window.ATLAS_LEARNING={"version":"3.3.0","points":{"LU 1":{"anchor":1,"compare":"LU 2","focus":{"he":"LU 2 קשורה לשקע שמתחת לעצם הבריח; LU 1 נמצאת נמוך יותר, בגובה המרווח הבין־צלעי הראשון. מעבר בין שתי הנקודות משנה גם את ציון הדרך, ולא רק את המספר.","en":"LU 2 refers to the infraclavicular depression; LU 1 is lower, at the first intercostal level. The anatomical reference changes along with the point number.","kind":"edited-comparison"},"shared":["Infraclavicular Fossa","Anterior Median Line"],"unique":["First Intercostal Space"],"primaryEn":"On the anterior thoracic region, at the same level as the first intercostal space, lateral to the infraclavicular fossa, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"LU 2":{"anchor":1,"compare":"LU 1","focus":{"he":"LU 2 קשורה לשקע שמתחת לעצם הבריח; LU 1 נמצאת נמוך יותר, בגובה המרווח הבין־צלעי הראשון. מעבר בין שתי הנקודות משנה גם את ציון הדרך, ולא רק את המספר.","en":"LU 2 refers to the infraclavicular depression; LU 1 is lower, at the first intercostal level. The anatomical reference changes along with the point number.","kind":"edited-comparison"},"shared":["Infraclavicular Fossa","Anterior Median Line"],"unique":["Coracoid Process Of The Scapula","Clavipectoral Triangle"],"primaryEn":"On the anterior thoracic region, in the depression of the infraclavicular fossa, medial to the coracoid process of the scapula, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"LU 3":{"anchor":1,"compare":"LU 4","focus":{"he":"שתי הנקודות מתוארות ביחס לשריר הדו־ראשי ולקפל בית השחי הקדמי. ההבחנה ביניהן היא המרחק מן הקפל: 3 לעומת 4 B-cun לכיוון המרפק.","en":"Both use the biceps and anterior axillary fold. The distinguishing measure from that fold is 3 versus 4 B-cun toward the elbow.","kind":"edited-comparison"},"shared":["Biceps Brachii Muscle","Anterior Axillary Fold"],"unique":[],"primaryEn":"On the anterolateral aspect of the arm, just lateral to the border of the biceps brachii muscle, 3 B-cun inferior to the anterior axillary fold.","primaryMeasures":["3 B-cun"]},"LU 4":{"anchor":1,"compare":"LU 3","focus":{"he":"שתי הנקודות מתוארות ביחס לשריר הדו־ראשי ולקפל בית השחי הקדמי. ההבחנה ביניהן היא המרחק מן הקפל: 3 לעומת 4 B-cun לכיוון המרפק.","en":"Both use the biceps and anterior axillary fold. The distinguishing measure from that fold is 3 versus 4 B-cun toward the elbow.","kind":"edited-comparison"},"shared":["Biceps Brachii Muscle","Anterior Axillary Fold"],"unique":[],"primaryEn":"On the anterolateral aspect of the arm, just lateral to the border of the biceps brachii muscle, 4 B-cun inferior to the anterior axillary fold.","primaryMeasures":["4 B-cun"]},"LU 5":{"anchor":1,"compare":"PC 3","focus":{"he":"קפל המרפק הוא ציון דרך משותף. LU 5 מתוארת בצד הרדיאלי של גיד הדו־ראשי, ו־PC 3 בצדו האולנרי. הגיד עוזר להבין את ההבדל בין צדי הקפל.","en":"Both use the elbow crease. LU 5 is described on the radial side of the biceps tendon and PC 3 on its ulnar side; the tendon distinguishes the sides.","kind":"edited-comparison"},"shared":["Biceps Brachii Tendon","Cubital Crease"],"unique":[],"primaryEn":"On the anterior aspect of the elbow, at the cubital crease, in the depression lateral to the biceps brachii tendon.","primaryMeasures":[]},"LU 6":{"anchor":1,"compare":"LU 7","focus":{"he":"העוגן הוא הקו בין LU 5 ל־LU 9. המידה 7 B-cun נמדדת מקפל שורש כף היד כלפי מעלה; אין לבלבל אותה עם המרחק מהמרפק.","en":"Use the LU 5–LU 9 line. The 7 B-cun measure starts at the wrist crease and runs proximally; it is not measured from the elbow.","kind":"edited-location"},"shared":["Palmar Wrist Crease"],"unique":[],"primaryEn":"On the anterolateral aspect of the forearm, on the line connecting LU5 with LU9, 7 B- cun superior to the palmar wrist crease.","primaryMeasures":["7 B-cun"]},"LU 7":{"anchor":1,"compare":"LU 8","focus":{"he":"המרחק מקפל שורש כף היד שונה: 1.5 B-cun ב־LU 7 לעומת 1 B-cun ב־LU 8. חשוב לקרוא גם את היחס לגידים ולזיז הרדיאלי, משום שהמרחק לבדו אינו מתאר את המיקום.","en":"The wrist-crease distances differ: 1.5 B-cun for LU 7 and 1 B-cun for LU 8. Their tendon and radial-styloid relationships also matter; distance alone is insufficient.","kind":"edited-comparison"},"shared":["Palmar Wrist Crease"],"unique":["Abductor Pollicis Longus Tendon","extensor pollicis brevis muscle"],"primaryEn":"On the radial aspect of the forearm, between the tendons of the abductor pollicis longus and the extensor pollicis brevis muscles, in the groove for the abductor pollicis longus tendon, 1.5 B-cun superior to the palmar wrist crease.","primaryMeasures":["1.5 B-cun"]},"LU 8":{"anchor":1,"compare":"LU 7","focus":{"he":"המרחק מקפל שורש כף היד שונה: 1.5 B-cun ב־LU 7 לעומת 1 B-cun ב־LU 8. חשוב לקרוא גם את היחס לגידים ולזיז הרדיאלי, משום שהמרחק לבדו אינו מתאר את המיקום.","en":"The wrist-crease distances differ: 1.5 B-cun for LU 7 and 1 B-cun for LU 8. Their tendon and radial-styloid relationships also matter; distance alone is insufficient.","kind":"edited-comparison"},"shared":["Palmar Wrist Crease"],"unique":["Radial Styloid Process","Radial Artery"],"primaryEn":"On the anterolateral aspect of the forearm, between the radial styloid process and the radial artery, 1 B-cun superior to the palmar wrist crease.","primaryMeasures":["1 B-cun"]},"LU 9":{"anchor":1,"compare":"LI 5","focus":{"he":"החישור ועצם הסירה ממקמים את LU 9 בצד הכפי־רדיאלי של שורש כף היד. LI 5 נמצאת בצד הגבי, בשקע ההרחה האנטומי. תחילה קובעים את פני היד, ואחר כך את השקע.","en":"Radius and scaphoid locate LU 9 on the palmar-radial wrist. LI 5 uses the dorsal anatomical snuffbox. Establish the hand surface before identifying the depression.","kind":"edited-location-3.3"},"shared":["Wrist","Radial Styloid Process"],"unique":["Scaphoid Bone","Abductor Pollicis Longus Tendon","Palmar Wrist Crease","Radial Artery"],"primaryEn":"On the anterolateral aspect of the wrist, between the radial styloid process and the scaphoid bone, in the depression ulnar to the abductor pollicis longus tendon.","primaryMeasures":[]},"LU 10":{"anchor":1,"compare":"LI 4","focus":{"he":"LU 10 מתוארת בצד הכפי, לצד אמצע עצם המסרק הראשונה; LI 4 נמצאת בגב כף היד בין עצמות המסרק הראשונה והשנייה. בחירת הצד הכפי או הגבי קודמת להשוואת הסימונים.","en":"LU 10 lies on the palm, radial to the first-metacarpal midpoint; LI 4 is on the dorsum between the first two metacarpals. Establish the hand surface before comparing the markers.","kind":"edited-comparison"},"shared":[],"unique":["First Metacarpal Bone"],"primaryEn":"On the palm, radial to the midpoint of the first metacarpal bone, at the border between the red and white flesh.","primaryMeasures":[]},"LU 11":{"anchor":0,"compare":"LI 1","focus":{"he":"שתי הרשומות משתמשות בפינת הציפורן, אך באצבעות שונות: LU 11 באגודל ו־LI 1 באצבע המורה. מזהים קודם את האצבע, ורק אחר כך את צד הציפורן.","en":"Both refer to a nail corner, but LU 11 uses the thumb and LI 1 the index finger. Identify the digit before identifying its nail side.","kind":"edited-comparison"},"shared":["Distal Phalanx"],"unique":["Thumb","Thumb Nail"],"primaryEn":"On the thumb, radial to the distal phalanx, 0.1 f-cun proximal-lateral to the radial corner of the thumb nail, at the intersection of the vertical line of the radial border and the horizontal line of the base of the thumb nail.","primaryMeasures":[]},"LI 1":{"anchor":0,"compare":"LU 11","focus":{"he":"שתי הרשומות משתמשות בפינת הציפורן, אך באצבעות שונות: LU 11 באגודל ו־LI 1 באצבע המורה. מזהים קודם את האצבע, ורק אחר כך את צד הציפורן.","en":"Both refer to a nail corner, but LU 11 uses the thumb and LI 1 the index finger. Identify the digit before identifying its nail side.","kind":"edited-comparison"},"shared":["Distal Phalanx"],"unique":["Index Finger","nail of manual digit 2"],"primaryEn":"On the index finger, radial to the distal phalanx, 0.1 f-cun proximal-lateral to the radial corner of the index fingernail, at the intersection of the vertical line of the radial border of the fingernail and the horizontal line of the base of the index fingernail.","primaryMeasures":[]},"LI 2":{"anchor":0,"compare":"LI 3","focus":{"he":"שתיהן בצד הרדיאלי של האצבע המורה. LI 2 דיסטלית למפרק המסרק־גליל השני, ואילו LI 3 פרוקסימלית לו. קו המפרק הוא ההבחנה המרכזית.","en":"Both are on the radial index-finger side. LI 2 is distal to the second metacarpophalangeal joint; LI 3 is proximal. The joint separates the two descriptions.","kind":"edited-comparison"},"shared":["Metacarpophalangeal Joint"],"unique":["Index Finger"],"primaryEn":"On the index finger, in the depression distal to the radial side of the second metacarpophalangeal joint, at the border between the red and white flesh.","primaryMeasures":[]},"LI 3":{"anchor":1,"compare":"LI 2","focus":{"he":"שתיהן בצד הרדיאלי של האצבע המורה. LI 2 דיסטלית למפרק המסרק־גליל השני, ואילו LI 3 פרוקסימלית לו. קו המפרק הוא ההבחנה המרכזית.","en":"Both are on the radial index-finger side. LI 2 is distal to the second metacarpophalangeal joint; LI 3 is proximal. The joint separates the two descriptions.","kind":"edited-comparison"},"shared":["Metacarpophalangeal Joint"],"unique":[],"primaryEn":"On the dorsum of the hand, in the depression radial and proximal to the second metacarpophalangeal joint.","primaryMeasures":[]},"LI 4":{"anchor":1,"compare":"LU 10","focus":{"he":"LU 10 מתוארת בצד הכפי, לצד אמצע עצם המסרק הראשונה; LI 4 נמצאת בגב כף היד בין עצמות המסרק הראשונה והשנייה. בחירת הצד הכפי או הגבי קודמת להשוואת הסימונים.","en":"LU 10 lies on the palm, radial to the first-metacarpal midpoint; LI 4 is on the dorsum between the first two metacarpals. Establish the hand surface before comparing the markers.","kind":"edited-comparison"},"shared":[],"unique":["Second Metacarpal Bone"],"primaryEn":"On the dorsum of the hand, radial to the midpoint of the second metacarpal bone.","primaryMeasures":[]},"LI 5":{"anchor":1,"compare":"LU 9","focus":{"he":"שקע ההרחה האנטומי נמצא בצד האגודל בגב שורש כף היד, מעבר לזיז החישור לכיוון האצבעות. LU 9 קשורה לצד הכפי; שתיהן רדיאליות, אך אינן באותו מבט.","en":"The anatomical snuffbox is on the thumb side of the dorsal wrist, distal to the radial styloid. LU 9 is palmar: sharing the radial side does not mean sharing the surface.","kind":"edited-location-3.3"},"shared":["Wrist","Radial Styloid Process"],"unique":["Dorsal Wrist Crease","Radial Fossa","Extensor Pollicis Longus Tendon","Extensor Pollicis Brevis Tendon"],"primaryEn":"On the posterolateral aspect of the wrist, at the radial side of the dorsal wrist crease, distal to the radial styloid process, in the depression of the anatomical snuffbox.","primaryMeasures":[]},"LI 6":{"anchor":1,"compare":"LI 7","focus":{"he":"הקו בין LI 5 ל־LI 11 משותף לכמה נקודות. כאן המרחק הוא 3 B-cun מעל קפל שורש כף היד הגבי; ב־LI 7 המרחק הוא 5 B-cun.","en":"Several points share the LI 5–LI 11 line. Here the level is 3 B-cun above the dorsal wrist crease; LI 7 uses 5 B-cun.","kind":"edited-location"},"shared":["Dorsal Wrist Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the forearm, on the line connecting LI5 with LI11, 3 B- cun superior to the dorsal wrist crease.","primaryMeasures":["3 B-cun"]},"LI 7":{"anchor":1,"compare":"LI 6","focus":{"he":"הבחינו בין גובה הנקודה לבין קו הייחוס שלה: LI 7 נמצאת על קו LI 5–LI 11, במרחק 5 B-cun מעל קפל שורש כף היד הגבי.","en":"Separate reference line from level: LI 7 uses the LI 5–LI 11 line, 5 B-cun above the dorsal wrist crease.","kind":"edited-location"},"shared":["Dorsal Wrist Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the forearm, on the line connecting LI5 with LI11, 5 B- cun superior to the dorsal wrist crease.","primaryMeasures":["5 B-cun"]},"LI 8":{"anchor":1,"compare":"LI 9","focus":{"he":"כאן מתחילים את קריאת המרחק מקפל המרפק: 4 B-cun לכיוון שורש כף היד. LI 9 נמצאת קרוב יותר למרפק, במרחק 3 B-cun ממנו.","en":"Read the distance from the elbow crease: 4 B-cun toward the wrist. LI 9 is nearer the elbow, 3 B-cun from that crease.","kind":"edited-location"},"shared":["Cubital Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the forearm, on the line connecting LI5 with LI11, 4 B- cun inferior to the cubital crease.","primaryMeasures":["4 B-cun"]},"LI 9":{"anchor":1,"compare":"LI 10","focus":{"he":"נקודת המוצא היא קפל המרפק, והכיוון הוא מטה לאורך האמה. המרחק המתואר הוא 3 B-cun; קו הייחוס מחבר את LI 5 עם LI 11.","en":"The reference is the elbow crease and the direction is distally along the forearm. The stated distance is 3 B-cun on the LI 5–LI 11 line.","kind":"edited-location"},"shared":["Cubital Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the forearm, on the line connecting LI5 with LI11, 3 B- cun inferior to the cubital crease.","primaryMeasures":["3 B-cun"]},"LI 10":{"anchor":1,"compare":"LI 11","focus":{"he":"LI 11 קשורה לקצה הצדדי של קפל המרפק. LI 10 נמצאת באמה, 2 B-cun דיסטלית ל־LI 11. מתחילים בזיהוי המרפק לפני שמפרשים את המרחק.","en":"LI 11 uses the lateral elbow-crease region. LI 10 is on the forearm, 2 B-cun distal to LI 11. Establish the elbow reference before interpreting the distance.","kind":"edited-comparison"},"shared":["Cubital Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the forearm, on the line connecting LI5 with LI11, 2 B- cun inferior to the cubital crease.","primaryMeasures":["2 B-cun"]},"LI 11":{"anchor":1,"compare":"LI 10","focus":{"he":"LI 11 קשורה לקצה הצדדי של קפל המרפק. LI 10 נמצאת באמה, 2 B-cun דיסטלית ל־LI 11. מתחילים בזיהוי המרפק לפני שמפרשים את המרחק.","en":"LI 11 uses the lateral elbow-crease region. LI 10 is on the forearm, 2 B-cun distal to LI 11. Establish the elbow reference before interpreting the distance.","kind":"edited-comparison"},"shared":["Cubital Crease"],"unique":["Lateral Epicondyle"],"primaryEn":"On the lateral aspect of the elbow, at the midpoint of the line connecting LU5 with the lateral epicondyle of the humerus.","primaryMeasures":[]},"LI 12":{"anchor":1,"compare":"LI 11","focus":{"he":"כאן העוגן הוא העילית העלי הצדדית של עצם הזרוע והשלוחה שמעליה. המיקום מתואר מעל העילית ולפני הרכס שמעליה; אין להסתפק בקפל המרפק המשמש להשוואה עם LI 11.","en":"Use the lateral humeral epicondyle and the ridge above it. The location is superior to the epicondyle and anterior to the ridge; the LI 11 elbow-crease reference alone is insufficient.","kind":"edited-location-3.3"},"shared":["Elbow","Lateral Epicondyle"],"unique":["Lateral Supraepicondylar Ridge"],"primaryEn":"On the posterolateral aspect of the elbow, superior to the lateral epicondyle of the humerus, anterior to the lateral supraepicondylar ridge.","primaryMeasures":[]},"LI 13":{"anchor":1,"compare":"LI 11","focus":{"he":"LI 13 שייכת לזרוע, מעל המרפק: 3 B-cun מעל קפל המרפק על הקו שבין LI 11 ל־LI 15. ההבחנה זרוע/אמה חשובה לפני השוואת המרחקים.","en":"LI 13 is on the arm above the elbow: 3 B-cun above the crease on the LI 11–LI 15 line. Establish arm versus forearm before comparing distances.","kind":"edited-location"},"shared":["Cubital Crease"],"unique":[],"primaryEn":"On the lateral aspect of the arm, on the line connecting LI11 with LI15, 3 B-cun supe- rior to the cubital crease.","primaryMeasures":["3 B-cun"]},"LI 14":{"anchor":1,"compare":"LI 15","focus":{"he":"LI 14 קשורה לגבול הקדמי של שריר הדלתא, 7 B-cun מעל LI 11. LI 15 קשורה לשקע שליד שיא הכתף. גבול שריר ושקע ליד עצם הם שני עוגנים שונים.","en":"LI 14 uses the anterior deltoid border, 7 B-cun above LI 11. LI 15 uses a depression by the acromion. Distinguish a muscle border from a depression beside bone.","kind":"edited-location-3.3"},"shared":[],"unique":["Arm","Deltoid Muscle"],"primaryEn":"On the lateral aspect of the arm, just anterior to the border of the deltoid muscle, 7 B-cun superior to LI11.","primaryMeasures":["7 B-cun"]},"LI 15":{"anchor":1,"compare":"TE 14","focus":{"he":"שתי הנקודות קשורות לכתף ולזיז שיא הכתף. LI 15 מתוארת בשקע הקדמי־תחתון ביחס אליו, ו־TE 14 בשקע האחורי־תחתון. מבט קדמי בלבד עלול להסתיר את ההבדל.","en":"Both concern the shoulder and acromion. LI 15 uses the anteroinferior depression and TE 14 the posteroinferior depression. An anterior view alone obscures the distinction.","kind":"edited-comparison"},"shared":["Acromion","Greater Tubercle Of The Humerus"],"unique":[],"primaryEn":"On the shoulder girdle, in the depression between the anterior end of lateral border of the acromion and the greater tubercle of the humerus.","primaryMeasures":[]},"LI 16":{"anchor":1,"compare":"SI 12","focus":{"he":"LI 16 נמצאת בשקע שבין הקצה הצדדי של עצם הבריח לקוץ השכמה. SI 12 קשורה לגומה שמעל קוץ השכמה. זיהוי שתי העצמות מונע בלבול בין השקע לגומה הרחבה.","en":"LI 16 uses the depression between the acromial clavicular end and the scapular spine. SI 12 uses the supraspinous fossa. Identify the two bones before confusing the depression with the broader fossa.","kind":"edited-location-3.3"},"shared":["Scapula"],"unique":["Shoulder Girdle","Clavicle","Suprascapular Fossa"],"primaryEn":"On the shoulder girdle, in the depression between the acromial end of the clavicle and the spine of the scapula.","primaryMeasures":[]},"LI 17":{"anchor":1,"compare":"ST 10","focus":{"he":"סחוס הטבעת קובע את הגובה. היחס לשריר מפנה הראש מבדיל בין הרשומות: LI 17 מאחורי גבולו, ו־ST 10 לפניו.","en":"The cricoid cartilage sets the level. The sternocleidomastoid relationship distinguishes the records: LI 17 is just posterior to its border, ST 10 just anterior.","kind":"edited-location"},"shared":["Cricoid Cartilage","Sternocleidomastoid Muscle"],"unique":[],"primaryEn":"On the anterior aspect of the neck, at the same level as the cricoid cartilage, just posterior to the border of the sternocleido- mastoid muscle.","primaryMeasures":[]},"LI 18":{"anchor":1,"compare":"ST 9","focus":{"he":"הגובה הוא הגבול העליון של סחוס התריס. במפלס זה LI 18 מתוארת בין הגבול הקדמי לאחורי של שריר מפנה הראש, ולא לפני השריר.","en":"The level is the superior thyroid-cartilage border. LI 18 lies between the anterior and posterior sternocleidomastoid borders rather than anterior to the muscle.","kind":"edited-location"},"shared":["Thyroid Cartilage","Sternocleidomastoid Muscle"],"unique":[],"primaryEn":"On the anterior aspect of the neck, at the same level as the superior border of the thyroid cartilage, between the anterior and posterior borders of the sternocleidomastoid muscle.","primaryMeasures":[]},"LI 19":{"anchor":1,"compare":"GV 26","focus":{"he":"GV 26 נמצאת בקו האמצע של הפילטרום, ו־LI 19 לצדו ומתחת לשוליים הצדדיים של הנחיר. לשתי הרשומות חלופה בגובה שונה; יש להשוות ראשי לראשי וחלופי לחלופי.","en":"GV 26 is on the philtrum midline; LI 19 lies beside it below the lateral nostril margin. Both have an alternative vertical level: compare primary with primary and alternative with alternative.","kind":"edited-comparison"},"shared":["Philtrum"],"unique":["Nostril"],"primaryEn":"On the face, at the same level as the midpoint of the philtrum, inferior to the lateral margin of the nostril.","primaryMeasures":[]},"LI 20":{"anchor":1,"compare":"ST 3","focus":{"he":"LI 20 משתמשת בחריץ האף־שפתי ובכנף האף. ST 3 משתמשת בקו שמתחת לאישון ובגובה השוליים התחתונים של כנף האף. דמיון בגובה אינו זהות במיקום הצדדי.","en":"LI 20 uses the nasolabial sulcus and nasal ala. ST 3 uses the line below the pupil and the inferior alar level. Similar height does not mean the same lateral position.","kind":"edited-comparison"},"shared":["Ala Of Nose"],"unique":["Nasolabial Sulcus"],"primaryEn":"On the face, in the nasolabial sulcus, at the same level as the midpoint of lateral border of the ala of the nose.","primaryMeasures":[]},"ST 1":{"anchor":1,"compare":"ST 2","focus":{"he":"ST 1 מתוארת בין גלגל העין לשוליים התחתונים של הארובה; ST 2 מתוארת בפתח התת־ארובתי שמתחתיהם. אלה שני ציוני דרך שונים סביב העין.","en":"ST 1 refers to the interval between the eyeball and inferior orbital margin; ST 2 to the infraorbital foramen below it. These are distinct orbital landmarks.","kind":"edited-comparison"},"shared":[],"unique":["Eyeball","Infraorbital Margin","Pupil"],"primaryEn":"On the face, between the eyeball and the infraorbital margin, directly inferior to the pupil.","primaryMeasures":[]},"ST 2":{"anchor":1,"compare":"ST 1","focus":{"he":"ST 1 מתוארת בין גלגל העין לשוליים התחתונים של הארובה; ST 2 מתוארת בפתח התת־ארובתי שמתחתיהם. אלה שני ציוני דרך שונים סביב העין.","en":"ST 1 refers to the interval between the eyeball and inferior orbital margin; ST 2 to the infraorbital foramen below it. These are distinct orbital landmarks.","kind":"edited-comparison"},"shared":[],"unique":["Infraorbital Foramen"],"primaryEn":"On the face, in the infraorbital foramen.","primaryMeasures":[]},"ST 3":{"anchor":1,"compare":"LI 20","focus":{"he":"LI 20 משתמשת בחריץ האף־שפתי ובכנף האף. ST 3 משתמשת בקו שמתחת לאישון ובגובה השוליים התחתונים של כנף האף. דמיון בגובה אינו זהות במיקום הצדדי.","en":"LI 20 uses the nasolabial sulcus and nasal ala. ST 3 uses the line below the pupil and the inferior alar level. Similar height does not mean the same lateral position.","kind":"edited-comparison"},"shared":["Ala Of Nose"],"unique":["Pupil"],"primaryEn":"On the face, directly inferior to the pupil, at the same level as the inferior border of the ala of the nose.","primaryMeasures":[]},"ST 4":{"anchor":1,"compare":"CV 24","focus":{"he":"זווית הפה היא העוגן של ST 4, עם היסט צדדי של 0.4 F-cun. CV 24 נמצאת בקו האמצע מתחת לשפה התחתונה. פינת הפה וקפל השפה־סנטר אינם אותו מבנה.","en":"ST 4 uses a 0.4 F-cun lateral offset from the mouth corner. CV 24 is midline below the lower lip. Distinguish the mouth angle from the mentolabial groove.","kind":"edited-location-3.3"},"shared":["Face"],"unique":["Mouth","Nasolabial Sulcus"],"primaryEn":"On the face, 0.4 f-cun lateral to the angle of the mouth.","primaryMeasures":[]},"ST 5":{"anchor":1,"compare":"ST 6","focus":{"he":"ST 5 מתוארת סמוך לשפת הלסת ולקצה הקדמי של שריר הלעיסה. ST 6 משתמשת בבליטת השריר כשהלסת נסגרת. יש להבחין בין שפת העצם לבין גוף השריר.","en":"ST 5 refers to the mandibular edge and anterior masseter border. ST 6 uses the muscle prominence when the jaw closes. Distinguish the bony edge from the muscle belly.","kind":"edited-comparison"},"shared":["Mandible","Masseter"],"unique":["Facial Artery"],"primaryEn":"On the face, anterior to the angle of the mandible, in the depression anterior to the masseter attachment, over the facial artery.","primaryMeasures":[]},"ST 6":{"anchor":1,"compare":"ST 5","focus":{"he":"ST 5 מתוארת סמוך לשפת הלסת ולקצה הקדמי של שריר הלעיסה. ST 6 משתמשת בבליטת השריר כשהלסת נסגרת. יש להבחין בין שפת העצם לבין גוף השריר.","en":"ST 5 refers to the mandibular edge and anterior masseter border. ST 6 uses the muscle prominence when the jaw closes. Distinguish the bony edge from the muscle belly.","kind":"edited-comparison"},"shared":["Mandible","Masseter"],"unique":[],"primaryEn":"On the face, one fingerbreadth (middle finger) anterosuperior to the angle of the mandible.","primaryMeasures":[]},"ST 7":{"anchor":1,"compare":"GB 3","focus":{"he":"השקע של ST 7 מתואר מתחת לאמצע קשת עצם הלחי ולצד מגרעת הלסת התחתונה. GB 3 נמצאת מעל הקשת. הקשת היא גבול ההשוואה, ולא קו האוזן.","en":"ST 7 is below the zygomatic-arch midpoint by the mandibular notch. GB 3 lies above the arch. The arch, rather than an ear-level line, separates the locations.","kind":"edited-location-3.3"},"shared":["Zygomatic Arch"],"unique":["Face","Mandibular Notch"],"primaryEn":"On the face, in the depression between the midpoint of the inferior border of the zygomatic arch and the mandibular notch.","primaryMeasures":[]},"ST 8":{"anchor":1,"compare":"GB 13","focus":{"he":"ST 8 משלבת חצי B-cun מעל קו השיער הקדמי בפינת המצח עם היסט של 4.5 B-cun מקו האמצע. שני הכיוונים נדרשים; גובה קו השיער לבדו אינו קובע את הצד.","en":"ST 8 combines half a B-cun above the anterior hairline at the forehead corner with a 4.5 B-cun lateral offset. Hairline height alone does not define the lateral position.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":["Forehead"],"primaryEn":"On the head, 0.5 B-cun directly superior to the anterior hairline at the corner of the forehead, 4.5 B-cun lateral to the anterior median line.","primaryMeasures":["0.5 B-cun","4.5 B-cun"]},"ST 9":{"anchor":1,"compare":"LI 18","focus":{"he":"בגובה הגבול העליון של סחוס התריס, ST 9 נמצאת לפני שריר מפנה הראש; LI 18 בין גבולות השריר. אזכור עורק התרדמה במקור הוא מידע אנטומי, ולא הנחיה לחיפוש באמצעות לחיצה.","en":"At the superior thyroid-cartilage level, ST 9 is anterior to sternocleidomastoid; LI 18 is between its borders. The carotid reference describes anatomy, not a pressure-based locating exercise.","kind":"edited-location-3.3"},"shared":["Neck","Thyroid Cartilage","Sternocleidomastoid Muscle"],"unique":["Common Carotid Artery"],"primaryEn":"In the anterior region of the neck, at the same level as the superior border of the thyroid cartilage, anterior to the sternocleidomastoid muscle, over the common carotid artery.","primaryMeasures":[]},"ST 10":{"anchor":1,"compare":"LI 17","focus":{"he":"בגובה סחוס הטבעת, ST 10 קשורה לגבול הקדמי של שריר מפנה הראש. LI 17 משתמשת באותו גובה אך ביחס אחורי לשריר.","en":"At cricoid level, ST 10 is just anterior to the sternocleidomastoid border. LI 17 uses the same level with a posterior muscle relationship.","kind":"edited-location"},"shared":["Cricoid Cartilage","Sternocleidomastoid Muscle"],"unique":[],"primaryEn":"In the anterior region of the neck, at the same level as the cricoid cartilage, just anterior to the border of the sternocleidomastoid muscle.","primaryMeasures":[]},"ST 11":{"anchor":1,"compare":"ST 12","focus":{"he":"ST 11 משתמשת בשקע הקטן מעל הקצה הסטרנלי של עצם הבריח, בין שני ראשי שריר מפנה הראש. ST 12 משתמשת בשקע העל־בריחי הגדול והצדדי יותר.","en":"ST 11 uses the lesser supraclavicular fossa above the sternal clavicular end, between the two sternocleidomastoid heads. ST 12 uses the larger, more lateral supraclavicular fossa.","kind":"edited-location-3.3"},"shared":["Neck","Clavicle"],"unique":["Lesser Supraclavicular Fossa","Sternocleidomastoid Muscle"],"primaryEn":"In the anterior region of the neck, in the lesser supraclavicular fossa, superior to the sternal end of the clavicle, in the depression between the sternal and clavicular heads of the sternocleidomastoid muscle.","primaryMeasures":[]},"ST 12":{"anchor":1,"compare":"ST 13","focus":{"he":"עצם הבריח מפרידה בין ההגדרות: ST 12 בשקע שמעליה ו־ST 13 מתחתיה, שתיהן עם היסט של 4 B-cun מקו האמצע. קובעים תחילה מעל או מתחת לעצם.","en":"The clavicle separates the definitions: ST 12 is above it and ST 13 below it, both with a 4 B-cun midline offset. First establish which side of the bone is described.","kind":"edited-location-3.3"},"shared":["Anterior Median Line","Clavicle"],"unique":["Neck","Greater Supraclavicular Fossa"],"primaryEn":"In the anterior region of the neck, in the greater supraclavicular fossa, 4 B-cun lateral to the anterior median line, in the depression superior to the clavicle.","primaryMeasures":["4 B-cun"]},"ST 13":{"anchor":1,"compare":"ST 14","focus":{"he":"ST 13 מתוארת מתחת לעצם הבריח, 4 B-cun מקו האמצע. ST 14 משתמשת במרווח הבין־צלעי הראשון. אין להחליף את השקע התת־בריחי במרווח שבין הצלעות.","en":"ST 13 is below the clavicle at a 4 B-cun midline offset. ST 14 uses the first intercostal space. The infraclavicular region and an intercostal space are distinct references.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Anterior Median Line"],"unique":["Clavicle"],"primaryEn":"In the anterior thoracic region, inferior to the clavicle, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"ST 14":{"anchor":1,"compare":"ST 15","focus":{"he":"המרווח הראשון וההיסט של 4 B-cun מגדירים את ST 14. ST 15 שומרת על ההיסט אך עוברת למרווח השני. מספר המרווח מציין את הרווח שמתחת לצלע בעלת אותו מספר.","en":"The first intercostal space and a 4 B-cun offset define ST 14. ST 15 keeps the offset but uses the second space. A space is numbered for the rib above it.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Anterior Median Line"],"unique":["First Intercostal Space"],"primaryEn":"In the anterior thoracic region, in the first intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"ST 15":{"anchor":1,"compare":"SP 20","focus":{"he":"ST 15 ו־SP 20 משתמשות במרווח הבין־צלעי השני; ההבדל הוא ההיסט מקו האמצע: 4 לעומת 6 B-cun. המרווח מעוקל, ולכן הסכמה אינה סרגל אופקי על הגוף.","en":"ST 15 and SP 20 share the second intercostal space, with offsets of 4 and 6 B-cun respectively. The space curves; a schematic horizontal level is not a body ruler.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Second Intercostal Space","Anterior Median Line"],"unique":["Second Rib","Sternal Angle"],"primaryEn":"In the anterior thoracic region, in the sec- ond intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"ST 16":{"anchor":1,"compare":"SP 19","focus":{"he":"המרווח הבין־צלעי השלישי משותף לשתי הרשומות. ST 16 משתמשת בהיסט של 4 B-cun ו־SP 19 בהיסט של 6 B-cun. ההבחנה היא רוחבית בתוך אותו מרווח.","en":"Both records use the third intercostal space. ST 16 has a 4 B-cun offset and SP 19 a 6 B-cun offset. Their distinction is lateral position within the same space.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Third Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the third intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"ST 17":{"anchor":1,"compare":"LR 14","focus":{"he":"ההגדרה הראשית משתמשת במרכז הפטמה כציון הדרך. אין להחליף את ציון הדרך הזה אוטומטית במספר קבוע של מרווח בין־צלעי לכל גוף.","en":"The primary definition uses the nipple centre. Do not automatically replace this landmark with a fixed intercostal-space number for every body.","kind":"edited-location"},"shared":["Nipple"],"unique":[],"primaryEn":"In the anterior thoracic region, at the centre of the nipple.","primaryMeasures":[]},"ST 18":{"anchor":1,"compare":"SP 17","focus":{"he":"ST 18 מתוארת במרווח הבין־צלעי החמישי, 4 B-cun מקו האמצע; SP 17 באותו מרווח, 6 B-cun ממנו. קפל שד או קו פטמה אינם מחליפים זיהוי של המרווח המתואר.","en":"ST 18 uses the fifth intercostal space at 4 B-cun from the midline; SP 17 uses 6 B-cun in that space. A breast fold or nipple line does not replace the stated intercostal reference.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fifth Intercostal Space","Anterior Median Line"],"unique":["Nipple Line"],"primaryEn":"In the anterior thoracic region, in the fifth intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"ST 19":{"anchor":1,"compare":"CV 14","focus":{"he":"מרכז הטבור קובע את הגובה: 6 B-cun מעליו. ST 19 נמצאת 2 B-cun לצד קו האמצע, ואילו CV 14 בקו האמצע באותו גובה. אין למדוד את שתי המידות באותו כיוון.","en":"The umbilicus sets the level, 6 B-cun superiorly. ST 19 lies 2 B-cun lateral to the midline; CV 14 is midline at that level. The two measures describe different axes.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":["Infrasternal Angle","Rib"],"primaryEn":"On the upper abdomen, 6 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun","2 B-cun"]},"ST 20":{"anchor":1,"compare":"CV 13","focus":{"he":"ST 20 נמצאת בגובה CV 13, 5 B-cun מעל הטבור, אך 2 B-cun לצד קו האמצע. ביחס ל־ST 19 היא נמוכה יותר; ההיסט הצדדי נשאר קבוע.","en":"ST 20 shares CV 13’s level, 5 B-cun above the umbilicus, but lies 2 B-cun lateral. It is lower than ST 19 while retaining the same lateral offset.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 5 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["5 B-cun","2 B-cun"]},"ST 21":{"anchor":1,"compare":"CV 12","focus":{"he":"כאן הגובה הוא 4 B-cun מעל הטבור וההיסט הצדדי הוא 2 B-cun. CV 12 מספקת השוואה בקו האמצע באותו גובה. תחילה מזהים גובה, ואז את העמודה הצדדית.","en":"Here the level is 4 B-cun above the umbilicus and the lateral offset is 2 B-cun. CV 12 provides the midline comparison at that level. Establish level before lateral column.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 4 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun","2 B-cun"]},"ST 22":{"anchor":1,"compare":"KI 18","focus":{"he":"ST 22 ו־KI 18 נמצאות 3 B-cun מעל הטבור. ST 22 מרוחקת 2 B-cun מקו האמצע ו־KI 18 חצי B-cun בלבד; אין לבלבל שיתוף גובה עם שיתוף מסלול.","en":"ST 22 and KI 18 lie 3 B-cun above the umbilicus. Their lateral offsets are 2 and 0.5 B-cun. Sharing a level does not mean occupying the same channel column.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 3 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["3 B-cun","2 B-cun"]},"ST 23":{"anchor":1,"compare":"KI 17","focus":{"he":"גובה שתי הנקודות הוא 2 B-cun מעל הטבור. ST 23 בעמודה של 2 B-cun מקו האמצע, ו־KI 17 בעמודה של חצי B-cun. ההשוואה היא בין העמודות ולא בין מספרי הנקודות.","en":"Both points are 2 B-cun above the umbilicus. ST 23 uses the 2 B-cun lateral column and KI 17 the 0.5 B-cun column. Compare columns rather than point numbers.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 2 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun","2 B-cun"]},"ST 24":{"anchor":1,"compare":"CV 9","focus":{"he":"ST 24 נמצאת 1 B-cun מעל הטבור ו־2 B-cun לצד קו האמצע. CV 9 מייצגת את אותו גובה בקו האמצע. אין להחליף בין הגובה מעל הטבור למרחק ממנו הצדה.","en":"ST 24 is 1 B-cun above the umbilicus and 2 B-cun lateral to the midline. CV 9 is midline at that level. Keep the superior and lateral distances separate.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 1 B-cun superior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["1 B-cun","2 B-cun"]},"ST 25":{"anchor":1,"compare":"SP 15","focus":{"he":"הטבור קובע כאן את הגובה ללא היסט מעלה או מטה. ST 25 נמצאת 2 B-cun לצדו, ו־SP 15 במרחק 4 B-cun. הטבור הוא נקודת ייחוס, ולא אחת הנקודות הצדדיות.","en":"The umbilicus sets the level with no superior or inferior offset. ST 25 is 2 B-cun lateral and SP 15 is 4 B-cun lateral. The umbilicus is their reference, not either lateral point.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus"],"unique":[],"primaryEn":"On the upper abdomen, 2 B-cun lateral to the centre of the umbilicus.","primaryMeasures":["2 B-cun"]},"ST 26":{"anchor":1,"compare":"KI 15","focus":{"he":"שתי הנקודות נמצאות 1 B-cun מתחת לטבור. ההיסט הצדדי שונה: 2 B-cun ב־ST 26 וחצי B-cun ב־KI 15. ״מתחת לטבור״ מתאר גובה בלבד.","en":"Both points are 1 B-cun below the umbilicus. ST 26 lies 2 B-cun lateral and KI 15 lies 0.5 B-cun lateral. “Below the umbilicus” specifies only their level.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 1 B-cun inferior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["1 B-cun","2 B-cun"]},"ST 27":{"anchor":1,"compare":"CV 5","focus":{"he":"ST 27 מתוארת 2 B-cun מתחת לטבור ו־2 B-cun מקו האמצע. CV 5 נמצאת בקו האמצע באותו גובה. שוויון המספרים בשתי המידות אינו הופך אותן לאותו כיוון.","en":"ST 27 is 2 B-cun below the umbilicus and 2 B-cun lateral to the midline. CV 5 is midline at that level. Equal numbers still describe different directions.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 2 B-cun inferior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun","2 B-cun"]},"ST 28":{"anchor":1,"compare":"CV 4","focus":{"he":"הגובה של ST 28 הוא 3 B-cun מתחת לטבור, בגובה CV 4; ההיסט מקו האמצע הוא 2 B-cun. CV 4 עוזרת לקרוא את שורת הגובה בלי לשנות את העמודה של ST.","en":"ST 28 is 3 B-cun below the umbilicus, level with CV 4, and 2 B-cun lateral. CV 4 helps identify the level without changing the ST lateral column.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 3 B-cun inferior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["3 B-cun","2 B-cun"]},"ST 29":{"anchor":1,"compare":"CV 3","focus":{"he":"ST 29 נמצאת 4 B-cun מתחת לטבור ו־2 B-cun לצד קו האמצע. CV 3 בקו האמצע באותו גובה. זהו גובה שמעל הגבול העליון של מאחה הערווה, ולא הגבול עצמו.","en":"ST 29 is 4 B-cun below the umbilicus and 2 B-cun lateral, level with midline CV 3. This is superior to the upper pubic-symphysis border, not at the border itself.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 4 B-cun inferior to the centre of the umbilicus, 2 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun","2 B-cun"]},"ST 30":{"anchor":1,"compare":"CV 2","focus":{"he":"הגבול העליון של מאחה הערווה קובע את הגובה. ST 30 נמצאת 2 B-cun הצדה ו־CV 2 בקו האמצע. המקור מזכיר את עורק הירך; הסימון אינו הוראה ללחיצה באזור.","en":"The superior pubic-symphysis border sets the level. ST 30 is 2 B-cun lateral and CV 2 midline. The source mentions the femoral artery; the marker is not an instruction to apply pressure.","kind":"edited-location-3.3"},"shared":["Pubic Symphysis","Anterior Median Line"],"unique":["Groin Region","Femoral Artery"],"primaryEn":"In the groin region, at the same level as the superior border of the pubic symphysis, 2 B-cun lateral to the anterior median line, over the femoral artery.","primaryMeasures":["2 B-cun"]},"ST 31":{"anchor":1,"compare":"ST 32","focus":{"he":"ST 31 מוגדרת בשקע בין שלושה שרירים בחלק העליון של הירך: הישר הירכי, החייטים ומותח המחתלה הרחבה. ST 32 משתמשת במדידה מבסיס הפיקה. אין לצמצם את ST 31 למרחק מהברך בלבד.","en":"ST 31 uses the proximal thigh depression between rectus femoris, sartorius and tensor fasciae latae. ST 32 uses a patellar-base measurement. A knee distance alone does not describe ST 31.","kind":"edited-location-3.3"},"shared":["Thigh","Patella","Anterior Superior Iliac Spine"],"unique":["Rectus Femoris Muscle","Sartorius Muscle","Tensor Fasciae Latae Muscle","Pubic Symphysis"],"primaryEn":"On the anterior aspect of the thigh, in the depression among three muscles: the proximal portion of the rectus femoris muscle, the sartorius muscle and the tensor fasciae latae muscle.","primaryMeasures":[]},"ST 32":{"anchor":1,"compare":"ST 31","focus":{"he":"שני קצות קו הייחוס הם הקצה הצדדי של בסיס הפיקה וקוץ הכסל הקדמי העליון. את 6 B-cun מודדים בתיאור מבסיס הפיקה כלפי מעלה.","en":"The reference line joins the lateral patellar base and the ASIS. The stated 6 B-cun distance runs superiorly from the patellar base.","kind":"edited-location"},"shared":["Patella","Anterior Superior Iliac Spine"],"unique":[],"primaryEn":"On the anterolateral aspect of the thigh, on the line connecting the lateral end of the base of the patella with the anterior superior iliac spine, 6 B-cun superior to the base of the patella.","primaryMeasures":["6 B-cun"]},"ST 33":{"anchor":1,"compare":"ST 34","focus":{"he":"בסיס הפיקה הוא מוצא המרחק: ST 33 נמצאת 3 B-cun מעליו ולצד גיד הישר הירכי. ST 34 נמוכה ממנה ב־1 B-cun. בסיס הפיקה הוא גבולה העליון, לא הקצה התחתון.","en":"ST 33 lies 3 B-cun above the patellar base, lateral to the rectus-femoris tendon. ST 34 is 1 B-cun lower. The patellar base is the superior border, not its lower tip.","kind":"edited-location-3.3"},"shared":["Thigh","Tendon Of Quadriceps Femoris","Patella"],"unique":[],"primaryEn":"On the anterolateral aspect of the thigh, lateral to the rectus femoris tendon, 3 B-cun superior to the base of the patella.","primaryMeasures":["3 B-cun"]},"ST 34":{"anchor":1,"compare":"ST 33","focus":{"he":"השקע שבין השריר הרחב הצדדי לגבול הצדדי של גיד הישר הירכי מגדיר את הצד. הגובה הוא 2 B-cun מעל בסיס הפיקה, לעומת 3 B-cun ב־ST 33.","en":"The interval between vastus lateralis and the lateral rectus-femoris tendon border defines the side. The level is 2 B-cun above the patellar base, compared with 3 B-cun for ST 33.","kind":"edited-location-3.3"},"shared":["Thigh","Tendon Of Quadriceps Femoris","Patella"],"unique":["Vastus Lateralis Muscle"],"primaryEn":"On the anterolateral aspect of the thigh, between the vastus lateralis muscle and the lateral border of the rectus femoris tendon, 2 B-cun superior to the base of the patella.","primaryMeasures":["2 B-cun"]},"ST 35":{"anchor":1,"compare":"ST 36","focus":{"he":"ST 35 משתמשת בשקע שלצד רצועת הפיקה. ST 36 נמצאת בשוק, 3 B-cun מתחת ל־ST 35. מזהים את מפרק הברך בנפרד מגוף השוק.","en":"ST 35 uses the depression beside the patellar ligament. ST 36 lies on the leg, 3 B-cun below ST 35. Distinguish the knee reference from the lower-leg region.","kind":"edited-comparison"},"shared":[],"unique":["Patellar Ligament","Patella"],"primaryEn":"On the anterior aspect of the knee, in the depression lateral to the patellar ligament.","primaryMeasures":[]},"ST 36":{"anchor":1,"compare":"ST 35","focus":{"he":"ST 35 משתמשת בשקע שלצד רצועת הפיקה. ST 36 נמצאת בשוק, 3 B-cun מתחת ל־ST 35. מזהים את מפרק הברך בנפרד מגוף השוק.","en":"ST 35 uses the depression beside the patellar ligament. ST 36 lies on the leg, 3 B-cun below ST 35. Distinguish the knee reference from the lower-leg region.","kind":"edited-comparison"},"shared":[],"unique":["Tibialis Anterior Muscle"],"primaryEn":"On the anterior aspect of the leg, on the line connecting ST35 with ST41, 3 B-cun inferior to ST35.","primaryMeasures":["3 B-cun"]},"ST 37":{"anchor":1,"compare":"ST 39","focus":{"he":"שתי הרשומות משתמשות ב־ST 35 כייחוס, אך במרחקים של 6 ו־9 B-cun מתחתיה. סדר המספור אינו מייצג מרווחים שווים בין כל נקודות המסלול.","en":"Both use ST 35 as a reference, at 6 and 9 B-cun below it respectively. Point numbering does not imply equal spacing throughout the channel.","kind":"edited-comparison"},"shared":["Tibialis Anterior Muscle"],"unique":[],"primaryEn":"On the anterior aspect of the leg, on the line connecting ST35 with ST41, 6 B-cun inferior to ST35.","primaryMeasures":["6 B-cun"]},"ST 38":{"anchor":1,"compare":"ST 40","focus":{"he":"שתיהן באזור אמצע השוק, אך ST 40 מתוארת לטרלית ל־ST 38. לצד הגובה, בודקים את היחס לשריר השוקתי הקדמי ולגבול השוקה.","en":"Both are around the middle of the lower leg; ST 40 is described lateral to ST 38. Read the tibialis-anterior and tibial-border relationship as well as the level.","kind":"edited-comparison"},"shared":["Tibialis Anterior Muscle"],"unique":[],"primaryEn":"On the anterior aspect of the leg, on the line connecting ST35 with ST41, 8 B-cun inferior to ST35.","primaryMeasures":["8 B-cun"]},"ST 39":{"anchor":1,"compare":"ST 37","focus":{"he":"שתי הרשומות משתמשות ב־ST 35 כייחוס, אך במרחקים של 6 ו־9 B-cun מתחתיה. סדר המספור אינו מייצג מרווחים שווים בין כל נקודות המסלול.","en":"Both use ST 35 as a reference, at 6 and 9 B-cun below it respectively. Point numbering does not imply equal spacing throughout the channel.","kind":"edited-comparison"},"shared":["Tibialis Anterior Muscle"],"unique":[],"primaryEn":"On the anterior aspect of the leg, on the line connecting ST35 with ST41, 9 B-cun inferior to ST35.","primaryMeasures":["9 B-cun"]},"ST 40":{"anchor":1,"compare":"ST 38","focus":{"he":"שתיהן באזור אמצע השוק, אך ST 40 מתוארת לטרלית ל־ST 38. לצד הגובה, בודקים את היחס לשריר השוקתי הקדמי ולגבול השוקה.","en":"Both are around the middle of the lower leg; ST 40 is described lateral to ST 38. Read the tibialis-anterior and tibial-border relationship as well as the level.","kind":"edited-comparison"},"shared":["Tibialis Anterior Muscle"],"unique":["Lateral Malleolus"],"primaryEn":"On the anterolateral aspect of the leg, lateral border of the tibialis anterior muscle, 8 B-cun superior to the prominence of the lateral malleolus.","primaryMeasures":["8 B-cun"]},"ST 41":{"anchor":1,"compare":"ST 42","focus":{"he":"ST 41 נמצאת בקדמת מפרק הקרסול בין גידי פושט הבוהן הארוך ופושט האצבעות הארוך. ST 42 קדמית יותר בכף הרגל ומשתמשת בחיבור עצמות. גיד ומפרק גרמי אינם עוגנים חלופיים זה לזה.","en":"ST 41 uses the anterior ankle interval between extensor hallucis longus and extensor digitorum longus tendons. ST 42 uses a bony junction farther onto the foot. Tendons and bone joints are distinct references.","kind":"edited-location-3.3"},"shared":[],"unique":["Ankle","Ankle Joint","Tendon of extensor hallucis longus","Tendon of extensor digitorum longus","LATERAL MALLEOLUS"],"primaryEn":"On the anterior aspect of the ankle, in the depression at the centre of the front surface of the ankle joint, between the tendons of extensor hallucis longus and extensor digitorum longus.","primaryMeasures":[]},"ST 42":{"anchor":1,"compare":"LR 3","focus":{"he":"העוגן של ST 42 הוא החיבור בין בסיס המסרק השני לעצם היתד האמצעית. LR 3 נמצאת במרווח שבין המסרקים הראשון והשני. בסיס עצם ומרווח בין עצמות אינם אותו מקום.","en":"ST 42 uses the second-metatarsal-base/intermediate-cuneiform joint. LR 3 uses the first–second metatarsal interval. Distinguish a bone’s base joint from a space between adjacent bones.","kind":"edited-location-3.3"},"shared":["Foot","Second Metatarsal Bone","Dorsalis Pedis Artery"],"unique":["Intermediate Cuneiform Bone"],"primaryEn":"On the dorsum of the foot, at the joint of the base of the second metatarsal bone and the intermediate cuneiform bone, over the dorsalis pedis artery.","primaryMeasures":[]},"ST 43":{"anchor":1,"compare":"LR 3","focus":{"he":"LR 3 מתוארת בין עצמות המסרק הראשונה והשנייה. ST 43 בין השנייה לשלישית. ספירת העצמות מן הבוהן מבדילה בין שני המרווחים בגב כף הרגל.","en":"LR 3 uses the first–second metatarsal interval; ST 43 the second–third interval. Counting bones from the great toe separates these dorsal-foot spaces.","kind":"edited-comparison"},"shared":["Second Metatarsal Bone"],"unique":["Third Metatarsal Bone","metatarsophalangeal joint of pedal digit 2"],"primaryEn":"On the dorsum of the foot, between the second and third metatarsal bones, in the depression proximal to the second metatarsophalangeal joint.","primaryMeasures":[]},"ST 44":{"anchor":1,"compare":"LR 2","focus":{"he":"ST 44 משתמשת ברווח שבין האצבעות השנייה והשלישית; LR 2 ברווח שבין הבוהן לאצבע השנייה. הספירה מתחילה בבוהן, גם כשהאיור מוצג מהצד.","en":"ST 44 uses the second–third toe interval; LR 2 the great–second toe interval. Toe numbering starts with the great toe regardless of the viewing direction.","kind":"edited-comparison"},"shared":["Second Toe"],"unique":["Third Toe"],"primaryEn":"On the dorsum of the foot, between the second and third toes, posterior to the web margin, at the border between the red and white flesh.","primaryMeasures":[]},"ST 45":{"anchor":0,"compare":"GB 44","focus":{"he":"ST 45 קשורה לפינה הצדדית של ציפורן האצבע השנייה בכף הרגל, 0.1 F-cun לכיוון שורש האצבע והצדה. GB 44 משתמשת באצבע הרביעית. סופרים אצבעות מן הבוהן לפני בחירת הפינה.","en":"ST 45 uses the lateral second-toenail corner with a 0.1 F-cun proximal-lateral offset. GB 44 uses the fourth toe. Count digits from the great toe before selecting the nail corner.","kind":"edited-location-3.3"},"shared":["Distal Phalanx"],"unique":["Second Toe","Nail Of The Second Toe"],"primaryEn":"On the second toe, lateral to the distal phalanx, 0.1 f-cun proximal-lateral to the lateral corner of the second toenail, at the intersection of the vertical line of the lateral border and the horizontal line of the base of the second toenail.","primaryMeasures":[]},"SP 1":{"anchor":0,"compare":"LR 1","focus":{"he":"שתיהן בבוהן: SP 1 בצד המדיאלי ו־LR 1 בצד הלטרלי של הציפורן. זיהוי שתי פינות אותה ציפורן חשוב יותר מזכירת צד ימין או שמאל בתמונה.","en":"Both use the great toe: SP 1 its medial nail side and LR 1 its lateral nail side. Distinguish the nail corners rather than memorizing picture left and right.","kind":"edited-comparison"},"shared":["Great Toe","Distal Phalanx","Toenail"],"unique":[],"primaryEn":"On the great toe, medial to the distal phalanx, 0.1 f-cun proximal-medial to the me- dial corner of the toenail, at the intersection of the vertical line of the medial border and horizontal line of the base of the toenail.","primaryMeasures":[]},"SP 2":{"anchor":0,"compare":"SP 3","focus":{"he":"SP 2 דיסטלית למפרק המסרק־גליל הראשון, ו־SP 3 פרוקסימלית לו. שתיהן מתוארות במעבר שבין עור הגב לעור הסוליה בצד הפנימי של כף הרגל.","en":"SP 2 is distal and SP 3 proximal to the first metatarsophalangeal joint. Both use the dorsal–plantar skin transition on the medial foot.","kind":"edited-comparison"},"shared":["First Metatarsophalangeal Joint"],"unique":["Great Toe"],"primaryEn":"On the great toe, in the depression distal to the first metatarsophalangeal joint, at the border between the red and white flesh.","primaryMeasures":[]},"SP 3":{"anchor":1,"compare":"SP 2","focus":{"he":"SP 2 דיסטלית למפרק המסרק־גליל הראשון, ו־SP 3 פרוקסימלית לו. שתיהן מתוארות במעבר שבין עור הגב לעור הסוליה בצד הפנימי של כף הרגל.","en":"SP 2 is distal and SP 3 proximal to the first metatarsophalangeal joint. Both use the dorsal–plantar skin transition on the medial foot.","kind":"edited-comparison"},"shared":["First Metatarsophalangeal Joint"],"unique":[],"primaryEn":"On the medial aspect of the foot, in the depression proximal to the first metatarsophalangeal joint, at the border between the red and white flesh.","primaryMeasures":[]},"SP 4":{"anchor":1,"compare":"SP 3","focus":{"he":"SP 4 קשורה לבסיס המסרק הראשון בצד הפנימי של כף הרגל; SP 3 קרובה יותר למפרק המסרק־גליל הראשון. חשוב להבחין בין בסיס המסרק, הפונה לקרסול, לבין ראשו, הפונה לבוהן.","en":"SP 4 uses the first-metatarsal base on the medial foot; SP 3 is nearer the first metatarsophalangeal joint. Distinguish the ankle-facing base from the toe-facing head.","kind":"edited-location-3.3"},"shared":["Foot"],"unique":["First Metatarsal Bone"],"primaryEn":"On the medial aspect of the foot, antero- inferior to the base of the first metatarsal bone, at the border between the red and white flesh.","primaryMeasures":[]},"SP 5":{"anchor":1,"compare":"KI 6","focus":{"he":"SP 5 נמצאת לפני ומתחת לפטישון הפנימי, בין הפטישון לגבשושית עצם הסירה. KI 6 מתוארת מתחת לפטישון. היחס הקדמי הוא ההבחנה החשובה בין שני התיאורים.","en":"SP 5 is anterior and inferior to the medial malleolus, between it and the navicular tuberosity. KI 6 is inferior to the malleolus. The anterior relationship distinguishes the descriptions.","kind":"edited-location-3.3"},"shared":["Foot","Medial Malleolus"],"unique":["Navicular Bone"],"primaryEn":"On the medial aspect of the foot, anteroinferior to the medial malleolus, in the depression midway between the tuberosity of the navicular bone and the prominence of the medial malleolus.","primaryMeasures":[]},"SP 6":{"anchor":1,"compare":"SP 7","focus":{"he":"בשתיהן ציון הדרך הוא הגבול האחורי של השוקה. ההבדל הוא הגובה מעל הפטישון הפנימי: 3 B-cun ב־SP 6 ו־6 B-cun ב־SP 7.","en":"Both refer to the posterior tibial border. Their heights above the medial malleolus differ: 3 B-cun for SP 6 and 6 B-cun for SP 7.","kind":"edited-comparison"},"shared":["Tibia","Medial Malleolus"],"unique":[],"primaryEn":"On the tibial aspect of the leg, posterior to the medial border of the tibia, 3 B-cun superior to the prominence of the medial malleolus.","primaryMeasures":["3 B-cun"]},"SP 7":{"anchor":1,"compare":"SP 6","focus":{"he":"בשתיהן ציון הדרך הוא הגבול האחורי של השוקה. ההבדל הוא הגובה מעל הפטישון הפנימי: 3 B-cun ב־SP 6 ו־6 B-cun ב־SP 7.","en":"Both refer to the posterior tibial border. Their heights above the medial malleolus differ: 3 B-cun for SP 6 and 6 B-cun for SP 7.","kind":"edited-comparison"},"shared":["Tibia","Medial Malleolus"],"unique":[],"primaryEn":"On the tibial aspect of the leg, posterior to the medial border of the tibia, 6 B-cun superior to the prominence of the medial malleolus.","primaryMeasures":["6 B-cun"]},"SP 8":{"anchor":1,"compare":"SP 9","focus":{"he":"SP 9 היא נקודת הייחוס למרחק של SP 8: שלושה B-cun כלפי מטה, מאחורי הגבול הפנימי של השוקה. אין למדוד כאן את שלוש היחידות מהפטישון שבקרסול.","en":"SP 8 is measured 3 B-cun inferiorly from SP 9, posterior to the medial tibial border. The ankle malleolus is not the starting landmark for this three-unit measure.","kind":"edited-location-3.3"},"shared":["Leg","Tibia"],"unique":["Patella","Medial Malleolus"],"primaryEn":"On the tibial aspect of the leg, posterior to the medial border of the tibia, 3 B-cun inferior to SP9.","primaryMeasures":["3 B-cun"]},"SP 9":{"anchor":1,"compare":"LR 8","focus":{"he":"SP 9 משתמשת בגבול התחתון של הקונדיל הפנימי של השוקה. LR 8 מתייחסת לקצה הפנימי של קפל הברך ולגידים. עצם וקפל אינם אותו ציון דרך.","en":"SP 9 uses the inferior border of the medial tibial condyle. LR 8 uses the medial knee-crease end and tendons. A bony margin and a crease are different references.","kind":"edited-comparison"},"shared":[],"unique":["Medial Condyle Of The Tibia","Tibia","Knee Joint"],"primaryEn":"On the tibial aspect of the leg, in the depression between the inferior border of the medial condyle of the tibia and the medial border of the tibia.","primaryMeasures":[]},"SP 10":{"anchor":1,"compare":"ST 34","focus":{"he":"שתי הרשומות משתמשות בגובה של 2 B-cun מעל בסיס הפיקה. SP 10 קשורה לבליטת השריר הרחב הפנימי, ו־ST 34 לצד החיצוני של הירך. הגובה המשותף אינו מבטל את הבדל הצדדים.","en":"Both records use a level 2 B-cun above the patellar base. SP 10 uses the vastus-medialis bulge; ST 34 uses the lateral thigh. Their shared level does not erase the side difference.","kind":"edited-location-3.3"},"shared":["Thigh","Patella"],"unique":["Vastus Medialis Muscle"],"primaryEn":"On the anteromedial aspect of the thigh, on the bulge of the vastus medialis muscle, 2 B-cun superior to the medial end of the base of the patella.","primaryMeasures":["2 B-cun"]},"SP 11":{"anchor":1,"compare":"SP 12","focus":{"he":"SP 11 מחלקת את הקו בין הקצה הפנימי של בסיס הפיקה ל־SP 12 לשליש עליון ושני שלישים תחתונים. היא בין החייטים למקרב הארוך; אין להחליף את חלוקת הקו באמצעו.","en":"SP 11 divides the medial-patellar-base–SP 12 line into an upper third and lower two thirds. It lies between sartorius and adductor longus; this is not the line’s midpoint.","kind":"edited-location-3.3"},"shared":["Femoral Artery"],"unique":["Thigh","Patella","Sartorius Muscle","Adductor Longus Muscle"],"primaryEn":"On the medial aspect of the thigh, at the junction of the upper one third and lower two thirds of the line connecting the medial end of the base of the patella with SP12, between the sartorius muscle and the adductor longus muscle, over the femoral artery.","primaryMeasures":[]},"SP 12":{"anchor":1,"compare":"SP 13","focus":{"he":"קפל המפשעה הוא העוגן של SP 12, בצד החיצוני של עורק הירך. SP 13 מתוארת באמצעות מרחקים מהטבור ומקו האמצע. קפל שטחי ושורת מדידה בבטן אינם אותו ציון דרך.","en":"SP 12 uses the inguinal crease lateral to the femoral artery. SP 13 uses distances from the umbilicus and midline. A surface crease and an abdominal measurement row are different references.","kind":"edited-location-3.3"},"shared":[],"unique":["Groin Region","Inguinal Crease","Femoral Artery"],"primaryEn":"In the groin region, at the inguinal crease, lateral to the femoral artery.","primaryMeasures":[]},"SP 13":{"anchor":1,"compare":"SP 14","focus":{"he":"SP 13 נמצאת 4.3 B-cun מתחת לטבור ו־4 B-cun לצד קו האמצע; SP 14 נמצאת רק 1.3 B-cun מתחת לטבור. החלק העשרוני נשמר במקור ואינו עיגול ל־4 או ל־1.","en":"SP 13 is 4.3 B-cun below the umbilicus and 4 B-cun lateral; SP 14 is only 1.3 B-cun below. Preserve the decimal values rather than rounding them to four or one.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 4.3 B-cun inferior to the centre of the umbilicus, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4.3 B-cun","4 B-cun"]},"SP 14":{"anchor":1,"compare":"ST 26","focus":{"he":"SP 14 נמצאת 1.3 B-cun מתחת לטבור ו־4 B-cun הצדה. ST 26 נמצאת 1 B-cun מתחת ו־2 B-cun הצדה. כאן משתנים גם הגובה וגם ההיסט, ולכן אין לתאר אותן כאותה שורה.","en":"SP 14 is 1.3 B-cun below the umbilicus and 4 B-cun lateral. ST 26 is 1 B-cun below and 2 B-cun lateral. Both level and offset differ; they are not the same row.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 1.3 B-cun inferior to the centre of the umbilicus, 4 B-cun lateral to the anterior median line.","primaryMeasures":["1.3 B-cun","4 B-cun"]},"SP 15":{"anchor":1,"compare":"ST 25","focus":{"he":"SP 15 נמצאת בגובה מרכז הטבור, 4 B-cun הצדה; ST 25 באותו גובה, במרחק 2 B-cun. אין מידה אנכית נוספת בתיאור הראשי של SP 15.","en":"SP 15 is level with the umbilical centre, 4 B-cun lateral; ST 25 is 2 B-cun lateral at the same level. SP 15’s primary description adds no superior or inferior displacement.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus"],"unique":[],"primaryEn":"On the upper abdomen, 4 B-cun lateral to the centre of the umbilicus.","primaryMeasures":["4 B-cun"]},"SP 16":{"anchor":1,"compare":"ST 22","focus":{"he":"גובה SP 16 הוא 3 B-cun מעל הטבור, כמו ST 22. ההיסט הצדדי שלה הוא 4 B-cun לעומת 2 B-cun ב־ST 22. אלה שתי עמודות באותה שורת ייחוס.","en":"SP 16 is 3 B-cun above the umbilicus, like ST 22. Its lateral offset is 4 rather than 2 B-cun. They occupy different columns at the same reference level.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 3 B-cun superior to the centre of the umbilicus, 4 B-cun lateral to the anterior median line.","primaryMeasures":["3 B-cun","4 B-cun"]},"SP 17":{"anchor":1,"compare":"ST 18","focus":{"he":"המרווח הבין־צלעי החמישי מגדיר את הגובה. SP 17 רחוקה 6 B-cun מקו האמצע, ו־ST 18 רחוקה 4 B-cun. עוקבים אחר המרווח המעוקל ולא אחר קו ישר מהמסך.","en":"The fifth intercostal space sets the level. SP 17 lies 6 B-cun from the midline and ST 18 lies 4 B-cun away. Follow the curved space rather than a straight screen line.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fifth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the fifth intercostal space, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"SP 18":{"anchor":1,"compare":"KI 23","focus":{"he":"SP 18 ו־KI 23 משתמשות במרווח הבין־צלעי הרביעי. SP 18 בהיסט של 6 B-cun ו־KI 23 בהיסט של 2 B-cun. זיהוי המרווח קודם להשוואת העמודות.","en":"SP 18 and KI 23 use the fourth intercostal space. Their offsets are 6 and 2 B-cun. Identify the space before comparing the lateral columns.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fourth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the fourth intercostal space, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"SP 19":{"anchor":1,"compare":"ST 16","focus":{"he":"SP 19 נמצאת במרווח הבין־צלעי השלישי, 6 B-cun מקו האמצע; ST 16 באותו מרווח, 4 B-cun ממנו. מספר המרווח והמרחק מקו האמצע מגדירים יחד את ההבדל.","en":"SP 19 uses the third intercostal space at 6 B-cun from the midline; ST 16 uses 4 B-cun in that space. Read the intercostal level and midline offset together.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Third Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the third intercostal space, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"SP 20":{"anchor":1,"compare":"ST 15","focus":{"he":"שתי הנקודות מתייחסות למרווח הבין־צלעי השני. SP 20 נמצאת רחוק יותר מקו האמצע: 6 B-cun לעומת 4 B-cun ב־ST 15. אין לספור את העצם עצמה בתור המרווח.","en":"Both points use the second intercostal space. SP 20 is farther from the midline, 6 versus 4 B-cun for ST 15. Do not count the rib itself as the space.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Second Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the sec- ond intercostal space, 6 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun"]},"SP 21":{"anchor":1,"compare":"GB 22","focus":{"he":"SP 21 נמצאת במרווח הבין־צלעי השישי על הקו האמצעי של בית השחי. GB 22 משתמשת במרווח הרביעי באותו אזור צדדי. אותו קו אנכי יכול לכלול גבהים שונים.","en":"SP 21 uses the sixth intercostal space on the midaxillary line. GB 22 uses the fourth space in the same lateral region. One vertical reference can contain different levels.","kind":"edited-location-3.3"},"shared":["Lateral Thoracic Region","Midaxillary Line"],"unique":["Sixth Intercostal Space"],"primaryEn":"In the lateral thoracic region, in the sixth intercostal space, on the midaxillary line.","primaryMeasures":[]},"HT 1":{"anchor":0,"compare":"HT 2","focus":{"he":"מרכז גומת בית השחי הוא העוגן של HT 1. HT 2 נמצאת לאורך הצד הפנימי של הזרוע ומתוארת ביחס לשריר הדו־ראשי ולמרפק. אזכור העורק בבית השחי אינו הוראת מגע.","en":"HT 1 uses the centre of the axillary fossa. HT 2 lies along the medial arm with biceps and elbow references. Mention of the axillary artery does not provide a touching instruction.","kind":"edited-location-3.3"},"shared":[],"unique":["Axilla","Axillary Fossa","Axillary Artery"],"primaryEn":"In the axilla, in the centre of the axillary fossa, over the axillary artery.","primaryMeasures":[]},"HT 2":{"anchor":1,"compare":"LU 3","focus":{"he":"HT 2 נמצאת מדיאלית לשריר הדו־ראשי, 3 B-cun מעל קפל המרפק. ב־LU 3 המידה מתייחסת לקפל בית השחי. מספר זהה אינו בר־השוואה בלי אותו מוצא מדידה.","en":"HT 2 is medial to biceps, 3 B-cun above the elbow crease. LU 3 measures from the axillary fold. Equal numbers are not directly comparable when their starting landmarks differ.","kind":"edited-location-3.3"},"shared":["Arm","Biceps Brachii Muscle"],"unique":["Cubital Crease"],"primaryEn":"On the medial aspect of the arm, just medial to the biceps brachii muscle, 3 B-cun superior to the cubital crease.","primaryMeasures":["3 B-cun"]},"HT 3":{"anchor":1,"compare":"SI 8","focus":{"he":"HT 3 נמצאת לפני העילית העלי הפנימית בגובה קפל המרפק. SI 8 נמצאת מאחור, בין העילית לזיז המרפק. העילית משותפת, אך פני המפרק משתנים.","en":"HT 3 is anterior to the medial epicondyle at elbow-crease level. SI 8 is posterior, between that epicondyle and the olecranon. The landmark is shared but the joint surface differs.","kind":"edited-location-3.3"},"shared":["Elbow","Medial Epicondyle"],"unique":["Cubital Crease"],"primaryEn":"On the anteromedial aspect of the elbow, just anterior to the medial epicondyle of the humerus, at the same level as the cubital crease.","primaryMeasures":[]},"HT 4":{"anchor":1,"compare":"HT 5","focus":{"he":"שתיהן סמוכות לגיד מכופף שורש כף היד האולנרי. HT 4 נמצאת 1.5 B-cun מעל הקפל הכפי ו־HT 5 נמצאת 1 B-cun מעליו.","en":"Both lie by the flexor carpi ulnaris tendon. HT 4 is 1.5 B-cun proximal to the palmar wrist crease; HT 5 is 1 B-cun proximal.","kind":"edited-comparison"},"shared":["Tendon of flexor carpi ulnaris","Palmar Wrist Crease","Ulna","Pisiform Bone"],"unique":[],"primaryEn":"On the anteromedial aspect of the forearm, just radial to the flexor carpi ulnaris tendon, 1.5 B-cun proximal to the palmar wrist crease.","primaryMeasures":["1.5 B-cun"]},"HT 5":{"anchor":1,"compare":"HT 4","focus":{"he":"שתיהן סמוכות לגיד מכופף שורש כף היד האולנרי. HT 4 נמצאת 1.5 B-cun מעל הקפל הכפי ו־HT 5 נמצאת 1 B-cun מעליו.","en":"Both lie by the flexor carpi ulnaris tendon. HT 4 is 1.5 B-cun proximal to the palmar wrist crease; HT 5 is 1 B-cun proximal.","kind":"edited-comparison"},"shared":["Tendon of flexor carpi ulnaris","Palmar Wrist Crease","Ulna","Pisiform Bone"],"unique":[],"primaryEn":"On the anteromedial aspect of the forearm, radial to the flexor carpi ulnaris tendon, 1 B-cun proximal to the palmar wrist crease.","primaryMeasures":["1 B-cun"]},"HT 6":{"anchor":1,"compare":"HT 7","focus":{"he":"HT 7 מתוארת בגובה קפל שורש כף היד; HT 6 נמצאת חצי B-cun פרוקסימלית לו. הגיד האולנרי נשאר ציון דרך משותף.","en":"HT 7 is at the wrist crease; HT 6 is half a B-cun proximal to it. The ulnar flexor tendon remains a shared reference.","kind":"edited-comparison"},"shared":["Tendon of flexor carpi ulnaris","Palmar Wrist Crease","Pisiform Bone"],"unique":["Ulna"],"primaryEn":"On the anteromedial aspect of the forearm, radial to the flexor carpi ulnaris tendon, 0.5 B-cun proximal to the palmar wrist crease.","primaryMeasures":["0.5 B-cun"]},"HT 7":{"anchor":1,"compare":"HT 6","focus":{"he":"HT 7 מתוארת בגובה קפל שורש כף היד; HT 6 נמצאת חצי B-cun פרוקסימלית לו. הגיד האולנרי נשאר ציון דרך משותף.","en":"HT 7 is at the wrist crease; HT 6 is half a B-cun proximal to it. The ulnar flexor tendon remains a shared reference.","kind":"edited-comparison"},"shared":["Tendon of flexor carpi ulnaris","Palmar Wrist Crease","Pisiform Bone"],"unique":[],"primaryEn":"On the anteromedial aspect of the wrist, radial to the flexor carpi ulnaris tendon, on the palmar wrist crease.","primaryMeasures":[]},"HT 8":{"anchor":2,"compare":"PC 8","focus":{"he":"HT 8 משתמשת במרווח שבין עצמות המסרק הרביעית והחמישית. המיקום הראשי של PC 8 הוא בין השנייה לשלישית; החלופה שלו בין השלישית לרביעית.","en":"HT 8 uses the fourth–fifth metacarpal interval. Primary PC 8 uses the second–third interval; its alternative uses the third–fourth interval.","kind":"edited-comparison"},"shared":["FOURTH METACARPAL BONE"],"unique":["FIFTH METACARPAL BONE","metacarpophalangeal joint of manual digit 5","Little Finger"],"primaryEn":"On the palm of the hand, in the depression between the fourth and fifth metacarpal bones, proximal to the fifth metacarpophalangeal joint.","primaryMeasures":[]},"HT 9":{"anchor":0,"compare":"SI 1","focus":{"he":"שתיהן סמוכות לציפורן הזרת: SI 1 בצד האולנרי ו־HT 9 בצד הרדיאלי. יש לזהות את צד האגודל וצד הזרת לפני פירוש פינת הציפורן.","en":"Both are near the little fingernail: SI 1 on its ulnar side and HT 9 on its radial side. Establish thumb-side and little-finger-side orientation first.","kind":"edited-comparison"},"shared":["Little Finger","Distal Phalanx","Nail Of Manual Digit 5"],"unique":[],"primaryEn":"On the little finger, radial to the distal phalanx, 0.1 f-cun proximal-lateral to the radial corner of the little fingernail, at the intersection of the vertical line of the radial border of the nail and horizontal line of the base of the little fingernail.","primaryMeasures":[]},"SI 1":{"anchor":0,"compare":"HT 9","focus":{"he":"שתיהן סמוכות לציפורן הזרת: SI 1 בצד האולנרי ו־HT 9 בצד הרדיאלי. יש לזהות את צד האגודל וצד הזרת לפני פירוש פינת הציפורן.","en":"Both are near the little fingernail: SI 1 on its ulnar side and HT 9 on its radial side. Establish thumb-side and little-finger-side orientation first.","kind":"edited-comparison"},"shared":["Little Finger","Distal Phalanx","Nail Of Manual Digit 5"],"unique":[],"primaryEn":"On the little finger, ulnar to the distal phalanx, 0.1 f-cun proximal-medial to the ulnar corner of the little fingernail, at the intersection of the vertical line of ulnar border of the nail and horizontal line of the base of the little fingernail.","primaryMeasures":[]},"SI 2":{"anchor":0,"compare":"SI 3","focus":{"he":"המפרק החמישי מפריד בין התיאורים: SI 2 דיסטלית לו, בצד הזרת; SI 3 פרוקסימלית לו, בצד כף היד. זה התיקון המרכזי ביחס לתיאורים המשוכפלים שהיו במאגר.","en":"The fifth metacarpophalangeal joint separates the descriptions: SI 2 is distal, on the finger side; SI 3 proximal, on the hand side. This resolves the duplicated source descriptions.","kind":"edited-comparison"},"shared":["metacarpophalangeal joint of manual digit 5"],"unique":["Little Finger"],"primaryEn":"On the ulnar side of the little finger, distal to the fifth metacarpophalangeal joint, at the border between the palmar and dorsal skin.","primaryMeasures":[]},"SI 3":{"anchor":1,"compare":"SI 2","focus":{"he":"המפרק החמישי מפריד בין התיאורים: SI 2 דיסטלית לו, בצד הזרת; SI 3 פרוקסימלית לו, בצד כף היד. זה התיקון המרכזי ביחס לתיאורים המשוכפלים שהיו במאגר.","en":"The fifth metacarpophalangeal joint separates the descriptions: SI 2 is distal, on the finger side; SI 3 proximal, on the hand side. This resolves the duplicated source descriptions.","kind":"edited-comparison"},"shared":["metacarpophalangeal joint of manual digit 5"],"unique":[],"primaryEn":"On the ulnar side of the hand, proximal to the fifth metacarpophalangeal joint, at the border between the palmar and dorsal skin.","primaryMeasures":[]},"SI 4":{"anchor":1,"compare":"SI 5","focus":{"he":"SI 4 משתמשת באזור שבין בסיס עצם המסרק החמישית לעצם המשולשת. SI 5 משתמשת באזור שבין זיז הגומד לעצם המשולשת, סמוך יותר לשורש כף היד.","en":"SI 4 uses the interval between the fifth metacarpal base and triquetrum. SI 5 uses the ulnar-styloid–triquetrum region, closer to the wrist.","kind":"edited-comparison"},"shared":["Triquetrum"],"unique":["Fifth Metacarpal Bone"],"primaryEn":"On the posteromedial aspect of the wrist, in the depression between the base of the fifth metacarpal bone and the triquetrum bone, at the border between the red and white flesh.","primaryMeasures":[]},"SI 5":{"anchor":1,"compare":"SI 4","focus":{"he":"SI 4 משתמשת באזור שבין בסיס עצם המסרק החמישית לעצם המשולשת. SI 5 משתמשת באזור שבין זיז הגומד לעצם המשולשת, סמוך יותר לשורש כף היד.","en":"SI 4 uses the interval between the fifth metacarpal base and triquetrum. SI 5 uses the ulnar-styloid–triquetrum region, closer to the wrist.","kind":"edited-comparison"},"shared":["Triquetrum"],"unique":["Ulnar Styloid Process"],"primaryEn":"On the posteromedial aspect of the wrist, in the depression between the triquetrum bone and the ulnar styloid process.","primaryMeasures":[]},"SI 6":{"anchor":1,"compare":"SI 5","focus":{"he":"ראש הגומד הוא עוגן SI 6, בשקע בצדו הרדיאלי ו־1 B-cun מעל הקפל הגבי. SI 5 משתמשת בזיז הגומד ובאזור המפרק. ראש העצם והזיז שלה אינם שמות נרדפים.","en":"SI 6 uses the radial side of the ulnar head, 1 B-cun proximal to the dorsal crease. SI 5 uses the ulnar styloid and wrist joint region. The head and styloid are distinct landmarks.","kind":"edited-location-3.3"},"shared":[],"unique":["Forearm","Dorsal Wrist Crease","ulna"],"primaryEn":"On the posteromedial aspect of the forearm, in the depression radial to the head of the ulnar bone, 1 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["1 B-cun"]},"SI 7":{"anchor":1,"compare":"TE 9","focus":{"he":"SI 7 נמצאת בין הגבול הפנימי של הגומד למכופף האולנרי, 5 B-cun מעל הקפל הגבי. TE 9 מודדת 5 B-cun מזיז המרפק לכיוון היד. אותו מספר מתחיל מקצה אחר.","en":"SI 7 lies between the medial ulna and flexor carpi ulnaris, 5 B-cun above the dorsal crease. TE 9 measures 5 B-cun distally from the olecranon. The same number starts at the opposite end.","kind":"edited-location-3.3"},"shared":["Forearm"],"unique":["ulna","Flexor Carpi Ulnaris Muscle","Dorsal Wrist Crease"],"primaryEn":"On the posteromedial aspect of the forearm, between the medial border of the ulnar bone and the flexor carpi ulnaris muscle, 5 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["5 B-cun"]},"SI 8":{"anchor":1,"compare":"HT 3","focus":{"he":"זיז המרפק והעילית העלי הפנימית תוחמים את השקע של SI 8 מאחור. HT 3 נמצאת לפני העילית. יש להבחין בין השקע האחורי לבין קפל המרפק הקדמי.","en":"Olecranon and medial epicondyle bound SI 8’s posterior depression. HT 3 lies anterior to the epicondyle. Distinguish the posterior groove from the anterior elbow crease.","kind":"edited-location-3.3"},"shared":["Elbow","Medial Epicondyle"],"unique":["Olecranon","Humerus Bone","Ulnar Nerve"],"primaryEn":"On the posteromedial aspect of the elbow, in the depression between the olecranon and the medial epicondyle of the humerus bone.","primaryMeasures":[]},"SI 9":{"anchor":1,"compare":"SI 10","focus":{"he":"SI 9 מתוארת 1 B-cun מעל קפל בית השחי האחורי ומאחורי הכתף. SI 10 משתמשת בשקע שמתחת לקוץ השכמה. הקפל והקוץ אינם שתי דרכים לציין אותו גובה.","en":"SI 9 is 1 B-cun above the posterior axillary fold behind the shoulder. SI 10 uses the depression below the scapular spine. Fold and spine are not interchangeable level references.","kind":"edited-location-3.3"},"shared":["Shoulder Girdle","Posterior Axillary Fold"],"unique":["Shoulder Joint","Deltoid Muscle"],"primaryEn":"On the shoulder girdle, posteroinferior to the shoulder joint, 1 B-cun superior to the posterior axillary fold.","primaryMeasures":["1 B-cun"]},"SI 10":{"anchor":1,"compare":"SI 12","focus":{"he":"קוץ השכמה מפריד בין אזורי ההשוואה: SI 10 בשקע שמתחתיו מעל קפל בית השחי האחורי, ו־SI 12 בגומה שמעליו. כיוון מעל/מתחת נקרא ביחס לעצם.","en":"The scapular spine separates the compared regions: SI 10 is below it above the posterior axillary fold; SI 12 is in the fossa above it. Read above and below relative to the bone.","kind":"edited-location-3.3"},"shared":["Scapula Spine"],"unique":["Shoulder Girdle","Posterior Axillary Fold"],"primaryEn":"On the shoulder girdle, superior to the posterior axillary fold, in the depression inferior to the spine of the scapula.","primaryMeasures":[]},"SI 11":{"anchor":1,"compare":"SI 12","focus":{"he":"SI 11 קשורה לגומה שמתחת לקוץ השכמה; SI 12 לגומה שמעליו. קוץ השכמה הוא קו ההפרדה שמסביר את מיקומן על אותה עצם.","en":"SI 11 uses the infraspinous fossa; SI 12 the supraspinous fossa. The scapular spine separates these regions of the same bone.","kind":"edited-comparison"},"shared":["Scapula","Scapula Spine"],"unique":[],"primaryEn":"In the scapular region, in the depression between the upper one third and lower two thirds of the line connecting the midpoint of the spine of the scapula with the inferior angle of the scapula.","primaryMeasures":[]},"SI 12":{"anchor":1,"compare":"SI 11","focus":{"he":"SI 11 קשורה לגומה שמתחת לקוץ השכמה; SI 12 לגומה שמעליו. קוץ השכמה הוא קו ההפרדה שמסביר את מיקומן על אותה עצם.","en":"SI 11 uses the infraspinous fossa; SI 12 the supraspinous fossa. The scapular spine separates these regions of the same bone.","kind":"edited-comparison"},"shared":["Scapula","Scapula Spine"],"unique":["Supraspinatus Fossa"],"primaryEn":"In the scapular region, in the supraspinatous fossa, superior to the midpoint of the spine of the scapula.","primaryMeasures":[]},"SI 13":{"anchor":1,"compare":"SI 12","focus":{"he":"SI 13 קשורה לקצה המדיאלי של קוץ השכמה ולשקע שמעליו. SI 12 מתייחסת לגומה העל־קוצית. זיהוי קצה הקוץ מחדד את המיקום בתוך אזור השכמה הרחב.","en":"SI 13 uses the depression above the medial end of the scapular spine. SI 12 uses the supraspinous fossa. Identifying the spine’s end narrows the location within the wider scapular region.","kind":"edited-location-3.3"},"shared":["Scapular Region","Scapula","Scapula Spine"],"unique":["Second Thoracic Vertebra"],"primaryEn":"In the scapular region, in the depression superior to the medial end of the spine of the scapula.","primaryMeasures":[]},"SI 14":{"anchor":1,"compare":"BL 11","focus":{"he":"SI 14 ו־BL 11 מתייחסות לגבול התחתון של זיז T1. SI 14 בהיסט של 3 B-cun ו־BL 11 בהיסט של 1.5 B-cun. הגובה משותף, אך העמודה הצדדית שונה.","en":"SI 14 and BL 11 reference the inferior border of the T1 spinous process. Their lateral offsets are 3 and 1.5 B-cun. They share a level, not a lateral column.","kind":"edited-location-3.3"},"shared":["Upper Back","First Thoracic Vertebra","Posterior Median Line"],"unique":["Scapula Spine"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the first thoracic vertebra (T1), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"SI 15":{"anchor":1,"compare":"GV 14","focus":{"he":"הגבול התחתון של זיז C7 קובע את הגובה. SI 15 נמצאת 2 B-cun לצד קו האמצע, בעוד GV 14 בקו האמצע. אין להעביר לכאן אוטומטית את היסט 3 B-cun של SI 14.","en":"The inferior C7 spinous-process border sets the level. SI 15 is 2 B-cun lateral and GV 14 midline. Do not carry over SI 14’s 3 B-cun offset to this record.","kind":"edited-location-3.3"},"shared":["Seventh Cervical Vertebra","Posterior Median Line"],"unique":["Upper Back","Scapula"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous pro- cess of the seventh cervical vertebra (C7), 2 B-cun lateral to the posterior median line.","primaryMeasures":["2 B-cun"]},"SI 16":{"anchor":1,"compare":"LI 18","focus":{"he":"בגובה הגבול העליון של סחוס התריס, SI 16 מתוארת מאחורי שריר מפנה הראש. LI 18 נמצאת בין גבולותיו ו־ST 9 לפניו.","en":"At the superior thyroid-cartilage level, SI 16 is posterior to sternocleidomastoid; LI 18 is between its borders and ST 9 anterior to it.","kind":"edited-location"},"shared":["Sternocleidomastoid Muscle","Thyroid Cartilage"],"unique":[],"primaryEn":"In the anterior region of the neck, posterior to the sternocleidomastoid muscle, at the same level as the superior border of the thyroid cartilage.","primaryMeasures":[]},"SI 17":{"anchor":1,"compare":"TE 16","focus":{"he":"זווית הלסת היא עוגן הגובה, והשקע מתואר לפני שריר מפנה הראש. TE 16 מתייחסת לגובה דומה אך לשקע מאחורי השריר.","en":"The mandibular angle is the level reference and the depression is anterior to sternocleidomastoid. TE 16 refers to a similar level posterior to the muscle.","kind":"edited-location"},"shared":["Mandible","Sternocleidomastoid Muscle"],"unique":[],"primaryEn":"In the anterior region of the neck, posterior to the angle of the mandible, in the depression anterior to the sternocleidomastoid muscle.","primaryMeasures":[]},"SI 18":{"anchor":1,"compare":"ST 2","focus":{"he":"SI 18 מתוארת מתחת לעצם הלחי, בקו היורד מזווית העין החיצונית. ST 2 משתמשת בקו שמתחת לאישון ובפתח התת־ארובתי. זווית העין והאישון מגדירים שני קווים שונים.","en":"SI 18 lies below the zygomatic bone on the line descending from the outer eye angle. ST 2 uses the pupil line and infraorbital foramen. Eye angle and pupil define different alignments.","kind":"edited-location-3.3"},"shared":["Face"],"unique":["Zygomatic Bone","Outer Canthus","Eye"],"primaryEn":"On the face, inferior to the zygomatic bone, in the depression directly inferior to the outer canthus of the eye.","primaryMeasures":[]},"SI 19":{"anchor":1,"compare":"TE 21","focus":{"he":"TE 21 מתוארת בגובה החריץ שמעל הטרגוס, ו־SI 19 בגובה אמצע הטרגוס. שינוי הגובה לאורך אותה אוזן הוא מוקד ההשוואה.","en":"TE 21 uses the supratragic notch level, while SI 19 uses the middle of the tragus. The differing level along the same ear is the focus.","kind":"edited-comparison"},"shared":[],"unique":["Tragus","Mandible Condylar Process"],"primaryEn":"On the face, in the depression between the anterior border of the centre of the tragus and the posterior border of the condylar process of the mandible.","primaryMeasures":[]},"BL 1":{"anchor":1,"compare":"GB 1","focus":{"he":"ההבחנה היא זווית העין: BL 1 בזווית הפנימית, סמוך לאף; GB 1 בזווית החיצונית. פנימי וחיצוני מתייחסים לפנים של האדם, לא לצד המסך.","en":"The distinction is the eye angle: BL 1 uses the inner, nasal angle; GB 1 the outer angle. These directions belong to the person, not to screen left and right.","kind":"edited-comparison"},"shared":["Eye"],"unique":["Inner Canthus","Orbital Cavity"],"primaryEn":"On the face, in the depression between the superomedial parts of the inner canthus of the eye and the medial wall of the orbit.","primaryMeasures":[]},"BL 2":{"anchor":1,"compare":"BL 1","focus":{"he":"הקצה הפנימי של הגבה והשקע שבו מגדירים את BL 2. BL 1 קשורה לזווית העין הפנימית מתחתיה. גבה וזווית עין הם ציוני דרך נפרדים, גם כשהם סמוכים בתקריב.","en":"BL 2 uses the depression at the medial eyebrow end. BL 1 uses the inner eye angle below it. Eyebrow and eye angle remain separate landmarks even in a close-up.","kind":"edited-location-3.3"},"shared":[],"unique":["Head","Eyebrow","Frontal Notch"],"primaryEn":"On the head, in the depression at the medial end of the eyebrow.","primaryMeasures":[]},"BL 3":{"anchor":1,"compare":"BL 4","focus":{"he":"BL 3 נמצאת חצי B-cun מעל קו השיער הקדמי, מעל החריץ המצחי; בהערת המקור היא באמצע בין GV 24 ל־BL 4. ל־BL 4 היסט צדדי מוגדר של 1.5 B-cun.","en":"BL 3 is half a B-cun above the anterior hairline over the frontal notch; the source note places it midway between GV 24 and BL 4. BL 4 has a specified 1.5 B-cun lateral offset.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline"],"unique":["Frontal Notch"],"primaryEn":"On the head, superior to the frontal notch, 0.5 B-cun superior to the anterior hairline.","primaryMeasures":["0.5 B-cun"]},"BL 4":{"anchor":1,"compare":"BL 5","focus":{"he":"BL 4 נמצאת חצי B-cun מעל קו השיער, 1.5 B-cun מקו האמצע. BL 5 שומרת על ההיסט הצדדי אך נמצאת יחידה שלמה מעל קו השיער. מפרידים בין שינוי הגובה לעמודה הקבועה.","en":"BL 4 is half a B-cun above the hairline and 1.5 B-cun lateral. BL 5 retains the lateral offset but is one full unit above the hairline. Only the hairline distance changes.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 0.5 B-cun superior to the anterior hairline, 1.5 B-cun lateral to the anterior median line.","primaryMeasures":["0.5 B-cun","1.5 B-cun"]},"BL 5":{"anchor":1,"compare":"GV 23","focus":{"he":"הגובה של BL 5 הוא 1 B-cun מעל קו השיער הקדמי, כמו GV 23. BL 5 נמצאת 1.5 B-cun הצדה ו־GV 23 בקו האמצע. הקווים בסכמת הקרקפת מייצגים ייחוס יחסי.","en":"BL 5 and GV 23 are 1 B-cun above the anterior hairline. BL 5 is 1.5 B-cun lateral; GV 23 is midline. Scalp-grid lines represent relative references rather than measured surface distances.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 1 B-cun superior to the anterior hairline, 1.5 B-cun lateral to the anterior median line.","primaryMeasures":["1 B-cun","1.5 B-cun"]},"BL 6":{"anchor":1,"compare":"BL 7","focus":{"he":"מרחק BL 6 מקו השיער הקדמי הוא 2.5 B-cun, לעומת 4 B-cun ב־BL 7. שתיהן בעמודה של 1.5 B-cun מקו האמצע; מספור עוקב אינו מרווח של יחידה אחת.","en":"BL 6 is 2.5 B-cun from the anterior hairline, compared with 4 B-cun for BL 7. Both use the 1.5 B-cun lateral column; consecutive numbers do not imply one-unit spacing.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 2.5 B-cun superior to the anterior hairline, 1.5 B-cun lateral to the anterior median line.","primaryMeasures":["2.5 B-cun","1.5 B-cun"]},"BL 7":{"anchor":1,"compare":"BL 8","focus":{"he":"BL 7 נמצאת 4 B-cun מעל קו השיער הקדמי, באמצע בין BL 6 ל־BL 8 לפי ההערה. BL 8 נמצאת במרחק 5.5 B-cun. את המרחקים קוראים לאורך הקרקפת ולא כלפי מעלה במסך בלבד.","en":"BL 7 is 4 B-cun from the anterior hairline and is the stated midpoint between BL 6 and BL 8. BL 8 is 5.5 B-cun from that line. Read these along the scalp, not merely screen-upward.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 4 B-cun superior to the anterior hairline, 1.5 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun","1.5 B-cun"]},"BL 8":{"anchor":1,"compare":"GV 20","focus":{"he":"BL 8 מתוארת 5.5 B-cun מקו השיער הקדמי ו־1.5 B-cun הצדה. ביחס ל־GV 20 היא חצי B-cun אחורית יותר. ההיסט האחורי וההיסט הצדדי הם שני רכיבים שונים.","en":"BL 8 is 5.5 B-cun from the anterior hairline and 1.5 B-cun lateral. Relative to GV 20 it is half a B-cun farther posteriorly. Posterior and lateral offsets are separate components.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 5.5 B-cun superior to the anterior hairline, 1.5 B-cun lateral to the anterior median line.","primaryMeasures":["5.5 B-cun","1.5 B-cun"]},"BL 9":{"anchor":1,"compare":"GV 17","focus":{"he":"BL 9 בגובה הגבול העליון של הבליטה העורפית, 1.3 B-cun לצד קו האמצע האחורי. GV 17 בקו האמצע באותו גובה. כאן ההיסט 1.3, ולא 1.5 כמו ברבות מנקודות BL.","en":"BL 9 is at the superior external-occipital-protuberance level, 1.3 B-cun lateral. GV 17 is midline at that level. Retain 1.3 rather than substituting the common BL offset of 1.5.","kind":"edited-location-3.3"},"shared":["Head","External Occipital Protuberance","Posterior Median Line"],"unique":["Trapezius Muscle"],"primaryEn":"On the head, at the same level as the superior border of the external occipital protuberance, and 1.3 B-cun lateral to the posterior median line.","primaryMeasures":["1.3 B-cun"]},"BL 10":{"anchor":1,"compare":"GV 15","focus":{"he":"זיז C2 קובע את הגובה של BL 10, והשקע נמצא לטרלית לשריר הטרפז. GV 15 משתמשת באזור שמעל זיז C2 בקו האמצע. שם החוליה לבדו אינו מתאר את ההיסט לשריר.","en":"C2’s spinous process sets BL 10’s level, with the depression lateral to trapezius. GV 15 uses the region above C2 on the midline. A vertebral name alone does not specify the muscle relationship.","kind":"edited-location-3.3"},"shared":["Neck","Second Cervical Vertebra"],"unique":["Trapezius Muscle"],"primaryEn":"In the posterior region of the neck, at the same level as the superior border of the spinous process of the second cervical vertebra (C2), in the depression lateral to the trapezius muscle.","primaryMeasures":[]},"BL 11":{"anchor":1,"compare":"SI 14","focus":{"he":"מתחילים בגבול התחתון של זיז T1, ואז בהיסט של 1.5 B-cun מקו האמצע. SI 14 נמצאת באותו גובה בהיסט 3 B-cun. BL 11 שייכת לעמודה הפנימית יותר.","en":"Start with the inferior T1 spinous-process border, then the 1.5 B-cun lateral offset. SI 14 uses 3 B-cun at the same level. BL 11 belongs to the more medial column.","kind":"edited-location-3.3"},"shared":["Upper Back","First Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the first thoracic vertebra (T1), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 12":{"anchor":1,"compare":"BL 41","focus":{"he":"הגבול התחתון של זיז T2 משותף ל־BL 12 ול־BL 41. BL 12 במרחק 1.5 B-cun מקו האמצע; BL 41 במרחק 3. זיהוי T2 אינו מספיק בלי בחירת העמודה.","en":"BL 12 and BL 41 share the inferior T2 spinous-process level. Their offsets are 1.5 and 3 B-cun. Identifying T2 must be followed by choosing the lateral column.","kind":"edited-location-3.3"},"shared":["Upper Back","Second Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the second thoracic vertebra (T2), 1.5 B- cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 13":{"anchor":1,"compare":"GV 12","focus":{"he":"BL 13 נמצאת לצד הגבול התחתון של זיז T3, בהיסט 1.5 B-cun. GV 12 בקו האמצע באותו גובה. קוד BL 13 אינו מציין חוליה שמספרה 13.","en":"BL 13 lies 1.5 B-cun lateral at the inferior T3 spinous-process level. GV 12 is midline at that level. The point number 13 does not denote a thirteenth vertebra.","kind":"edited-location-3.3"},"shared":["Upper Back","Third Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous pro- cess of the third thoracic vertebra (T3), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 14":{"anchor":1,"compare":"BL 43","focus":{"he":"T4 מגדירה את הגובה ו־1.5 B-cun מגדירים את ההיסט של BL 14. BL 43 נמצאת בגובה זה בעמודה של 3 B-cun. שני הקודים מתייחסים לאותה חוליה למרות המספרים השונים.","en":"T4 sets the level and 1.5 B-cun the offset for BL 14. BL 43 uses the 3 B-cun column at that level. Different point numbers can reference the same vertebra.","kind":"edited-location-3.3"},"shared":["Upper Back","Fourth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the fourth thoracic vertebra (T4), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 15":{"anchor":1,"compare":"BL 44","focus":{"he":"העוגן האנכי הוא הגבול התחתון של זיז T5. BL 15 קרובה יותר לקו האמצע מ־BL 44: היסט של 1.5 לעומת 3 B-cun. ההשוואה עוקבת אחר הגובה לפני הרוחב.","en":"Use the inferior T5 spinous-process border. BL 15 is nearer the midline than BL 44, at 1.5 rather than 3 B-cun. Match the vertebral level before comparing width.","kind":"edited-location-3.3"},"shared":["Upper Back","Fifth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous pro- cess of the fifth thoracic vertebra (T5), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 16":{"anchor":1,"compare":"GV 10","focus":{"he":"BL 16 נמצאת 1.5 B-cun הצדה בגובה שמתחת לזיז T6. GV 10 נמצאת בקו האמצע באותו מפלס. הגבול התחתון של הזיז הוא הייחוס, ולא מרכז גוף החוליה.","en":"BL 16 lies 1.5 B-cun lateral at the inferior T6 spinous-process level; GV 10 is midline there. The reference is the spinous-process border, not the vertebral-body centre.","kind":"edited-location-3.3"},"shared":["Upper Back","Sixth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, level with the inferior border of the spinous process of the sixth thoracic vertebra (T6), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 17":{"anchor":1,"compare":"BL 18","focus":{"he":"BL 17 משתמשת ב־T7 ובהיסט של 1.5 B-cun. הנקודה הבאה, BL 18, משתמשת ב־T9; אין ברצף הזה נקודה מקבילה ב־T8. זו דוגמה לכך שמספור הנקודות אינו ספירת חוליות.","en":"BL 17 uses T7 and a 1.5 B-cun offset. The next point, BL 18, uses T9; this sequence skips a T8 counterpart. Point numbering is not vertebral counting.","kind":"edited-location-3.3"},"shared":["Upper Back","Posterior Median Line"],"unique":["Seventh Thoracic Vertebra","Scapula"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the seventh thoracic vertebra (T7), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 18":{"anchor":1,"compare":"BL 47","focus":{"he":"ב־BL 18 הגובה הוא הגבול התחתון של זיז T9, וההיסט 1.5 B-cun. BL 47 מרוחקת 3 B-cun באותו מפלס. יש לזהות T9 ישירות, בלי להניח שהמספר ממשיך מגובה T8.","en":"BL 18 uses the inferior T9 spinous-process level at 1.5 B-cun lateral. BL 47 uses 3 B-cun there. Identify T9 directly rather than inferring the level from point sequence.","kind":"edited-location-3.3"},"shared":["Upper Back","Ninth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the ninth thoracic vertebra (T9), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 19":{"anchor":1,"compare":"GV 7","focus":{"he":"BL 19 נמצאת בגובה הגבול התחתון של זיז T10, 1.5 B-cun הצדה. GV 7 מייצגת את קו האמצע בגובה זה. T10 היא חוליית חזה, ולכן שייכת לסדרה T ולא L.","en":"BL 19 is 1.5 B-cun lateral at the inferior T10 spinous-process level. GV 7 is the midline counterpart. T10 belongs to the thoracic T series, not the lumbar L series.","kind":"edited-location-3.3"},"shared":["Upper Back","Tenth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the tenth thoracic vertebra (T10), 1.5 B- cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 20":{"anchor":1,"compare":"BL 49","focus":{"he":"BL 20 ו־BL 49 נפגשות באותה שורת ייחוס, מתחת לזיז T11. ההיסטים 1.5 ו־3 B-cun מבחינים ביניהן. שם החוליה מגדיר את השורה; שם המרידיאן אינו מגדיר לבדו את העמודה.","en":"BL 20 and BL 49 share the inferior T11 spinous-process row. Their offsets, 1.5 and 3 B-cun, distinguish them. A channel name alone does not select a lateral column.","kind":"edited-location-3.3"},"shared":["Upper Back","Eleventh Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the 11th thoracic vertebra (T11), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 21":{"anchor":1,"compare":"BL 22","focus":{"he":"BL 21 משתמשת ב־T12, החוליה האחרונה בסדרת החזה, בהיסט 1.5 B-cun. BL 22 עוברת ל־L1 שבמותן עם אותו היסט. שימו לב להחלפת האות לצד החלפת המספר.","en":"BL 21 uses T12, the last thoracic vertebra, at 1.5 B-cun lateral. BL 22 moves to lumbar L1 with the same offset. Notice the letter change as well as the number.","kind":"edited-location-3.3"},"shared":["Posterior Median Line"],"unique":["Upper Back","Twelfth Thoracic Vertebra"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the 12th thoracic vertebra (T12), 1.5 B- cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 22":{"anchor":1,"compare":"BL 51","focus":{"he":"העוגן הוא הגבול התחתון של זיז L1. BL 22 במרחק 1.5 B-cun מקו האמצע, ו־BL 51 במרחק 3. L1 מגדירה גובה מותני ואינה שם של נקודת לימוד.","en":"The inferior L1 spinous-process border is the reference. BL 22 is 1.5 B-cun from the midline and BL 51 is 3 B-cun away. L1 denotes a lumbar level, not a point code.","kind":"edited-location-3.3"},"shared":["Lumbar Region","First Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the first lumbar vertebra (L1), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 23":{"anchor":1,"compare":"GV 4","focus":{"he":"BL 23 ממוקמת לצד זיז L2, בגובה גבולו התחתון, 1.5 B-cun מקו האמצע. GV 4 בקו האמצע באותו גובה. אין להזיז את השורה לפי קו המותניים החיצוני בלבד.","en":"BL 23 lies 1.5 B-cun lateral at the inferior L2 spinous-process level; GV 4 is midline there. An external waist contour alone does not establish that vertebral row.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Second Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the second lumbar vertebra (L2), 1.5 B- cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 24":{"anchor":1,"compare":"BL 25","focus":{"he":"BL 24 משתמשת בגבול התחתון של זיז L3, ו־BL 25 בזיז L4. ההיסט של שתיהן 1.5 B-cun. כאן הגובה משתנה, בעוד העמודה הצדדית נשמרת.","en":"BL 24 uses the inferior L3 spinous-process border; BL 25 uses L4. Both retain the 1.5 B-cun offset. The level changes while the lateral column stays constant.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Posterior Median Line"],"unique":["Third Lumbar Vertebra"],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the third lumbar vertebra (L3), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 25":{"anchor":1,"compare":"GV 3","focus":{"he":"הגבול התחתון של זיז L4 הוא שורת הייחוס. BL 25 נמצאת 1.5 B-cun הצדה ו־GV 3 בקו האמצע. קווי האגן בסכמה הם הקשר חזותי ואינם מחליפים את זיהוי L4.","en":"The inferior L4 spinous-process border sets the row. BL 25 lies 1.5 B-cun lateral and GV 3 midline. Pelvic contours give context but do not replace identification of L4.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Fourth Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the fourth lumbar vertebra (L4), 1.5 B- cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 26":{"anchor":1,"compare":"BL 27","focus":{"he":"BL 26 עדיין משתמשת בזיז חוליה מותנית: L5, בהיסט 1.5 B-cun. BL 27 עוברת לגובה הנקב הראשון בעצה. מעבר בין הרשומות מחליף גם את סוג ציון הדרך.","en":"BL 26 still uses a lumbar spinous process, L5, at a 1.5 B-cun offset. BL 27 moves to the first sacral-foramen level. The anatomical reference type changes between them.","kind":"edited-location-3.3"},"shared":[],"unique":["Lumbar Region","Fifth Lumbar Vertebra","Posterior Median Line"],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the fifth lumbar vertebra (L5), 1.5 B-cun lateral to the posterior median line.","primaryMeasures":["1.5 B-cun"]},"BL 27":{"anchor":1,"compare":"BL 31","focus":{"he":"הנקב האחורי הראשון בעצה קובע את גובה BL 27, אך הנקודה נמצאת 1.5 B-cun מרכס העצה האמצעי. BL 31 נמצאת בנקב עצמו. ״בגובה הנקב״ אינו ״בתוך הנקב״.","en":"The first posterior sacral foramen sets BL 27’s level, but its position is 1.5 B-cun from the median sacral crest. BL 31 uses the foramen itself. Level with is not within.","kind":"edited-location-3.3"},"shared":["Sacral Region","First Posterior Sacral Foramen"],"unique":["Median Sacral Crest"],"primaryEn":"In the sacral region, at the same level as the first posterior sacral foramen, and 1.5 B-cun lateral to the median sacral crest.","primaryMeasures":["1.5 B-cun"]},"BL 28":{"anchor":1,"compare":"BL 32","focus":{"he":"BL 28 נמצאת בגובה הנקב האחורי השני, 1.5 B-cun מרכס העצה האמצעי; BL 32 בנקב עצמו. מספר הנקב קובע גובה, וההיסט קובע אם הסימון יושב עליו או לצדו.","en":"BL 28 is level with the second posterior sacral foramen, 1.5 B-cun from the median crest; BL 32 uses the foramen itself. Foramen number and lateral offset answer different locating questions.","kind":"edited-location-3.3"},"shared":["Sacral Region","Second Posterior Sacral Foramen"],"unique":["Median Sacral Crest"],"primaryEn":"In the sacral region, at the same level as the second posterior sacral foramen, and 1.5 B-cun lateral to the median sacral crest.","primaryMeasures":["1.5 B-cun"]},"BL 29":{"anchor":1,"compare":"BL 33","focus":{"he":"הנקב השלישי מספק את שורת הייחוס. BL 29 נמצאת 1.5 B-cun מרכס העצה, ו־BL 33 מתוארת בנקב. השוואה נכונה משאירה את הגובה קבוע ובודקת את ההיסט.","en":"The third posterior sacral foramen supplies the reference row. BL 29 lies 1.5 B-cun from the median crest; BL 33 uses the foramen. Hold the level constant when comparing the offset.","kind":"edited-location-3.3"},"shared":["Sacral Region","Third Posterior Sacral Foramen"],"unique":["Median Sacral Crest"],"primaryEn":"In the sacral region, at the same level as the third posterior sacral foramen, 1.5 B-cun lateral to the median sacral crest.","primaryMeasures":["1.5 B-cun"]},"BL 30":{"anchor":1,"compare":"BL 54","focus":{"he":"BL 30 ו־BL 54 מתייחסות לגובה הנקב האחורי הרביעי בעצה. BL 30 בהיסט 1.5 B-cun ו־BL 54 בהיסט 3. פתח העצה שמוזכר בהערה הוא עוגן נוסף לגובה, לא שם הנקב הרביעי.","en":"BL 30 and BL 54 use the fourth posterior sacral-foramen level, at offsets of 1.5 and 3 B-cun. The sacral hiatus is another level reference, not another name for the fourth foramen.","kind":"edited-location-3.3"},"shared":["Fourth Posterior Sacral Foramen","Sacral Hiatus","Median Sacral Crest"],"unique":["Sacral Region"],"primaryEn":"In the sacral region, at the same level as the fourth posterior sacral foramen, 1.5 B-cun lateral to the median sacral crest.","primaryMeasures":["1.5 B-cun"]},"BL 31":{"anchor":1,"compare":"BL 27","focus":{"he":"הספרה הסידורית היא חלק מההגדרה: הנקב האחורי הראשון של עצם העצה. אין לערבב בין נקב מסוים לבין נקודה צדדית שנמצאת בגובה דומה.","en":"The ordinal matters: the first posterior sacral foramen. A specific foramen is distinct from a lateral point at a similar level.","kind":"edited-location"},"shared":["First Posterior Sacral Foramen"],"unique":[],"primaryEn":"In the sacral region, in the first posterior sacral foramen.","primaryMeasures":[]},"BL 32":{"anchor":1,"compare":"BL 28","focus":{"he":"BL 32 מתוארת בנקב האחורי השני של העצה. BL 28 משתמשת באותו גובה אך בהיסט 1.5 B-cun מרכס האמצע. זיהוי הנקב עצמו קודם לקריאת הסימונים הצדדיים.","en":"BL 32 uses the second posterior sacral foramen itself. BL 28 shares its level but lies 1.5 B-cun from the median crest. Identify the foramen before the lateral markers.","kind":"edited-location-3.3"},"shared":["Sacral Region","Second Posterior Sacral Foramen"],"unique":["Posterior Superior Iliac Spine","Second Sacral Vertebra"],"primaryEn":"In the sacral region, in the second posterior sacral foramen.","primaryMeasures":[]},"BL 33":{"anchor":1,"compare":"BL 29","focus":{"he":"העוגן הוא הנקב האחורי השלישי של עצם העצה. מספר הנקב מגדיר את הגובה; רשומות אחרות באזור עשויות להשתמש בהיסט צדדי במקום בנקב עצמו.","en":"The reference is the third posterior sacral foramen. Its number defines the level; other regional records may use a lateral offset rather than the foramen itself.","kind":"edited-location"},"shared":["Third Posterior Sacral Foramen"],"unique":[],"primaryEn":"In the sacral region, in the third posterior sacral foramen.","primaryMeasures":[]},"BL 34":{"anchor":1,"compare":"BL 30","focus":{"he":"העוגן הוא הנקב האחורי הרביעי של עצם העצה. אזכור פתח העצה בהערת המקור הוא קשר של גובה, ואינו הופך את שני המבנים לאותו מבנה.","en":"The reference is the fourth posterior sacral foramen. The source note relates its level to the sacral hiatus; these remain different structures.","kind":"edited-location"},"shared":["Fourth Posterior Sacral Foramen","Sacral Hiatus"],"unique":[],"primaryEn":"In the sacral region, in the fourth posterior sacral foramen.","primaryMeasures":[]},"BL 35":{"anchor":1,"compare":"GV 1","focus":{"he":"קצה עצם הזנב הוא העוגן של BL 35, חצי B-cun לצדו. GV 1 מוגדרת בקו האמצע בין עצם הזנב לפי הטבעת. אלה יחסים שונים לאזור, והאיור מציג אותם באופן מופשט.","en":"BL 35 lies half a B-cun lateral to the coccygeal tip. GV 1 uses the midline between coccyx and anus. These are distinct regional relationships shown abstractly in the atlas.","kind":"edited-location-3.3"},"shared":["Coccyx"],"unique":["Buttock"],"primaryEn":"In the buttock region, 0.5 B-cun lateral to the extremity of the coccyx.","primaryMeasures":["0.5 B-cun"]},"BL 36":{"anchor":1,"compare":"BL 37","focus":{"he":"ההגדרה משתמשת באמצע קפל העכוז. זהו קפל שטחי כציון דרך, ולא מרכז שריר העכוז או עצם האגן.","en":"The definition uses the midpoint of the gluteal fold: a surface crease, not the centre of a gluteal muscle or pelvic bone.","kind":"edited-location"},"shared":["Gluteal Fold"],"unique":[],"primaryEn":"In the buttock region, at the midpoint of the gluteal fold.","primaryMeasures":[]},"BL 37":{"anchor":1,"compare":"BL 36","focus":{"he":"BL 36 מספקת עוגן בקפל העכוז; BL 37 נמצאת 6 B-cun מתחת לקפל, בין הדו־ראשי הירכי לחצי־גידי. זהו מרווח בין שרירי הירך, ולא מרכז קפל הברך.","en":"BL 36 supplies the gluteal-fold reference. BL 37 is 6 B-cun below that fold, between biceps femoris and semitendinosus. It is an intermuscular thigh interval rather than the knee-crease centre.","kind":"edited-location-3.3"},"shared":["Gluteal Fold"],"unique":["Thigh","Biceps Femoris","Semitendinosus"],"primaryEn":"On the posterior aspect of the thigh, between the biceps femoris and the semitendinosus muscles, 6 B-cun inferior to the gluteal fold.","primaryMeasures":["6 B-cun"]},"BL 38":{"anchor":1,"compare":"BL 39","focus":{"he":"שתיהן קשורות לגיד הדו־ראשי של הירך בצד החיצוני של אחורי הברך. BL 39 בגובה קפל הברך ו־BL 38 נמצאת 1 B-cun מעליו.","en":"Both relate to the lateral biceps-femoris tendon behind the knee. BL 39 is at the popliteal crease; BL 38 is 1 B-cun above it.","kind":"edited-comparison"},"shared":["Biceps Femoris Tendon","Popliteal Crease"],"unique":["Biceps Femoris"],"primaryEn":"On the posterior aspect of the knee, just medial to the biceps femoris tendon, 1 B-cun proximal to the popliteal crease.","primaryMeasures":["1 B-cun"]},"BL 39":{"anchor":1,"compare":"BL 38","focus":{"he":"שתיהן קשורות לגיד הדו־ראשי של הירך בצד החיצוני של אחורי הברך. BL 39 בגובה קפל הברך ו־BL 38 נמצאת 1 B-cun מעליו.","en":"Both relate to the lateral biceps-femoris tendon behind the knee. BL 39 is at the popliteal crease; BL 38 is 1 B-cun above it.","kind":"edited-comparison"},"shared":["Biceps Femoris Tendon","Popliteal Crease"],"unique":[],"primaryEn":"On the posterolateral aspect of the knee, just medial to the biceps femoris tendon in the popliteal crease.","primaryMeasures":[]},"BL 40":{"anchor":1,"compare":"BL 55","focus":{"he":"קפל בית הברך הוא ציון הדרך, והמיקום הוא באמצעו. זהו המבט האחורי של הברך; אין להשוות את הסימון ישירות לקו הפיקה במבט קדמי.","en":"Use the midpoint of the popliteal crease on the posterior knee. It is not directly interchangeable with the patellar reference on an anterior view.","kind":"edited-location"},"shared":["Popliteal Crease"],"unique":[],"primaryEn":"On the posterior aspect of the knee, at the midpoint of the popliteal crease.","primaryMeasures":[]},"BL 41":{"anchor":1,"compare":"BL 12","focus":{"he":"BL 41 שייכת לעמודה החיצונית יותר, 3 B-cun מקו האמצע, בגובה הגבול התחתון של זיז T2. BL 12 באותו גובה בהיסט 1.5 B-cun; אין לבלבל מספר נקודה עם מספר חוליה.","en":"BL 41 belongs to the outer 3 B-cun column at the inferior T2 spinous-process level. BL 12 shares the level at 1.5 B-cun. Keep point numbers separate from vertebral numbers.","kind":"edited-location-3.3"},"shared":["Upper Back","Second Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the second thoracic vertebra (T2), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 42":{"anchor":1,"compare":"BL 13","focus":{"he":"ההשוואה מתחילה בזיז T3: BL 42 במרחק 3 B-cun מקו האמצע ו־BL 13 במרחק 1.5. הכפלת ההיסט אינה שינוי בגובה החוליה.","en":"Begin at the inferior T3 spinous-process level: BL 42 is 3 B-cun from the midline and BL 13 is 1.5 B-cun away. Doubling the offset does not change the vertebral level.","kind":"edited-location-3.3"},"shared":["Upper Back","Third Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the third thoracic vertebra (T3), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 43":{"anchor":1,"compare":"BL 14","focus":{"he":"BL 43 בגובה הגבול התחתון של זיז T4, בעמודת 3 B-cun. BL 14 היא ההשוואה הפנימית בגובה זה. גבול השכמה באיור מספק הקשר, אך אינו מחליף את שני הנתונים האלה.","en":"BL 43 uses the inferior T4 spinous-process level in the 3 B-cun column. BL 14 is its inner-column comparison. The drawn scapular border gives context without replacing level and offset.","kind":"edited-location-3.3"},"shared":["Upper Back","Fourth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous pro- cess of the fourth thoracic vertebra (T4), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 44":{"anchor":1,"compare":"GV 11","focus":{"he":"BL 44 נמצאת 3 B-cun לצד קו האמצע בגובה שמתחת לזיז T5. GV 11 נמצאת בקו האמצע באותו גובה. מתחילים בזיהוי הזיז וממשיכים למרחק הצדדי.","en":"BL 44 is 3 B-cun lateral at the inferior T5 spinous-process level; GV 11 is midline there. Establish the spinous-process reference before the lateral distance.","kind":"edited-location-3.3"},"shared":["Upper Back","Fifth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the fifth thoracic vertebra (T5), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 45":{"anchor":1,"compare":"BL 16","focus":{"he":"T6 מגדירה את השורה המשותפת ל־BL 45 ול־BL 16. BL 45 מרוחקת 3 B-cun מקו האמצע ו־BL 16 רק 1.5. המראה הצדדי יותר של הסימון אינו מצביע על חוליה אחרת.","en":"T6 defines the shared row for BL 45 and BL 16. BL 45 is 3 B-cun lateral and BL 16 only 1.5. A more lateral marker does not indicate a different vertebra.","kind":"edited-location-3.3"},"shared":["Upper Back","Sixth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the sixth thoracic vertebra (T6), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 46":{"anchor":1,"compare":"BL 47","focus":{"he":"BL 46 משתמשת בגבול התחתון של זיז T7 ובהיסט 3 B-cun. BL 47 נמצאת כבר בגובה T9. גם בעמודה החיצונית רצף המספרים מדלג על גובה T8.","en":"BL 46 uses the inferior T7 spinous-process level at 3 B-cun lateral; BL 47 moves to T9. The outer-column numbering also skips a T8 counterpart.","kind":"edited-location-3.3"},"shared":["Upper Back","Posterior Median Line"],"unique":["Seventh Thoracic Vertebra"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the seventh thoracic vertebra (T7), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 47":{"anchor":1,"compare":"GV 8","focus":{"he":"BL 47 נמצאת 3 B-cun הצדה בגובה שמתחת לזיז T9; GV 8 נמצאת בקו האמצע באותו מפלס. שני הקודים משמשים להשוואת קו אמצע ועמודה חיצונית.","en":"BL 47 lies 3 B-cun lateral at the inferior T9 spinous-process level; GV 8 is midline at that level. The pair contrasts a midline point with the outer column.","kind":"edited-location-3.3"},"shared":["Upper Back","Ninth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the ninth thoracic vertebra (T9), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 48":{"anchor":1,"compare":"BL 19","focus":{"he":"הגבול התחתון של זיז T10 הוא העוגן האנכי. BL 48 מרוחקת 3 B-cun מקו האמצע, פי שניים מן ההיסט המתואר ב־BL 19. הסכמה שומרת יחס לימודי, לא סנטימטרים.","en":"The inferior T10 spinous-process border sets the level. BL 48’s 3 B-cun offset is twice BL 19’s stated offset. The schematic expresses a teaching relationship rather than centimetres.","kind":"edited-location-3.3"},"shared":["Upper Back","Tenth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous pro- cess of the tenth thoracic vertebra (T10), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 49":{"anchor":1,"compare":"GV 6","focus":{"he":"BL 49 נמצאת בגובה הגבול התחתון של זיז T11, 3 B-cun לצד קו האמצע. GV 6 בקו האמצע באותו גובה. צלעות סמוכות באיור אינן משנות את הייחוס לזיז החוליה.","en":"BL 49 is 3 B-cun lateral at the inferior T11 spinous-process level; GV 6 is midline there. Nearby rib drawings do not change the stated spinous-process reference.","kind":"edited-location-3.3"},"shared":["Upper Back","Eleventh Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the 11th thoracic vertebra (T11), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 50":{"anchor":1,"compare":"BL 51","focus":{"he":"BL 50 מסיימת כאן את סדרת החזה ב־T12, בהיסט 3 B-cun. BL 51 ממשיכה ב־L1 שבמותן. שינוי האזור האנטומי מתרחש אף שהעמודה הצדדית נשארת זהה.","en":"BL 50 reaches thoracic T12 with a 3 B-cun offset. BL 51 continues at lumbar L1. The anatomical region changes while the lateral column remains the same.","kind":"edited-location-3.3"},"shared":["Posterior Median Line"],"unique":["Upper Back","Twelfth Thoracic Vertebra"],"primaryEn":"In the upper back region, at the same level as the inferior border of the spinous process of the 12th thoracic vertebra (T12), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 51":{"anchor":1,"compare":"GV 5","focus":{"he":"BL 51 נמצאת 3 B-cun מקו האמצע בגובה הגבול התחתון של זיז L1. GV 5 בקו האמצע באותו מפלס. ה־L מסמנת חוליה מותנית והמספר 1 את הראשונה בסדרה זו.","en":"BL 51 lies 3 B-cun lateral at the inferior L1 spinous-process level; GV 5 is midline there. L identifies the lumbar series and 1 its first vertebra.","kind":"edited-location-3.3"},"shared":["Lumbar Region","First Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the first lumbar vertebra (L1), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 52":{"anchor":1,"compare":"BL 23","focus":{"he":"BL 52 ו־BL 23 חולקות את הגבול התחתון של זיז L2 כעוגן לגובה. ההיסט של BL 52 הוא 3 B-cun ושל BL 23 הוא 1.5. שורת L2 נשארת קבועה במהלך ההשוואה.","en":"BL 52 and BL 23 share the inferior L2 spinous-process level. Their offsets are 3 and 1.5 B-cun. Keep the L2 row fixed while comparing their lateral positions.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Second Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, at the same level as the inferior border of the spinous process of the second lumbar vertebra (L2), 3 B-cun lateral to the posterior median line.","primaryMeasures":["3 B-cun"]},"BL 53":{"anchor":1,"compare":"BL 28","focus":{"he":"הנקב האחורי השני בעצה קובע את הגובה. BL 53 נמצאת 3 B-cun מרכס העצה האמצעי, ו־BL 28 במרחק 1.5. אף אחת מהן אינה הרשומה המתארת את הנקב עצמו.","en":"The second posterior sacral foramen sets the level. BL 53 is 3 B-cun from the median sacral crest and BL 28 is 1.5 B-cun away. Neither record denotes the foramen itself.","kind":"edited-location-3.3"},"shared":["Second Posterior Sacral Foramen","Median Sacral Crest"],"unique":["Buttock"],"primaryEn":"In the buttock region, at the same level as the second posterior sacral foramen, 3 B-cun lateral to the median sacral crest.","primaryMeasures":["3 B-cun"]},"BL 54":{"anchor":1,"compare":"BL 34","focus":{"he":"BL 54 בגובה הנקב האחורי הרביעי, 3 B-cun מרכס העצה האמצעי. BL 34 בנקב עצמו. פתח העצה הוא ציון דרך נפרד המוזכר בהקשר לגובה, ולא שם חלופי לנקב.","en":"BL 54 is at the fourth posterior sacral-foramen level, 3 B-cun from the median crest. BL 34 uses the foramen. The hiatus is a separate level reference, not an alternative foramen name.","kind":"edited-location-3.3"},"shared":["Fourth Posterior Sacral Foramen","Sacral Hiatus"],"unique":["Buttock","Median Sacral Crest"],"primaryEn":"In the buttock region, at the same level as the fourth posterior sacral foramen, 3 B-cun lateral to the median sacral crest.","primaryMeasures":["3 B-cun"]},"BL 55":{"anchor":1,"compare":"BL 56","focus":{"he":"קפל בית הברך הוא מוצא המדידה: BL 55 נמצאת 2 B-cun מתחתיו בין שני ראשי שריר התאומים. BL 56 נמצאת 5 B-cun מתחת לקפל. שתי הרשומות משתמשות באותו קצה מדידה.","en":"The popliteal crease starts both measures. BL 55 is 2 B-cun below it between the gastrocnemius heads; BL 56 is 5 B-cun below. Their distances share the same starting reference.","kind":"edited-location-3.3"},"shared":["Leg","Gastrocnemius Muscle","Popliteal Crease"],"unique":[],"primaryEn":"On the posterior aspect of the leg, between the lateral head and medial head of the gastrocnemius muscle, 2 B-cun distal to the popliteal crease.","primaryMeasures":["2 B-cun"]},"BL 56":{"anchor":1,"compare":"BL 57","focus":{"he":"שתיהן בחלק האחורי של השוק. BL 56 קשורה למרווח בין שני חלקי שריר התאומים; BL 57 לשקע שמתחת למפגש חלקי השריר. היחס לשריר מוסיף מידע מעבר לגובה בלבד.","en":"Both lie on the posterior lower leg. BL 56 uses the interval between the two gastrocnemius bellies; BL 57 the depression below its converging portions. Muscle relationship adds to height alone.","kind":"edited-comparison"},"shared":["Gastrocnemius Muscle"],"unique":["Popliteal Crease"],"primaryEn":"On the posterior aspect of the leg, between the two muscle bellies of the gastrocne- mius muscle, 5 B-cun distal to the popliteal crease.","primaryMeasures":["5 B-cun"]},"BL 57":{"anchor":1,"compare":"BL 56","focus":{"he":"שתיהן בחלק האחורי של השוק. BL 56 קשורה למרווח בין שני חלקי שריר התאומים; BL 57 לשקע שמתחת למפגש חלקי השריר. היחס לשריר מוסיף מידע מעבר לגובה בלבד.","en":"Both lie on the posterior lower leg. BL 56 uses the interval between the two gastrocnemius bellies; BL 57 the depression below its converging portions. Muscle relationship adds to height alone.","kind":"edited-comparison"},"shared":["Gastrocnemius Muscle"],"unique":["Calcaneal Tendon"],"primaryEn":"On the posterior aspect of the leg, at the connecting point of the calcaneal tendon with the two muscle bellies of the gastrocnemius muscle.","primaryMeasures":[]},"BL 58":{"anchor":1,"compare":"BL 57","focus":{"he":"התיאור משלב גובה ביחס ל־BL 60 עם מיקום בין הראש הצדדי של שריר התאומים לגיד אכילס. המספר 7 B-cun לבדו אינו מתאר את הצד ואת היחס לשריר.","en":"The description combines a level relative to BL 60 with the interval between the lateral gastrocnemius head and the calcaneal tendon. The 7 B-cun measure alone does not specify those relationships.","kind":"edited-location"},"shared":["Gastrocnemius Muscle","Calcaneal Tendon"],"unique":[],"primaryEn":"On the posterolateral aspect of the leg, between the inferior border of the lateral head of the gastrocnemius muscle and the calcaneal tendon, at the same level as 7 B-cun proximal to BL60.","primaryMeasures":["7 B-cun"]},"BL 59":{"anchor":1,"compare":"BL 60","focus":{"he":"BL 60 היא עוגן הגובה: BL 59 נמצאת 3 B-cun פרוקסימלית לה, בין השוקית לגיד אכילס. זהו האזור האחורי־חיצוני של השוק, ולא חזית עצם השוקה.","en":"BL 59 is 3 B-cun proximal to BL 60, between the fibula and Achilles tendon. The description concerns the posterolateral leg rather than the front of the tibia.","kind":"edited-location-3.3"},"shared":["Calcaneal Tendon"],"unique":["Leg","Fibula"],"primaryEn":"On the posterolateral aspect of the leg, between the fibula and the calcaneal tendon, at the same level as 3 B-cun proximal to BL60.","primaryMeasures":["3 B-cun"]},"BL 60":{"anchor":1,"compare":"KI 3","focus":{"he":"שתיהן מתוארות בין פטישון לגיד אכילס. BL 60 בצד החיצוני של הקרסול, ו־KI 3 בצדו הפנימי. מעבר בין מבטי כף הרגל חיוני להשוואה הזאת.","en":"Both lie between a malleolus and the Achilles tendon. BL 60 is lateral and KI 3 medial. Switch foot views to understand this comparison.","kind":"edited-comparison"},"shared":["Calcaneal Tendon"],"unique":["Lateral Malleolus"],"primaryEn":"On the posterolateral aspect of the ankle, in the depression between the prominence of the lateral malleolus and the calcaneal tendon.","primaryMeasures":[]},"BL 61":{"anchor":1,"compare":"BL 62","focus":{"he":"העוגן הגרמי הוא עצם העקב בצד החיצוני של כף הרגל. גבול שינוי גוון העור המוזכר במקור הוא ציון דרך נפרד מגבול העצם.","en":"The bony reference is the lateral calcaneus. The skin-colour boundary in the source is a separate surface landmark, not the edge of the bone.","kind":"edited-location"},"shared":["Calcaneus"],"unique":[],"primaryEn":"On the lateral aspect of the foot, distal to BL60, lateral to the calcaneus, at the border between the red and white flesh.","primaryMeasures":[]},"BL 62":{"anchor":1,"compare":"KI 6","focus":{"he":"BL 62 מתוארת מתחת לפטישון החיצוני, בין גבולו התחתון לעצם העקב. KI 6 היא ההשוואה שמתחת לפטישון הפנימי. לפני השוואת הסימונים מחליפים בין הצד החיצוני לפנימי של הקרסול.","en":"BL 62 is below the lateral malleolus, between its inferior border and calcaneus. KI 6 is the medial-malleolar comparison. Establish lateral versus medial ankle before comparing the markers.","kind":"edited-location-3.3"},"shared":["Foot"],"unique":["Lateral Malleolus","Calcaneus"],"primaryEn":"On the lateral aspect of the foot, directly inferior to the prominence of the lateral malleolus, in the depression between the inferior border of the lateral malleolus and the calcaneus.","primaryMeasures":[]},"BL 63":{"anchor":1,"compare":"BL 64","focus":{"he":"BL 63 מתוארת מתחת לעצם הקובייה ומאחורי גבשושית המסרק החמישי. BL 64 נמצאת דיסטלית לגבשושית. הגבשושית מפרידה בין שני התיאורים לאורך הצד החיצוני של כף הרגל.","en":"BL 63 lies inferior to the cuboid and posterior to the fifth-metatarsal tuberosity. BL 64 is distal to the tuberosity. That prominence separates the descriptions along the lateral foot.","kind":"edited-location-3.3"},"shared":["Foot","Fifth Metatarsal Bone"],"unique":["Lateral Malleolus","Cuboid Bone"],"primaryEn":"On the dorsum of the foot, distal to the anterior border of the lateral malleolus, posterior to the tuberosity of the fifth metatarsal bone, in the depression inferior to the cuboid bone.","primaryMeasures":[]},"BL 64":{"anchor":1,"compare":"BL 65","focus":{"he":"BL 64 משתמשת בגבשושית שבבסיס המסרק החמישי, ו־BL 65 באזור שלפני המפרק עם הזרת. הבסיס קרוב לקרסול; ראש המסרק והמפרק קרובים לאצבע.","en":"BL 64 uses the fifth-metatarsal-base tuberosity, while BL 65 concerns the region proximal to the little-toe joint. Base is ankle-facing; head and metatarsophalangeal joint are toe-facing.","kind":"edited-location-3.3"},"shared":["Foot","Metatarsophalangeal Joint Of Pedal Digit 5"],"unique":["Fifth Metatarsal Bone"],"primaryEn":"On the lateral aspect of the foot, distal to the tuberosity of the fifth metatarsal bone, at the border between the red and white flesh.","primaryMeasures":[]},"BL 65":{"anchor":1,"compare":"BL 66","focus":{"he":"BL 65 פרוקסימלית למפרק המסרק־גליל החמישי ו־BL 66 דיסטלית לו. זהו אותו עיקרון של הבחנה משני עברי מפרק, כאן בצד החיצוני של כף הרגל.","en":"BL 65 is proximal and BL 66 distal to the fifth metatarsophalangeal joint. The comparison spans a joint on the lateral foot.","kind":"edited-comparison"},"shared":["Metatarsophalangeal Joint Of Pedal Digit 5"],"unique":[],"primaryEn":"On the lateral aspect of the foot, in the depression proximal to the fifth metatarsophalangeal joint, at the border between the red and white flesh.","primaryMeasures":[]},"BL 66":{"anchor":0,"compare":"BL 65","focus":{"he":"BL 65 פרוקסימלית למפרק המסרק־גליל החמישי ו־BL 66 דיסטלית לו. זהו אותו עיקרון של הבחנה משני עברי מפרק, כאן בצד החיצוני של כף הרגל.","en":"BL 65 is proximal and BL 66 distal to the fifth metatarsophalangeal joint. The comparison spans a joint on the lateral foot.","kind":"edited-comparison"},"shared":["Metatarsophalangeal Joint Of Pedal Digit 5"],"unique":["Little Toe"],"primaryEn":"On the little toe, in the depression distal and lateral to the fifth metatarsophalangeal joint, at the border between the red and white flesh.","primaryMeasures":[]},"BL 67":{"anchor":0,"compare":"GB 44","focus":{"he":"BL 67 קשורה לפינה החיצונית של ציפורן הזרת בכף הרגל, עם היסט פרוקסימלי של 0.1 F-cun. GB 44 קשורה לאצבע הרביעית. זיהוי האצבע קודם לזיהוי הפינה.","en":"BL 67 uses the lateral little-toenail corner with a 0.1 F-cun proximal offset. GB 44 uses the fourth toe. Identify the digit before selecting the nail corner.","kind":"edited-location-3.3"},"shared":["Toenail"],"unique":["Little Toe"],"primaryEn":"On the little toe, lateral to the distal pha- lanx, 0.1 f-cun proximal to the lateral corner of the toenail; at the intersection of the vertical line of the lateral side of the nail and the horizontal line of the base of the toenail.","primaryMeasures":[]},"KI 1":{"anchor":1,"compare":"LR 3","focus":{"he":"KI 1 שייכת לסוליה, בשקע המודגש בכיפוף האצבעות; LR 3 בגב כף הרגל. חלוקת הקו בין העקב לבסיסי האצבעות היא עזר ייחוס, ואינה סיבה להעביר את הסימון לצד הגבי.","en":"KI 1 is plantar, in the depression emphasized by toe flexion; LR 3 is dorsal. The heel-to-toe-base line is a reference and does not transfer the point to the foot’s dorsum.","kind":"edited-location-3.3"},"shared":[],"unique":["Sole Of The Foot","Pedal Digit 2","Pedal Digit 3"],"primaryEn":"On the sole of the foot, in the deepest depression of the sole when the toes are flexed.","primaryMeasures":[]},"KI 2":{"anchor":1,"compare":"SP 5","focus":{"he":"התיאור מציב את הנקודה מתחת לגבשושית עצם הסירה. SP 5 משתמשת באזור קדמי ותחתון לפטישון הפנימי; אין להחליף בין שני ציוני הדרך הגרמיים.","en":"The location is inferior to the navicular tuberosity. SP 5 uses a depression anterior and inferior to the medial malleolus; the bony references differ.","kind":"edited-location"},"shared":["Navicular Bone"],"unique":[],"primaryEn":"On the medial aspect of the foot, inferior to the tuberosity of the navicular bone, at the border between the red and white flesh.","primaryMeasures":[]},"KI 3":{"anchor":1,"compare":"KI 6","focus":{"he":"KI 3 משתמשת במרווח שמאחורי הפטישון הפנימי, לכיוון גיד אכילס. KI 6 מתוארת מתחת לפטישון. מאחור ומתחת הם שני יחסים שונים לאותו ציון דרך.","en":"KI 3 uses the space behind the medial malleolus toward the Achilles tendon. KI 6 is below the malleolus. Posterior and inferior describe different relationships.","kind":"edited-comparison"},"shared":["Medial Malleolus"],"unique":["Calcaneal Tendon"],"primaryEn":"On the posteromedial aspect of the ankle, in the depression between the prominence of the medial malleolus and the calcaneal tendon.","primaryMeasures":[]},"KI 4":{"anchor":1,"compare":"KI 3","focus":{"he":"KI 4 נמצאת מאחור ומתחת לפטישון הפנימי, מעל עצם העקב ולפני אזור האחז של גיד אכילס. KI 3 משתמשת במרווח בגובה הפטישון. יחסי הגובה והאחז מבדילים בין השתיים.","en":"KI 4 is posteroinferior to the medial malleolus, above calcaneus and anterior to the Achilles attachment region. KI 3 uses the interval at malleolar level. Level and attachment relationships distinguish them.","kind":"edited-location-3.3"},"shared":["Medial Malleolus","Calcaneal Tendon"],"unique":["Foot","Calcaneus"],"primaryEn":"On the medial aspect of the foot, posteroinferior to the medial malleolus, superior to the calcaneus, in the depression anterior to the medial attachment of the calcaneal tendon.","primaryMeasures":[]},"KI 5":{"anchor":1,"compare":"KI 6","focus":{"he":"KI 5 מתוארת 1 B-cun מתחת ל־KI 3, לפני גבשושית העקב. KI 6 מתוארת מתחת לפטישון הפנימי. המילה ״מתחת״ מתייחסת בכל כרטיס לעוגן אחר.","en":"KI 5 is 1 B-cun below KI 3, anterior to the calcaneal tuberosity. KI 6 is below the medial malleolus. “Below” starts from a different reference in each record.","kind":"edited-location-3.3"},"shared":["Foot"],"unique":["Calcaneal Tuberosity"],"primaryEn":"On the medial aspect of the foot, 1 B-cun inferior to KI3, in the depression anterior to the calcaneal tuberosity.","primaryMeasures":["1 B-cun"]},"KI 6":{"anchor":1,"compare":"KI 3","focus":{"he":"KI 3 משתמשת במרווח שמאחורי הפטישון הפנימי, לכיוון גיד אכילס. KI 6 מתוארת מתחת לפטישון. מאחור ומתחת הם שני יחסים שונים לאותו ציון דרך.","en":"KI 3 uses the space behind the medial malleolus toward the Achilles tendon. KI 6 is below the malleolus. Posterior and inferior describe different relationships.","kind":"edited-comparison"},"shared":["Medial Malleolus"],"unique":[],"primaryEn":"On the medial aspect of the foot, 1 B-cun inferior to the prominence of the medial malleolus, in the depression inferior to the medial malleolus.","primaryMeasures":["1 B-cun"]},"KI 7":{"anchor":1,"compare":"KI 8","focus":{"he":"שתיהן 2 B-cun מעל הפטישון הפנימי. KI 7 סמוכה לגיד אכילס, ו־KI 8 קדמית יותר וביחס לשוקה. גובה משותף אינו מספיק כדי להבחין ביניהן.","en":"Both are 2 B-cun above the medial malleolus. KI 7 is near the Achilles tendon; KI 8 is more anterior in relation to the tibia. Shared height is insufficient.","kind":"edited-comparison"},"shared":["Medial Malleolus"],"unique":["Calcaneal Tendon"],"primaryEn":"On the posteromedial aspect of the leg, anterior to the calcaneal tendon, 2 B-cun superior to the prominence of the medial malleolus.","primaryMeasures":["2 B-cun"]},"KI 8":{"anchor":1,"compare":"KI 7","focus":{"he":"שתיהן 2 B-cun מעל הפטישון הפנימי. KI 7 סמוכה לגיד אכילס, ו־KI 8 קדמית יותר וביחס לשוקה. גובה משותף אינו מספיק כדי להבחין ביניהן.","en":"Both are 2 B-cun above the medial malleolus. KI 7 is near the Achilles tendon; KI 8 is more anterior in relation to the tibia. Shared height is insufficient.","kind":"edited-comparison"},"shared":["Medial Malleolus"],"unique":["Tibia"],"primaryEn":"On the medial aspect of the leg, in the depression posterior to the medial border of the tibial bone, 2 B-cun superior to the prominence of the medial malleolus.","primaryMeasures":["2 B-cun"]},"KI 9":{"anchor":1,"compare":"LR 5","focus":{"he":"KI 9 ו־LR 5 נמצאות 5 B-cun מעל הפטישון הפנימי. KI 9 קשורה למרווח בין הסוליה לגיד אכילס מאחור, ו־LR 5 לגבול הפנימי של השוקה. אותו גובה אינו אותו מרווח.","en":"KI 9 and LR 5 are 5 B-cun above the medial malleolus. KI 9 uses the soleus–Achilles interval posteriorly; LR 5 uses the medial tibial border. Shared height does not mean shared interval.","kind":"edited-location-3.3"},"shared":["Leg","Medial Malleolus","Tibia"],"unique":["Soleus Muscle","Calcaneal Tendon"],"primaryEn":"On the posteromedial aspect of the leg, between the soleus muscle and the calcaneal tendon, 5 B-cun superior to the prominence of the medial malleolus.","primaryMeasures":["5 B-cun"]},"KI 10":{"anchor":1,"compare":"LR 8","focus":{"he":"קפל בית הברך וגיד השריר החצי־גידי מופיעים יחד. כאן היחס לגיד הוא צדדי, ולא פנימי; יש לקרוא את כיוון היחס לצד שם הגיד.","en":"The popliteal crease and semitendinosus tendon are both references. The stated relationship is lateral to the tendon; read direction along with the tendon name.","kind":"edited-location"},"shared":["Semitendinosus Tendon","Popliteal Crease"],"unique":[],"primaryEn":"On the posteromedial aspect of the knee, just lateral to the semitendinosus tendon, in the popliteal crease.","primaryMeasures":[]},"KI 11":{"anchor":1,"compare":"ST 30","focus":{"he":"KI 11 נמצאת 5 B-cun מתחת לטבור וחצי B-cun לצד קו האמצע. ST 30 נמצאת באותו גובה ייחוס אך בהיסט 2 B-cun. ב־KI המרחק הצדדי קטן ונשאר נפרד ממידת הגובה.","en":"KI 11 is 5 B-cun below the umbilicus and half a B-cun lateral. ST 30 shares that reference level at a 2 B-cun offset. Keep KI’s smaller lateral distance separate from its vertical measure.","kind":"edited-location-3.3"},"shared":["Anterior Median Line"],"unique":["Lower Abdomen","Umbilicus"],"primaryEn":"On the lower abdomen, 5 B-cun inferior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["5 B-cun","0.5 B-cun"]},"KI 12":{"anchor":1,"compare":"CV 3","focus":{"he":"גובה KI 12 הוא 4 B-cun מתחת לטבור, כמו CV 3. KI 12 נמצאת חצי B-cun לצד קו האמצע. אין לפרש את חצי היחידה כתוספת לגובה שמתחת לטבור.","en":"KI 12 shares CV 3’s level, 4 B-cun below the umbilicus, but lies half a B-cun lateral. The half-unit is not added to the inferior umbilical distance.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 4 B-cun inferior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun","0.5 B-cun"]},"KI 13":{"anchor":1,"compare":"CV 4","focus":{"he":"KI 13 ו־CV 4 נמצאות 3 B-cun מתחת לטבור. KI 13 חצי B-cun הצדה, ו־CV 4 בקו האמצע. זיהוי קו האמצע מאפשר להבחין בין הסימונים הקרובים בסכמה.","en":"KI 13 and CV 4 are 3 B-cun below the umbilicus. KI 13 is half a B-cun lateral; CV 4 is midline. Establish the midline to distinguish the nearby schematic markers.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 3 B-cun inferior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["3 B-cun","0.5 B-cun"]},"KI 14":{"anchor":1,"compare":"ST 27","focus":{"he":"KI 14 ו־ST 27 משתמשות בגובה 2 B-cun מתחת לטבור. המרחק מקו האמצע הוא חצי B-cun ב־KI 14 ו־2 B-cun ב־ST 27. כאן ההבדל הוא בעמודה הצדדית בלבד.","en":"KI 14 and ST 27 share a level 2 B-cun below the umbilicus. Their offsets are 0.5 and 2 B-cun. Only the lateral column differs in this comparison.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 2 B-cun inferior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun","0.5 B-cun"]},"KI 15":{"anchor":1,"compare":"CV 7","focus":{"he":"KI 15 נמצאת 1 B-cun מתחת לטבור וחצי B-cun לצד קו האמצע. CV 7 נמצאת בקו האמצע באותה שורה. לפני פירוש הסכמה מבדילים בין מתחת לטבור לבין לצד קו האמצע.","en":"KI 15 is 1 B-cun below the umbilicus and half a B-cun lateral. CV 7 is midline in the same row. Distinguish the inferior umbilical distance from the lateral midline distance.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 1 B-cun inferior to umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["1 B-cun","0.5 B-cun"]},"KI 16":{"anchor":1,"compare":"CV 8","focus":{"he":"הטבור עצמו מגדיר את גובה KI 16. ההיסט היחיד בתיאור הוא חצי B-cun הצדה, בעוד CV 8 במרכז הטבור. אין כאן מידה נוספת מעליו או מתחתיו.","en":"The umbilicus sets KI 16’s level. The only stated offset is half a B-cun laterally; CV 8 is at the umbilical centre. No additional superior or inferior measure is specified.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus"],"unique":[],"primaryEn":"On the upper abdomen, 0.5 B-cun lateral to the centre of the umbilicus.","primaryMeasures":["0.5 B-cun"]},"KI 17":{"anchor":1,"compare":"KI 16","focus":{"he":"KI 17 נמצאת 2 B-cun מעל הטבור, וחצי B-cun מקו האמצע. KI 16 נמצאת בגובה הטבור. במספור הזה המעבר הוא של שתי יחידות גובה, ולא יחידה אחת.","en":"KI 17 is 2 B-cun above the umbilicus and half a B-cun lateral. KI 16 is at umbilical level. This consecutive numbering step spans two vertical units rather than one.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus"],"unique":["Anterior Median Line"],"primaryEn":"On the upper abdomen, 2 B-cun superior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun","0.5 B-cun"]},"KI 18":{"anchor":1,"compare":"CV 11","focus":{"he":"הגובה של KI 18 הוא 3 B-cun מעל הטבור, כמו CV 11. ההיסט הוא חצי B-cun לצד קו האמצע. CV 11 עוזרת לקרוא את השורה מבלי להחליף את העמודה של KI.","en":"KI 18 shares CV 11’s level, 3 B-cun above the umbilicus, with a half-B-cun lateral offset. CV 11 identifies the row without replacing the KI column.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 3 B-cun superior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["3 B-cun","0.5 B-cun"]},"KI 19":{"anchor":1,"compare":"ST 21","focus":{"he":"KI 19 ו־ST 21 נמצאות 4 B-cun מעל הטבור. KI 19 בהיסט חצי B-cun ו־ST 21 בהיסט 2 B-cun. מתאימים את הגובה תחילה, ורק אז משווים את המרחק מן האמצע.","en":"KI 19 and ST 21 are 4 B-cun above the umbilicus. KI 19 uses a 0.5 B-cun offset and ST 21 uses 2. Match the level before comparing the distance from the midline.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 4 B-cun superior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun","0.5 B-cun"]},"KI 20":{"anchor":1,"compare":"CV 13","focus":{"he":"KI 20 נמצאת 5 B-cun מעל הטבור, חצי B-cun לצד קו האמצע. CV 13 מספקת השוואה באמצע באותו גובה. שם האיבר במרידיאן אינו משנה את העוגן האנטומי של התיאור.","en":"KI 20 lies 5 B-cun above the umbilicus and half a B-cun lateral. CV 13 is its midline comparison. The channel’s organ name does not change the anatomical locating reference.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 5 B-cun superior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["5 B-cun","0.5 B-cun"]},"KI 21":{"anchor":1,"compare":"KI 22","focus":{"he":"KI 21 משתמשת במדידה מן הטבור: 6 B-cun מעליו וחצי B-cun הצדה. KI 22 עוברת למרווח בין־צלעי ולהיסט 2 B-cun. המעבר בין הבטן לחזה משנה גם את העוגן וגם את הרוחב.","en":"KI 21 uses umbilical measurement, 6 B-cun above and half a B-cun lateral. KI 22 changes to an intercostal space and a 2 B-cun offset. Both reference type and width change.","kind":"edited-location-3.3"},"shared":["Anterior Median Line"],"unique":["Upper Abdomen","Umbilicus"],"primaryEn":"On the upper abdomen, 6 B-cun superior to the centre of the umbilicus, 0.5 B-cun lateral to the anterior median line.","primaryMeasures":["6 B-cun","0.5 B-cun"]},"KI 22":{"anchor":1,"compare":"ST 18","focus":{"he":"המרווח הבין־צלעי החמישי משותף לשתיהן. KI 22 בהיסט 2 B-cun ו־ST 18 בהיסט 4 B-cun. בעמודת החזה של KI משתמשים ב־2 B-cun, ולא בחצי היחידה של הבטן.","en":"Both use the fifth intercostal space. KI 22 is 2 B-cun lateral and ST 18 is 4. The thoracic KI column uses 2 B-cun, not the abdominal half-unit offset.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fifth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the fifth intercostal space, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"KI 23":{"anchor":1,"compare":"PC 1","focus":{"he":"KI 23 ו־PC 1 נמצאות במרווח הבין־צלעי הרביעי. ההיסטים הם 2 ו־5 B-cun בהתאמה. זו השוואה של שני מסלולים באותו מרווח, עם מיקום צדדי שונה.","en":"KI 23 and PC 1 use the fourth intercostal space at offsets of 2 and 5 B-cun respectively. The comparison crosses channels while holding the intercostal space constant.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fourth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the fourth intercostal space, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"KI 24":{"anchor":1,"compare":"ST 16","focus":{"he":"KI 24 נמצאת במרווח הבין־צלעי השלישי, 2 B-cun מקו האמצע; ST 16 במרחק 4 B-cun באותו מרווח. מזהים את הרווח בין הצלעות ולא את פני הצלע עצמה.","en":"KI 24 lies in the third intercostal space at 2 B-cun from the midline; ST 16 uses 4 B-cun there. Identify the space between ribs rather than the surface of a rib.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Third Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the third intercostal space, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"KI 25":{"anchor":1,"compare":"SP 20","focus":{"he":"המרווח הבין־צלעי השני מגדיר את שורת KI 25. ההיסט שלה הוא 2 B-cun, לעומת 6 B-cun ב־SP 20. הטווח הצדדי גדול אף שמספר המרווח נשאר זהה.","en":"The second intercostal space defines KI 25’s row. Its offset is 2 B-cun versus SP 20’s 6. The lateral separation changes considerably while the space number stays the same.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Second Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the second intercostal space, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"KI 26":{"anchor":1,"compare":"KI 27","focus":{"he":"KI 26 במרווח הבין־צלעי הראשון, 2 B-cun מקו האמצע. KI 27 מתוארת מתחת לעצם הבריח באותה עמודה. יש להבחין בין המרווח הבין־צלעי לבין האזור התת־בריחי.","en":"KI 26 uses the first intercostal space at a 2 B-cun offset. KI 27 is below the clavicle in the same column. Distinguish an intercostal space from the infraclavicular region.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Anterior Median Line"],"unique":["First Intercostal Space"],"primaryEn":"In the anterior thoracic region, in the first intercostal space, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"KI 27":{"anchor":1,"compare":"ST 13","focus":{"he":"שתיהן מתוארות מתחת לעצם הבריח. KI 27 במרחק 2 B-cun מקו האמצע ו־ST 13 במרחק 4 B-cun. כאן עצם הבריח מגדירה את הקשר הגובה, והמידה מגדירה את הצד.","en":"Both are described below the clavicle. KI 27 is 2 B-cun from the midline and ST 13 is 4. The clavicle supplies vertical context while the measurement defines lateral position.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Clavicle","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, just inferior to the clavicle, 2 B-cun lateral to the anterior median line.","primaryMeasures":["2 B-cun"]},"PC 1":{"anchor":1,"compare":"SP 18","focus":{"he":"PC 1 מתוארת במרווח הבין־צלעי הרביעי, 5 B-cun מקו האמצע. SP 18 באותו מרווח בהיסט 6 B-cun. אין להחליף את ה־5 במידת 4 או 6 הנהוגה במסלולים סמוכים.","en":"PC 1 uses the fourth intercostal space at 5 B-cun from the midline; SP 18 uses 6 there. Preserve the five-unit offset rather than substituting a neighbouring channel’s four or six.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fourth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, in the fourth intercostal space, 5 B-cun lateral to the anterior median line.","primaryMeasures":["5 B-cun"]},"PC 2":{"anchor":1,"compare":"LU 3","focus":{"he":"PC 2 נמצאת בין שני ראשי השריר הדו־ראשי, 2 B-cun מתחת לקפל בית השחי הקדמי. LU 3 משתמשת בגבול השריר ובמרחק 3 B-cun. גם היחס לשריר וגם המרחק משתנים.","en":"PC 2 lies between the two biceps heads, 2 B-cun below the anterior axillary fold. LU 3 uses the muscle’s border at 3 B-cun. Both muscle relationship and distance differ.","kind":"edited-location-3.3"},"shared":["Arm","Biceps Brachii Muscle","Anterior Axillary Fold"],"unique":[],"primaryEn":"On the anterior aspect of the arm, between the long head and short head of the biceps brachii muscle, 2 B-cun distal to the anterior axillary fold.","primaryMeasures":["2 B-cun"]},"PC 3":{"anchor":1,"compare":"LU 5","focus":{"he":"קפל המרפק הוא ציון דרך משותף. LU 5 מתוארת בצד הרדיאלי של גיד הדו־ראשי, ו־PC 3 בצדו האולנרי. הגיד עוזר להבין את ההבדל בין צדי הקפל.","en":"Both use the elbow crease. LU 5 is described on the radial side of the biceps tendon and PC 3 on its ulnar side; the tendon distinguishes the sides.","kind":"edited-comparison"},"shared":["Cubital Crease","Biceps Brachii Tendon"],"unique":[],"primaryEn":"On the anterior aspect of the elbow, at the cubital crease, in the depression medial to the biceps brachii tendon.","primaryMeasures":[]},"PC 4":{"anchor":1,"compare":"PC 5","focus":{"he":"שתי הנקודות משתמשות במרווח שבין גידי הכפי הארוך והכופף הרדיאלי. PC 4 נמצאת 5 B-cun מעל הקפל הכפי, ו־PC 5 נמצאת 3. המקור מציין שגיד הכפי הארוך עשוי להיות חסר.","en":"Both use the palmaris-longus–flexor-carpi-radialis interval. PC 4 lies 5 B-cun above the palmar crease; PC 5 lies 3. The source notes that palmaris longus may be absent.","kind":"edited-location-3.3"},"shared":["Forearm","Palmaris Longus Tendon","Tendon of flexor carpi radialis","Palmar Wrist Crease"],"unique":[],"primaryEn":"On the anterior aspect of the forearm, between the tendons of the palmaris longus and the flexor carpi radialis, 5 B-cun proximal to the palmar wrist crease.","primaryMeasures":["5 B-cun"]},"PC 5":{"anchor":1,"compare":"PC 6","focus":{"he":"המרווח בין גיד הכפי הארוך לגיד הכופף הרדיאלי משותף לשתיהן. PC 5 נמצאת 3 B-cun מעל קפל שורש כף היד ו־PC 6 נמצאת 2 B-cun מעליו.","en":"Both use the palmaris-longus–flexor-carpi-radialis tendon interval. PC 5 is 3 B-cun above the wrist crease; PC 6 is 2 B-cun above it.","kind":"edited-comparison"},"shared":["Palmaris Longus Tendon","Tendon of flexor carpi radialis","Palmar Wrist Crease"],"unique":[],"primaryEn":"On the anterior aspect of the forearm, between the tendons of the palmaris longus and the flexor carpi radialis, 3 B-cun proximal to the palmar wrist crease.","primaryMeasures":["3 B-cun"]},"PC 6":{"anchor":1,"compare":"PC 5","focus":{"he":"המרווח בין גיד הכפי הארוך לגיד הכופף הרדיאלי משותף לשתיהן. PC 5 נמצאת 3 B-cun מעל קפל שורש כף היד ו־PC 6 נמצאת 2 B-cun מעליו.","en":"Both use the palmaris-longus–flexor-carpi-radialis tendon interval. PC 5 is 3 B-cun above the wrist crease; PC 6 is 2 B-cun above it.","kind":"edited-comparison"},"shared":["Palmaris Longus Tendon","Tendon of flexor carpi radialis","Palmar Wrist Crease"],"unique":[],"primaryEn":"On the anterior aspect of the forearm, between the tendons of the palmaris longus and the flexor carpi radialis, 2 B-cun proximal to the palmar wrist crease.","primaryMeasures":["2 B-cun"]},"PC 7":{"anchor":1,"compare":"TE 4","focus":{"he":"שתיהן באזור שורש כף היד, אך PC 7 מתוארת בצד הכפי ו־TE 4 בצד הגבי. יש להפוך את המבט ולא להעתיק את הסימון מצד אחד לצד השני.","en":"Both concern the wrist, but PC 7 is palmar and TE 4 dorsal. Change the view rather than transferring a marker between surfaces.","kind":"edited-comparison"},"shared":[],"unique":["Palmaris Longus Tendon","Tendon of flexor carpi radialis","Palmar Wrist Crease"],"primaryEn":"On the anterior aspect of the wrist, between the tendons of palmaris longus and the flexor carpi radialis, on the palmar wrist crease.","primaryMeasures":[]},"PC 8":{"anchor":2,"compare":"HT 8","focus":{"he":"HT 8 משתמשת במרווח שבין עצמות המסרק הרביעית והחמישית. המיקום הראשי של PC 8 הוא בין השנייה לשלישית; החלופה שלו בין השלישית לרביעית.","en":"HT 8 uses the fourth–fifth metacarpal interval. Primary PC 8 uses the second–third interval; its alternative uses the third–fourth interval.","kind":"edited-comparison"},"shared":["Fourth Metacarpal Bone"],"unique":["Second Metacarpal Bone","Third Metacarpal Bone","METACARPOPHALANGEAL JOINT"],"primaryEn":"On the palm of the hand, in the depression between the second and third metacarpal bones, proximal to the metacarpophalangeal joints.","primaryMeasures":[]},"PC 9":{"anchor":0,"compare":"TE 1","focus":{"he":"PC 9 הראשית נמצאת במרכז קצה האצבע האמצעית. TE 1 סמוכה לפינת הציפורן באצבע הקמיצה. גם האצבע וגם סוג ציון הדרך משתנים.","en":"Primary PC 9 is at the middle fingertip centre. TE 1 is near a nail corner of the ring finger. Both the digit and the reference type change.","kind":"edited-comparison"},"shared":[],"unique":["Middle Finger","Nail Of Manual Digit 3"],"primaryEn":"On the middle finger, at the centre of the tip of the middle finger.","primaryMeasures":[]},"TE 1":{"anchor":0,"compare":"PC 9","focus":{"he":"PC 9 הראשית נמצאת במרכז קצה האצבע האמצעית. TE 1 סמוכה לפינת הציפורן באצבע הקמיצה. גם האצבע וגם סוג ציון הדרך משתנים.","en":"Primary PC 9 is at the middle fingertip centre. TE 1 is near a nail corner of the ring finger. Both the digit and the reference type change.","kind":"edited-comparison"},"shared":[],"unique":["Ring Finger","Distal Phalanx","Nail Of Manual Digit 4"],"primaryEn":"On the ring finger, ulnar to the distal phalanx, 0.1 f-cun proximal to the ulnar corner of the fingernail, at the intersection of the vertical line of the ulnar side of the nail and the horizontal line of the base of the fingernail.","primaryMeasures":[]},"TE 2":{"anchor":1,"compare":"TE 3","focus":{"he":"TE 2 מתייחסת לשקע שליד קרום החיבור בין הקמיצה לזרת. TE 3 נמצאת קרוב יותר לשורש כף היד, בין המסרקים הרביעי והחמישי. הקרום שבין האצבעות אינו המפרק שבבסיסן.","en":"TE 2 uses the depression by the ring–little finger web margin. TE 3 is more proximal between the fourth and fifth metacarpals. The web margin is not the joint at the digit bases.","kind":"edited-location-3.3"},"shared":["Dorsum Of The Hand"],"unique":["Ring Finger","Little Finger"],"primaryEn":"On the dorsum of the hand, in the depression superior to the web margin between the ring and little fingers, at the border between the red and white flesh.","primaryMeasures":[]},"TE 3":{"anchor":1,"compare":"TE 2","focus":{"he":"העוגן של TE 3 הוא המפרק הרביעי שבין המסרק לגליל, והמיקום פרוקסימלי לו במרווח המסרקים. TE 2 משתמשת בשולי הקרום בין האצבעות. יש להתקדם מן האצבעות לכיוון כף היד.","en":"TE 3 is proximal to the fourth metacarpophalangeal joint in the metacarpal interval. TE 2 uses the finger-web margin. Follow the anatomy from the digits toward the hand.","kind":"edited-location-3.3"},"shared":["Dorsum Of The Hand"],"unique":["Fourth Metacarpal Bone","Fifth Metacarpal Bone","Metacarpophalangeal Joint Of Manual Digit 4"],"primaryEn":"On the dorsum of the hand, between the fourth and fifth metacarpal bones, in the depression proximal to the fourth metacarpophalangeal joint.","primaryMeasures":[]},"TE 4":{"anchor":1,"compare":"PC 7","focus":{"he":"שתיהן באזור שורש כף היד, אך PC 7 מתוארת בצד הכפי ו־TE 4 בצד הגבי. יש להפוך את המבט ולא להעתיק את הסימון מצד אחד לצד השני.","en":"Both concern the wrist, but PC 7 is palmar and TE 4 dorsal. Change the view rather than transferring a marker between surfaces.","kind":"edited-comparison"},"shared":[],"unique":["Tendon of extensor digitorum","Dorsal Wrist Crease","Fifth Metacarpal Bone","Fourth Metacarpal Bone"],"primaryEn":"On the posterior aspect of the wrist, in the depression ulnar to the extensor digitorum tendon, on the dorsal wrist crease.","primaryMeasures":[]},"TE 5":{"anchor":1,"compare":"TE 6","focus":{"he":"שתיהן משתמשות במרווח שבין החישור לגומד, ולא בשריר בכף היד. המרחק מן הקפל הגבי שונה: 2 B-cun ב־TE 5 ו־3 B-cun ב־TE 6.","en":"Both use the space between radius and ulna, not a muscle in the hand. Their distances from the dorsal wrist crease are 2 B-cun for TE 5 and 3 B-cun for TE 6.","kind":"edited-comparison"},"shared":["Interosseous Space","Radius","Ulna","Dorsal Wrist Crease"],"unique":[],"primaryEn":"On the posterior aspect of the forearm, midpoint of the interosseous space between the radius and the ulna, 2 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["2 B-cun"]},"TE 6":{"anchor":1,"compare":"TE 5","focus":{"he":"שתיהן משתמשות במרווח שבין החישור לגומד, ולא בשריר בכף היד. המרחק מן הקפל הגבי שונה: 2 B-cun ב־TE 5 ו־3 B-cun ב־TE 6.","en":"Both use the space between radius and ulna, not a muscle in the hand. Their distances from the dorsal wrist crease are 2 B-cun for TE 5 and 3 B-cun for TE 6.","kind":"edited-comparison"},"shared":["Interosseous Space","Radius","Ulna","Dorsal Wrist Crease"],"unique":[],"primaryEn":"On the posterior aspect of the forearm, midpoint of the interosseous space between the radius and the ulna, 3 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["3 B-cun"]},"TE 7":{"anchor":1,"compare":"TE 6","focus":{"he":"TE 7 ו־TE 6 נמצאות בגובה 3 B-cun מעל קפל שורש כף היד הגבי. TE 7 קרובה יותר לגומד; אותו גובה אינו אומר אותו מיקום רוחבי.","en":"TE 7 and TE 6 share the 3 B-cun level above the dorsal wrist crease. TE 7 is nearer the ulna; equal level does not mean equal transverse position.","kind":"edited-location"},"shared":["Ulna","Dorsal Wrist Crease"],"unique":[],"primaryEn":"On the posterior aspect of the forearm, just radial to the ulna, 3 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["3 B-cun"]},"TE 8":{"anchor":1,"compare":"TE 6","focus":{"he":"TE 8 נמצאת באמצע המרווח בין החישור לגומד, 4 B-cun מעל הקפל הגבי; TE 6 בגובה 3 B-cun. ״אמצע״ מתייחס לרוחב המרווח בין העצמות, ולא לאמצע אורך האמה.","en":"TE 8 is in the middle of the radius–ulna interval, 4 B-cun above the dorsal crease; TE 6 uses 3. “Middle” describes the interval’s width, not the midpoint of forearm length.","kind":"edited-location-3.3"},"shared":["Forearm","Radius","Ulna","Dorsal Wrist Crease"],"unique":["Elbow"],"primaryEn":"On the posterior aspect of the forearm, midpoint of the interosseous space between the radius and the ulna, 4 B-cun proximal to the dorsal wrist crease.","primaryMeasures":["4 B-cun"]},"TE 9":{"anchor":1,"compare":"TE 10","focus":{"he":"TE 9 מתוארת 5 B-cun דיסטלית לזיז המרפק, באמה. TE 10 מתוארת 1 B-cun פרוקסימלית לזיז, באזור המרפק. כאן גם הכיוון מן הזיז משתנה.","en":"TE 9 lies 5 B-cun distal to the olecranon on the forearm. TE 10 lies 1 B-cun proximal in the elbow region. The direction from the same landmark changes.","kind":"edited-comparison"},"shared":["Olecranon"],"unique":["Interosseous Space","Radius","Ulna"],"primaryEn":"On the posterior aspect of the forearm, midpoint of the interosseous space between the radius and the ulna, 5 B-cun distal to the prominence of the olecranon.","primaryMeasures":["5 B-cun"]},"TE 10":{"anchor":1,"compare":"TE 9","focus":{"he":"TE 9 מתוארת 5 B-cun דיסטלית לזיז המרפק, באמה. TE 10 מתוארת 1 B-cun פרוקסימלית לזיז, באזור המרפק. כאן גם הכיוון מן הזיז משתנה.","en":"TE 9 lies 5 B-cun distal to the olecranon on the forearm. TE 10 lies 1 B-cun proximal in the elbow region. The direction from the same landmark changes.","kind":"edited-comparison"},"shared":["Olecranon"],"unique":["Olecranon Fossa"],"primaryEn":"On the posterior aspect of the elbow, in the depression 1 B-cun proximal to the prominence of the olecranon.","primaryMeasures":["1 B-cun"]},"TE 11":{"anchor":1,"compare":"TE 12","focus":{"he":"הקו המחבר את זיז המרפק לזווית שיא הכתף משותף לשתיהן. TE 11 נמצאת 2 B-cun מעל זיז המרפק, ו־TE 12 נמצאת 5. שתי המידות מתחילות במרפק ופונות אל הכתף.","en":"Both use the olecranon–acromial-angle line. TE 11 lies 2 B-cun proximal to the olecranon; TE 12 lies 5. Both measurements start at the elbow and run toward the shoulder.","kind":"edited-location-3.3"},"shared":["Arm","Olecranon"],"unique":["Elbow"],"primaryEn":"On the posterior aspect of the arm, on the line connecting the prominence of olecranon with the acromial angle, 2 B-cun proximal to the prominence of the olecranon.","primaryMeasures":["2 B-cun"]},"TE 12":{"anchor":1,"compare":"TE 13","focus":{"he":"TE 12 נמדדת מן המרפק: 5 B-cun לכיוון הכתף. TE 13 נמדדת מזווית שיא הכתף: 3 B-cun כלפי מטה. אין לחבר או לחסר את המספרים בלי להתחשב במוצא המדידה.","en":"TE 12 is measured 5 B-cun from the olecranon toward the shoulder. TE 13 is measured 3 B-cun inferiorly from the acromial angle. Their starting references differ.","kind":"edited-location-3.3"},"shared":["Arm"],"unique":["Olecranon"],"primaryEn":"On the posterior aspect of the arm, on the line connecting the prominence of the olecranon with the acromial angle, 5 B-cun proximal to the prominence of the olecranon.","primaryMeasures":["5 B-cun"]},"TE 13":{"anchor":1,"compare":"LI 14","focus":{"he":"TE 13 קשורה לאזור שמאחור ומתחת לגבול שריר הדלתא, 3 B-cun מתחת לזווית שיא הכתף. LI 14 משתמשת בגבול הקדמי של השריר. זיהוי הצד של הדלתא מבחין בין התיאורים.","en":"TE 13 is posteroinferior to the deltoid border, 3 B-cun below the acromial angle. LI 14 uses the anterior deltoid border. Identify the muscle’s side before comparing positions.","kind":"edited-location-3.3"},"shared":["Arm","Deltoid Muscle"],"unique":[],"primaryEn":"On the posterior aspect of the arm, posteroinferior to the border of the deltoid muscle, 3 B-cun inferior to the acromial angle.","primaryMeasures":["3 B-cun"]},"TE 14":{"anchor":1,"compare":"LI 15","focus":{"he":"שתי הנקודות קשורות לכתף ולזיז שיא הכתף. LI 15 מתוארת בשקע הקדמי־תחתון ביחס אליו, ו־TE 14 בשקע האחורי־תחתון. מבט קדמי בלבד עלול להסתיר את ההבדל.","en":"Both concern the shoulder and acromion. LI 15 uses the anteroinferior depression and TE 14 the posteroinferior depression. An anterior view alone obscures the distinction.","kind":"edited-comparison"},"shared":["Acromion","Greater Tubercle Of The Humerus"],"unique":[],"primaryEn":"On the shoulder girdle, in the depression between the acromial angle and the greater tubercle of the humerus.","primaryMeasures":[]},"TE 15":{"anchor":1,"compare":"SI 12","focus":{"he":"העוגן הוא הזווית העליונה של השכמה והשקע שמעליה. אין לבלבל את הזווית העליונה עם קוץ השכמה או עם שיא הכתף.","en":"Use the superior scapular angle and the depression above it. Distinguish that angle from the scapular spine and the acromion.","kind":"edited-location"},"shared":["Scapula"],"unique":[],"primaryEn":"In the scapular region, in the depression superior to the superior angle of the scapula.","primaryMeasures":[]},"TE 16":{"anchor":1,"compare":"SI 17","focus":{"he":"גובה זווית הלסת משותף להשוואה עם SI 17. TE 16 מתוארת בשקע שמאחורי שריר מפנה הראש; SI 17 לפני השריר.","en":"The mandibular-angle level links the comparison with SI 17. TE 16 is posterior to sternocleidomastoid, whereas SI 17 is anterior.","kind":"edited-location"},"shared":["Mandible","Sternocleidomastoid Muscle"],"unique":[],"primaryEn":"In the anterior region of the neck, at the same level as the angle of the mandible, in the depression posterior to the sternocleidomastoid muscle.","primaryMeasures":[]},"TE 17":{"anchor":1,"compare":"GB 12","focus":{"he":"TE 17 נמצאת מאחורי תנוך האוזן ולפני הקצה התחתון של הזיז הפטמתי. GB 12 מאחור ומתחת לזיז. התנוך והזיז הגרמי ממלאים תפקידים שונים בתיאור.","en":"TE 17 is behind the earlobe and anterior to the mastoid’s inferior end. GB 12 is posteroinferior to the mastoid. The earlobe and bony process play different locating roles.","kind":"edited-location-3.3"},"shared":["Neck","Mastoid Process"],"unique":["Ear Lobe"],"primaryEn":"In the anterior region of the neck, posterior to the ear lobe, in the depression anterior to the inferior end of the mastoid process.","primaryMeasures":[]},"TE 18":{"anchor":1,"compare":"TE 17","focus":{"he":"TE 18 ו־TE 19 מחלקות את הקו הקמור בין TE 17 ל־TE 20. TE 18 נמצאת במפגש שני השלישים העליונים והשליש התחתון, ולכן אין לקרוא את השליש מהקצה הלא נכון.","en":"TE 18 and TE 19 divide the TE 17–TE 20 curve. TE 18 is at the upper-two-thirds/lower-third junction; the starting end matters.","kind":"edited-location"},"shared":["Mastoid Process"],"unique":[],"primaryEn":"On the head, at the centre of the mastoid process, at the junction of the upper two thirds and lower one third of the curved line from tE17 to tE20.","primaryMeasures":[]},"TE 19":{"anchor":0,"compare":"TE 18","focus":{"he":"הקו הקמור מחבר את TE 17 עם TE 20. כאן החלוקה היא שליש עליון ושני שלישים תחתונים — קרוב יותר לקצה העליון מאשר TE 18.","en":"On the TE 17–TE 20 curve, this is the upper-third/lower-two-thirds junction, nearer the upper end than TE 18.","kind":"edited-location"},"shared":[],"unique":[],"primaryEn":"On the head, at the junction of the upper one third and lower two thirds of the curved line from tE17 to tE20.","primaryMeasures":[]},"TE 20":{"anchor":1,"compare":"GB 7","focus":{"he":"העוגן הוא קודקוד אפרכסת האוזן, והמיקום מתואר מיד מעליו. אין להחליף בין קודקוד האפרכסת, שורש האוזן ופתח תעלת האוזן.","en":"The reference is the auricular apex, with the point immediately superior to it. Distinguish the apex, auricular root and ear-canal opening.","kind":"edited-location"},"shared":["ear"],"unique":[],"primaryEn":"On the head, just superior to the auricular apex.","primaryMeasures":[]},"TE 21":{"anchor":1,"compare":"SI 19","focus":{"he":"TE 21 מתוארת בגובה החריץ שמעל הטרגוס, ו־SI 19 בגובה אמצע הטרגוס. שינוי הגובה לאורך אותה אוזן הוא מוקד ההשוואה.","en":"TE 21 uses the supratragic notch level, while SI 19 uses the middle of the tragus. The differing level along the same ear is the focus.","kind":"edited-comparison"},"shared":[],"unique":["supratragic notch","Condyloid Process"],"primaryEn":"On the face, in the depression between the supratragic notch and the condylar process of the mandible.","primaryMeasures":[]},"TE 22":{"anchor":1,"compare":"TE 20","focus":{"he":"TE 22 מתוארת לפני שורש האפרכסת ומאחורי קו השיער ברקה. TE 20 משתמשת בקודקוד האפרכסת. שורש האוזן וקודקודה אינם שתי דרכים לציין את אותו קו גובה.","en":"TE 22 lies anterior to the auricular root and posterior to the temporal hairline. TE 20 uses the auricular apex. Root and apex are distinct ear references.","kind":"edited-location-3.3"},"shared":["Head"],"unique":["Hairline","Auricular Root","Superficial Temporal Artery"],"primaryEn":"On the head, posterior to the temple hairline, anterior to the auricular root, posterior to the superficial temporal artery.","primaryMeasures":[]},"TE 23":{"anchor":1,"compare":"BL 2","focus":{"he":"TE 23 משתמשת בשקע שבקצה החיצוני של הגבה; BL 2 בשקע שבקצה הפנימי. קודם מזהים את הצד הקרוב לאף ואת הצד הקרוב לרקה, ואז את שקע הגבה המתאים.","en":"TE 23 uses the depression at the lateral eyebrow end; BL 2 uses the medial end. Establish nasal versus temporal direction before selecting the eyebrow depression.","kind":"edited-location-3.3"},"shared":["Head","Eyebrow"],"unique":[],"primaryEn":"On the head, in the depression at the lateral end of the eyebrow.","primaryMeasures":[]},"GB 1":{"anchor":1,"compare":"BL 1","focus":{"he":"ההבחנה היא זווית העין: BL 1 בזווית הפנימית, סמוך לאף; GB 1 בזווית החיצונית. פנימי וחיצוני מתייחסים לפנים של האדם, לא לצד המסך.","en":"The distinction is the eye angle: BL 1 uses the inner, nasal angle; GB 1 the outer angle. These directions belong to the person, not to screen left and right.","kind":"edited-comparison"},"shared":["Eye"],"unique":["Outer Canthus"],"primaryEn":"On the head, in the depression, 0.5 B-cun lateral to the outer canthus of the eye.","primaryMeasures":["0.5 B-cun"]},"GB 2":{"anchor":1,"compare":"SI 19","focus":{"he":"שתיהן סמוכות לאוזן, אך SI 19 מתייחסת לאמצע הטרגוס ו־GB 2 לחריץ שבין הטרגוס לאנטיטרגוס. קוד הנקודה אינו מחליף זיהוי של מבנה האוזן.","en":"Both are near the ear: SI 19 uses the middle of the tragus, whereas GB 2 uses the intertragic notch. Identify the ear structure rather than relying on the code.","kind":"edited-comparison"},"shared":[],"unique":["Intertragic Notch","Condyloid Process"],"primaryEn":"On the face, in the depression between the intertragic notch and the condylar process of the mandible.","primaryMeasures":[]},"GB 3":{"anchor":1,"compare":"ST 7","focus":{"he":"קשת עצם הלחי מפרידה בין שני תיאורים: GB 3 מעל אמצע הקשת, ו־ST 7 מתחתיה. היחס מעל/מתחת חשוב יותר מקרבת הסימונים בתרשים.","en":"The zygomatic arch separates the definitions: GB 3 is above its midpoint and ST 7 below it. Above versus below is more informative than schematic proximity.","kind":"edited-location"},"shared":["Zygomatic Arch"],"unique":[],"primaryEn":"On the head, in the depression superior to the midpoint of the zygomatic arch","primaryMeasures":[]},"GB 4":{"anchor":0,"compare":"GB 5","focus":{"he":"GB 4, GB 5 ו־GB 6 מחלקות את הקו הקמור בין ST 8 ל־GB 7. GB 4 נמצאת ברבע העליון של הקו, סמוך יותר לקצה ST 8.","en":"GB 4, GB 5 and GB 6 divide the ST 8–GB 7 curve. GB 4 is at its upper-quarter junction, nearer ST 8.","kind":"edited-location"},"shared":[],"unique":[],"primaryEn":"On the head, at the junction of the upper one fourth and lower three fourths of the curved line from St8 to gB7.","primaryMeasures":[]},"GB 5":{"anchor":0,"compare":"GB 4","focus":{"he":"GB 5 מתוארת באמצע הקו הקמור בין ST 8 ל־GB 7. זהו אמצע קו הייחוס המתואר, ולא בהכרח מרכז הרקה כולה.","en":"GB 5 is the midpoint of the ST 8–GB 7 curve, not necessarily the centre of the entire temple region.","kind":"edited-location"},"shared":[],"unique":[],"primaryEn":"On the head, at the midpoint of the curved line from St8 to gB7.","primaryMeasures":[]},"GB 6":{"anchor":0,"compare":"GB 5","focus":{"he":"המיקום מחלק את קו ST 8–GB 7 לשלושה רבעים עליונים ורבע תחתון. לכן GB 6 קרובה יותר לקצה GB 7 מאשר GB 4 ו־GB 5.","en":"The ST 8–GB 7 curve is divided into upper three quarters and a lower quarter. GB 6 is therefore nearer GB 7 than GB 4 or GB 5.","kind":"edited-location"},"shared":[],"unique":[],"primaryEn":"On the head, at the junction of the upper three fourths and lower one fourth of the curved line from St8 to gB7.","primaryMeasures":[]},"GB 7":{"anchor":1,"compare":"GB 8","focus":{"he":"התיאור משתמש במפגש שני קווי ייחוס: קו אנכי של הגבול האחורי של קו השיער ברקה, וקו אופקי בגובה קודקוד האפרכסת.","en":"The description intersects two references: a vertical line at the posterior temporal hairline border and a horizontal line through the auricular apex.","kind":"edited-location"},"shared":["Hairline","ear"],"unique":[],"primaryEn":"On the head, at the junction of the vertical line of the posterior border of the temple hairline and the horizontal line of the apex of the auricle.","primaryMeasures":[]},"GB 8":{"anchor":1,"compare":"GB 10","focus":{"he":"קודקוד האפרכסת קובע את הקו האנכי, וקו השיער ברקה הוא מוצא המרחק של 1.5 B-cun. אלה שני תפקידים שונים של ציוני הדרך.","en":"The auricular apex establishes vertical alignment; the temporal hairline starts the 1.5 B-cun measure. These landmarks serve different roles.","kind":"edited-location"},"shared":["ear","Hairline"],"unique":[],"primaryEn":"On the head, directly superior to the auricular apex, 1.5 B-cun superior to the temporal hairline.","primaryMeasures":["1.5 B-cun"]},"GB 9":{"anchor":1,"compare":"TE 22","focus":{"he":"ההתייחסות היא לגבול האחורי של שורש האפרכסת, ולא לקודקוד שלה. הגובה מתואר כ־2 B-cun מעל קו השיער.","en":"The reference is the posterior auricular-root border rather than the apex. The stated level is 2 B-cun above the hairline.","kind":"edited-location"},"shared":["Auricular Root","Hairline"],"unique":[],"primaryEn":"On the head, directly superior to the posterior border of the auricular root, 2 B-cun superior to the hairline.","primaryMeasures":["2 B-cun"]},"GB 10":{"anchor":1,"compare":"GB 11","focus":{"he":"GB 10 ו־GB 11 מחלקות את הקו הקמור מ־GB 9 ל־GB 12. GB 10 במפגש השליש העליון ושני השלישים התחתונים; GB 11 בחלוקה ההפוכה. שני המקומות שונים לאורך אותו קו.","en":"GB 10 and GB 11 divide the GB 9–GB 12 curve. GB 10 is at the upper-third/lower-two-thirds junction; GB 11 uses the opposite fraction. These are distinct positions on one curve.","kind":"edited-location-3.3"},"shared":["Head","Mastoid Process"],"unique":["ear","Hairline"],"primaryEn":"On the head, posterosuperior to the mastoid process, at the junction of the upper one third and lower two thirds of the curved line from gB9 to gB12.","primaryMeasures":[]},"GB 11":{"anchor":1,"compare":"GB 10","focus":{"he":"GB 11 מחלקת את הקו הקמור בין GB 9 ל־GB 12 לשני שלישים עליונים ושליש תחתון. קראו גם את היחס לזיז הפטמתי, ולא רק את חלוקת הקו.","en":"GB 11 divides the GB 9–GB 12 curve into upper two thirds and a lower third. Read its mastoid relationship as well as the curve fraction.","kind":"edited-location"},"shared":["Mastoid Process"],"unique":[],"primaryEn":"On the head, posterior and superior to the mastoid process, at the junction of the up- per two thirds and lower one third of the curved line from gB 9 to gB12.","primaryMeasures":[]},"GB 12":{"anchor":1,"compare":"GB 11","focus":{"he":"השקע מתואר מאחור ומתחת לזיז הפטמתי. שתי מילות הכיוון נדרשות: מאחור לבדה או מתחת לבדה אינן משחזרות את התיאור.","en":"The depression is posteroinferior to the mastoid process. Both directional components matter; posterior or inferior alone is incomplete.","kind":"edited-location"},"shared":["Mastoid Process"],"unique":[],"primaryEn":"In the anterior region of the neck, in the depression posteroinferior to the mastoid process.","primaryMeasures":[]},"GB 13":{"anchor":1,"compare":"BL 4","focus":{"he":"שתיהן חצי B-cun מעל קו השיער הקדמי. GB 13 במרחק 3 B-cun מקו האמצע ו־BL 4 במרחק 1.5. הגובה זהה וההיסט של GB 13 כפול, לפי הגדרת המקור.","en":"Both are half a B-cun above the anterior hairline. GB 13 is 3 B-cun lateral and BL 4 is 1.5. Their height is shared while GB 13’s stated offset is twice as large.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 0.5 B-cun superior to the anterior hairline, 3 B-cun lateral to the anterior median line.","primaryMeasures":["0.5 B-cun","3 B-cun"]},"GB 14":{"anchor":1,"compare":"GB 15","focus":{"he":"GB 14 נמצאת 1 B-cun מעל הגבה, בקו האישון. GB 15 משתמשת באותו קו אישון אך בחצי B-cun בתוך קו השיער. גבה וקו שיער הם שני מוצאי מדידה שונים.","en":"GB 14 is 1 B-cun above the eyebrow on the pupil line. GB 15 follows that alignment but is half a B-cun within the hairline. Eyebrow and hairline are different starting references.","kind":"edited-location-3.3"},"shared":["Head","Pupil"],"unique":["Eyebrow"],"primaryEn":"On the head, 1 B-cun superior to the eyebrow, directly superior to the centre of the pupil.","primaryMeasures":["1 B-cun"]},"GB 15":{"anchor":1,"compare":"GV 24","focus":{"he":"GB 15 ו־GV 24 חצי B-cun בתוך קו השיער הקדמי. GB 15 בקו שמעל מרכז האישון, ו־GV 24 בקו האמצע. הכיוון הצדדי נשען על האישון ולא על פינת העין.","en":"GB 15 and GV 24 are half a B-cun within the anterior hairline. GB 15 follows the pupil-centre line; GV 24 is midline. The alignment uses the pupil, not the eye corner.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline"],"unique":["Pupil"],"primaryEn":"On the head, 0.5 B-cun within the anterior hairline, directly superior to the centre of the pupil.","primaryMeasures":["0.5 B-cun"]},"GB 16":{"anchor":1,"compare":"GB 15","focus":{"he":"GB 16 ממשיכה על קו האישון, 1.5 B-cun בתוך קו השיער הקדמי. GB 15 נמצאת חצי B-cun בתוך הקו. ההפרש הוא יחידה אחת לאורך הקרקפת, עם אותו יישור צדדי.","en":"GB 16 follows the pupil line 1.5 B-cun within the anterior hairline; GB 15 lies half a B-cun within it. The difference is one unit along the scalp with the same alignment.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Pupil"],"unique":[],"primaryEn":"On the head, 1.5 B-cun within the anterior hairline, directly superior to the centre of the pupil.","primaryMeasures":["1.5 B-cun"]},"GB 17":{"anchor":1,"compare":"BL 6","focus":{"he":"GB 17 ו־BL 6 נמצאות 2.5 B-cun מקו השיער הקדמי. GB 17 מיושרת לאישון, ו־BL 6 לעמודה של 1.5 B-cun מקו האמצע. אותו מרחק מקו השיער אינו אותה עמודה.","en":"GB 17 and BL 6 are 2.5 B-cun from the anterior hairline. GB 17 follows the pupil alignment; BL 6 follows the 1.5 B-cun lateral column. Hairline distance alone does not distinguish them.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline"],"unique":["Pupil"],"primaryEn":"On the head, 2.5 B-cun within the anterior hairline, directly superior to the centre of the pupil.","primaryMeasures":["2.5 B-cun"]},"GB 18":{"anchor":1,"compare":"BL 7","focus":{"he":"הגובה היחסי של GB 18 הוא 4 B-cun בתוך קו השיער הקדמי, כמו BL 7. קו האישון מבדיל את העמודה של GB. זהו מבט פרוס של הקרקפת; הכיוון במסך אינו תנועת ראש.","en":"GB 18 and BL 7 share a distance of 4 B-cun from the anterior hairline. Pupil alignment distinguishes the GB column. A flattened scalp view represents references rather than head movement.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline"],"unique":["Pupil"],"primaryEn":"On the head, 4 B-cun within the anterior hairline, directly superior to the centre of the pupil.","primaryMeasures":["4 B-cun"]},"GB 19":{"anchor":1,"compare":"BL 9","focus":{"he":"הגובה קשור לגבול העליון של הבליטה העורפית החיצונית, והיישור האנכי הוא מעל GB 20. ציון הדרך הגרמי והנקודה השכנה ממלאים תפקידים שונים.","en":"The superior external-occipital-protuberance border sets the level; GB 20 sets vertical alignment. Bone and neighbouring point serve different roles.","kind":"edited-location"},"shared":["External Occipital Protuberance"],"unique":[],"primaryEn":"On the head, at the same level as the supe- rior border of the external occipital protu- berance, directly superior to gB20.","primaryMeasures":[]},"GB 20":{"anchor":1,"compare":"GV 16","focus":{"he":"GB 20 מתוארת מתחת לעצם העורף, בשקע בין אזורי המוצא של מפנה הראש והטרפז. GV 16 בקו האמצע בגובה דומה. השקע בין השרירים הוא ההבחנה הצדדית המרכזית.","en":"GB 20 is below the occiput in the depression between sternocleidomastoid and trapezius origins. GV 16 is midline at a similar level. The intermuscular depression defines the lateral distinction.","kind":"edited-location-3.3"},"shared":["Neck","Trapezius"],"unique":["Occipital Bone","Sternocleidomastoid"],"primaryEn":"In the anterior region of the neck, inferior to the occipital bone, in the depression between the origins of sternocleidomastoid and the trapezius muscles.","primaryMeasures":[]},"GB 21":{"anchor":1,"compare":"GV 14","focus":{"he":"GB 21 היא אמצע הקו בין זיז C7 לקצה הצדדי של שיא הכתף. GV 14 נמצאת מתחת לזיז C7 בקו האמצע. אמצע הקו אינו אמצע הצוואר או אמצע עצם הבריח.","en":"GB 21 is the midpoint between the C7 spinous process and lateral acromial end. GV 14 is midline below C7. This line’s midpoint is neither the neck centre nor the clavicular midpoint.","kind":"edited-location-3.3"},"shared":["Neck","Seventh Cervical Vertebra"],"unique":["Acromion"],"primaryEn":"In the posterior region of the neck, at the midpoint of the line connecting the spinous process of the seventh cervical vertebra (C7) with the lateral end of the acromion.","primaryMeasures":[]},"GB 22":{"anchor":1,"compare":"GB 23","focus":{"he":"המרווח הבין־צלעי הרביעי משותף לשתי הנקודות. GB 22 על הקו האמצעי של בית השחי; GB 23 במרחק 1 B-cun לפניו. ״לפני״ מתייחס לכיוון קדמת הגוף.","en":"Both points use the fourth intercostal space. GB 22 lies on the midaxillary line; GB 23 is 1 B-cun anterior to it. Anterior refers toward the body’s front.","kind":"edited-location-3.3"},"shared":["Lateral Thoracic Region","Fourth Intercostal Space","Midaxillary Line"],"unique":[],"primaryEn":"In the lateral thoracic region, in the fourth intercostal space, on the midaxillary line.","primaryMeasures":[]},"GB 23":{"anchor":1,"compare":"GB 22","focus":{"he":"GB 23 נמצאת במרווח הרביעי, 1 B-cun קדמית לקו אמצע בית השחי. GB 22 נמצאת על הקו עצמו. שינוי ההיסט הקדמי אינו מעבר למרווח הבין־צלעי הבא.","en":"GB 23 is in the fourth space, 1 B-cun anterior to the midaxillary line; GB 22 lies on the line. An anterior offset does not move the point into the next intercostal space.","kind":"edited-location-3.3"},"shared":["Lateral Thoracic Region","Fourth Intercostal Space","Midaxillary Line"],"unique":[],"primaryEn":"In the lateral thoracic region, in the fourth intercostal space, 1 B-cun anterior to the midaxillary line.","primaryMeasures":["1 B-cun"]},"GB 24":{"anchor":1,"compare":"LR 14","focus":{"he":"GB 24 נמצאת במרווח הבין־צלעי השביעי, בהיסט 4 B-cun; LR 14 במרווח השישי באותו היסט. זו השוואה של מרווחים סמוכים, ולא של שני קווי רוחב שונים.","en":"GB 24 uses the seventh intercostal space at a 4 B-cun offset; LR 14 uses the sixth at the same offset. The comparison changes intercostal space rather than lateral column.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Anterior Median Line","Nipple"],"unique":["Seventh Intercostal Space","Midclavicular Line"],"primaryEn":"In the anterior thoracic region, in the sev- enth intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"GB 25":{"anchor":1,"compare":"LR 13","focus":{"he":"שתיהן קשורות לקצה חופשי של צלע בצד הגוף: LR 13 לצלע ה־11 ו־GB 25 לצלע ה־12. יש לזהות את הצלע המתוארת לפני השוואת מיקומן בסכמה.","en":"Both use a free rib end on the flank: LR 13 rib 11 and GB 25 rib 12. Identify the named rib before comparing schematic positions.","kind":"edited-comparison"},"shared":["Costal Arch"],"unique":["Twelfth Rib","Posterior Axillary Line"],"primaryEn":"On the lateral abdomen, inferior to the free extremity of the 12th rib.","primaryMeasures":[]},"GB 26":{"anchor":1,"compare":"LR 13","focus":{"he":"GB 26 בגובה הטבור ומתחת לקצה החופשי של הצלע ה־11. LR 13 קשורה לקצה הצלע עצמו. הצלע נותנת את היחס האנכי, והטבור מוסיף שורת גובה נפרדת.","en":"GB 26 is level with the umbilicus and inferior to the free end of rib 11. LR 13 uses that rib end itself. Rib relationship and umbilical level provide separate locating information.","kind":"edited-location-3.3"},"shared":["Abdomen","Eleventh Rib","Costal Arch"],"unique":["Umbilicus"],"primaryEn":"On the lateral abdomen, inferior to the free extremity of the 11th rib, at the same level as the centre of umbilicus.","primaryMeasures":[]},"GB 27":{"anchor":1,"compare":"GB 28","focus":{"he":"GB 27 נמצאת 3 B-cun מתחת לטבור, מדיאלית לקוץ הכסל הקדמי העליון. GB 28 מתוארת חצי B-cun מדיאלית ותחתונה לקוץ. יש לקרוא את העוגן של כל מידה במפורש.","en":"GB 27 is 3 B-cun below the umbilicus, medial to the ASIS. GB 28 is half a B-cun medioinferior to the ASIS. Read the starting landmark for each measure explicitly.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Anterior Superior Iliac Spine"],"unique":["Umbilicus"],"primaryEn":"On the lower abdomen, 3 B-cun inferior to the centre of umbilicus, medial to the anterior superior iliac spine.","primaryMeasures":["3 B-cun"]},"GB 28":{"anchor":1,"compare":"GB 27","focus":{"he":"קוץ הכסל הקדמי העליון הוא עוגן המיקום הראשי של GB 28: חצי B-cun מדיאלית ותחתונה ממנו. GB 27 כוללת גם גובה ביחס לטבור. אין להסתפק במילים ״ליד האגן״.","en":"The ASIS anchors primary GB 28: half a B-cun medioinferior to it. GB 27 also specifies an umbilical level. “Near the pelvis” does not capture these directional relationships.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Anterior Superior Iliac Spine"],"unique":[],"primaryEn":"On the lower abdomen, 0.5 B-cun medioin- ferior to the anterior superior iliac spine.","primaryMeasures":["0.5 B-cun"]},"GB 29":{"anchor":1,"compare":"GB 30","focus":{"he":"GB 29 משתמשת באמצע הקו שבין קוץ הכסל הקדמי העליון לתל הגדול. GB 30 הראשית משתמשת בקו אחר, מן התל הגדול לפתח העצה. החלופה של GB 30 חוזרת לקו הקדמי, אך בחלוקה שונה.","en":"GB 29 uses the midpoint of the ASIS–greater-trochanter line. Primary GB 30 uses a different line toward the sacral hiatus. Its alternative uses the anterior line but a different division.","kind":"edited-comparison"},"shared":["Anterior Superior Iliac Spine","Greater Trochanter"],"unique":[],"primaryEn":"In the buttock region, midpoint of the line connecting the anterior superior iliac spine and the prominence of the greater trochanter.","primaryMeasures":[]},"GB 30":{"anchor":1,"compare":"GB 29","focus":{"he":"GB 29 משתמשת באמצע הקו שבין קוץ הכסל הקדמי העליון לתל הגדול. GB 30 הראשית משתמשת בקו אחר, מן התל הגדול לפתח העצה. החלופה של GB 30 חוזרת לקו הקדמי, אך בחלוקה שונה.","en":"GB 29 uses the midpoint of the ASIS–greater-trochanter line. Primary GB 30 uses a different line toward the sacral hiatus. Its alternative uses the anterior line but a different division.","kind":"edited-comparison"},"shared":["Greater Trochanter","Anterior Superior Iliac Spine"],"unique":["Sacral Hiatus"],"primaryEn":"In the buttock region, at the junction of the lateral one third and medial two thirds of the line connecting the prominence of the greater trochanter with the sacral hiatus.","primaryMeasures":[]},"GB 31":{"anchor":1,"compare":"GB 32","focus":{"he":"ההגדרה משלבת את הצד האחורי של הרצועה האיליוטיביאלית עם תנוחת עמידה וזרוע תלויה. לכן אין להסיק את מיקומה ממספר קבוע בתרשים בלבד.","en":"The definition combines a position posterior to the iliotibial band with standing posture and a hanging arm. A fixed schematic number alone cannot reproduce it.","kind":"edited-location"},"shared":["Iliotibial Band"],"unique":[],"primaryEn":"On the lateral aspect of the thigh, in the depression posterior to the iliotibial band where the tip of the middle finger rests, when standing up with the arms hanging alongside the thigh.","primaryMeasures":[]},"GB 32":{"anchor":1,"compare":"GB 31","focus":{"he":"GB 32 נמצאת מאחורי הרצועה האיליוטיביאלית, 7 B-cun מעל קפל בית הברך. GB 31 משתמשת גם ביחס ליד התלויה בעמידה. שתי ההגדרות אינן מודדות מאותו עוגן.","en":"GB 32 lies posterior to the iliotibial band, 7 B-cun above the popliteal crease. GB 31 also uses a hanging-hand relationship in standing. The definitions do not measure from the same reference.","kind":"edited-location-3.3"},"shared":["Thigh","Iliotibial Band"],"unique":["Popliteal Crease"],"primaryEn":"On the lateral aspect of the thigh, posterior to the iliotibial band, 7 B-cun superior to the popliteal crease.","primaryMeasures":["7 B-cun"]},"GB 33":{"anchor":1,"compare":"GB 34","focus":{"he":"GB 33 קשורה לשקע בין גיד הדו־ראשי הירכי לרצועה האיליוטיביאלית, מאחור ומעל העילית העלי הצדדית של הירך. GB 34 משתמשת בראש השוקית שמתחת לברך. אלה שתי עצמות שונות.","en":"GB 33 uses the biceps-femoris–iliotibial-band depression posteroproximal to the lateral femoral epicondyle. GB 34 uses the fibular head below the knee. These are landmarks on different bones.","kind":"edited-location-3.3"},"shared":[],"unique":["Knee","Biceps Femoris Tendon","Iliotibial Band","Femur"],"primaryEn":"On the lateral aspect of the knee, in the depression between the biceps femoris tendon and the iliotibial band, posterior and proximal to the lateral epicondyle of the femur.","primaryMeasures":[]},"GB 34":{"anchor":1,"compare":"GB 36","focus":{"he":"ראש השוקית הוא העוגן. השקע מתואר לפניו ובכיוון כף הרגל; אין לבלבל בין ראש השוקית לבין הפטישון החיצוני בקרסול.","en":"The fibular head is the reference, with the depression anterior and distal to it. Distinguish the fibular head from the lateral ankle malleolus.","kind":"edited-location"},"shared":["Fibula"],"unique":[],"primaryEn":"On the fibular aspect of the leg, in the depression anterior and distal to the head of the fibula.","primaryMeasures":[]},"GB 35":{"anchor":1,"compare":"GB 36","focus":{"he":"שתי הנקודות נמצאות באותו גובה ביחס לפטישון החיצוני. GB 35 מתוארת מאחורי השוקית ו־GB 36 לפניה. העצם מבדילה בין שני צדי השוק.","en":"Both are at the same level relative to the lateral malleolus. GB 35 is posterior to the fibula and GB 36 anterior. The bone distinguishes their sides.","kind":"edited-comparison"},"shared":["Fibula","Lateral Malleolus","Popliteal Crease"],"unique":[],"primaryEn":"On the fibular aspect of the leg, posterior to the fibula, 7 B-cun proximal to the prominence of the lateral malleolus.","primaryMeasures":["7 B-cun"]},"GB 36":{"anchor":1,"compare":"GB 35","focus":{"he":"שתי הנקודות נמצאות באותו גובה ביחס לפטישון החיצוני. GB 35 מתוארת מאחורי השוקית ו־GB 36 לפניה. העצם מבדילה בין שני צדי השוק.","en":"Both are at the same level relative to the lateral malleolus. GB 35 is posterior to the fibula and GB 36 anterior. The bone distinguishes their sides.","kind":"edited-comparison"},"shared":["Fibula","Lateral Malleolus","Popliteal Crease"],"unique":[],"primaryEn":"On the fibular aspect of the leg, anterior to the fibula, 7 B-cun proximal to the prominence of the lateral malleolus.","primaryMeasures":["7 B-cun"]},"GB 37":{"anchor":1,"compare":"GB 38","focus":{"he":"הפטישון החיצוני הוא מוצא המדידה: GB 37 נמצאת 5 B-cun מעליו, לפני השוקית; GB 38 נמצאת 4 B-cun מעליו. המילה ״לפני״ מתייחסת לעצם השוקית.","en":"The lateral malleolus starts the measure: GB 37 is 5 B-cun above it, anterior to the fibula; GB 38 is 4 B-cun above. Anterior is defined relative to the fibula.","kind":"edited-location-3.3"},"shared":["Leg","Fibula","Lateral Malleolus"],"unique":[],"primaryEn":"On the fibular aspect of the leg, anterior to the fibula, 5 B-cun proximal to the prominence of the lateral malleolus.","primaryMeasures":["5 B-cun"]},"GB 38":{"anchor":1,"compare":"GB 39","focus":{"he":"GB 38 ו־GB 39 נמצאות לפני השוקית. ההבדל הוא הגובה מעל הפטישון החיצוני: 4 לעומת 3 B-cun. כאן נשמר גם הצד של העצם וגם מוצא המדידה.","en":"GB 38 and GB 39 are anterior to the fibula. Their heights above the lateral malleolus are 4 and 3 B-cun. Both the bone relationship and starting landmark remain constant.","kind":"edited-location-3.3"},"shared":["Leg","Fibula","Lateral Malleolus"],"unique":[],"primaryEn":"On the fibular aspect of the leg, anterior to the fibula, 4 B-cun proximal to the prominence of the lateral malleolus.","primaryMeasures":["4 B-cun"]},"GB 39":{"anchor":1,"compare":"BL 59","focus":{"he":"שתיהן משתמשות בגובה של 3 B-cun מעל אזור הפטישון החיצוני. GB 39 לפני השוקית, ו־BL 59 בין השוקית לגיד אכילס מאחור. הגובה המשותף אינו מחליף את בחירת הצד.","en":"Both use a level 3 B-cun above the lateral-malleolar region. GB 39 is anterior to the fibula; BL 59 lies between fibula and Achilles posteriorly. Shared height still requires side identification.","kind":"edited-location-3.3"},"shared":["Leg","Fibula"],"unique":["Lateral Malleolus"],"primaryEn":"On the fibular aspect of the leg, anterior to the fibula, 3 B-cun proximal to the prominence of the lateral malleolus.","primaryMeasures":["3 B-cun"]},"GB 40":{"anchor":1,"compare":"ST 41","focus":{"he":"התיאור משלב את הפטישון החיצוני עם גיד פושט האצבעות הארוך. המיקום צדדי לגיד ולפנים ולמטה מהפטישון; אלה יחסים משלימים.","en":"The lateral malleolus and extensor digitorum longus tendon both matter: lateral to the tendon and anterior/distal to the malleolus.","kind":"edited-location"},"shared":["Tendon of extensor digitorum longus","Lateral Malleolus"],"unique":[],"primaryEn":"On the anterolateral aspect of the ankle, in the depression lateral to the extensor digitorum longus tendon, anterior and distal to the lateral malleolus.","primaryMeasures":[]},"GB 41":{"anchor":1,"compare":"GB 42","focus":{"he":"שתיהן בגב כף הרגל בין עצמות המסרק הרביעית והחמישית. GB 41 קשורה לאזור בסיסי העצמות; GB 42 לאזור הפרוקסימלי למפרק המסרק־גליל הרביעי. יש לעקוב לאורך העצמות ולא רק בין האצבעות.","en":"Both lie between the fourth and fifth metatarsals. GB 41 relates to their bases; GB 42 to the region proximal to the fourth metatarsophalangeal joint. Follow the bones, not just the toe gap.","kind":"edited-comparison"},"shared":["Fourth Metatarsal Bone","Fifth Metatarsal Bone"],"unique":["Tendon of extensor digitorum longus"],"primaryEn":"On the dorsum of the foot, distal to the junction of the bases of the fourth and fifth metatarsal bones, in the depression lateral to the fifth extensor digitorum longus tendon.","primaryMeasures":[]},"GB 42":{"anchor":1,"compare":"GB 41","focus":{"he":"שתיהן בגב כף הרגל בין עצמות המסרק הרביעית והחמישית. GB 41 קשורה לאזור בסיסי העצמות; GB 42 לאזור הפרוקסימלי למפרק המסרק־גליל הרביעי. יש לעקוב לאורך העצמות ולא רק בין האצבעות.","en":"Both lie between the fourth and fifth metatarsals. GB 41 relates to their bases; GB 42 to the region proximal to the fourth metatarsophalangeal joint. Follow the bones, not just the toe gap.","kind":"edited-comparison"},"shared":["Fourth Metatarsal Bone","Fifth Metatarsal Bone"],"unique":["Metatarsophalangeal Joint Of Pedal Digit 4"],"primaryEn":"On the dorsum of the foot, between the fourth and fifth metatarsal bones, in the depression proximal to the fourth metatarsophalangeal joint.","primaryMeasures":[]},"GB 43":{"anchor":1,"compare":"GB 42","focus":{"he":"GB 43 משתמשת בשולי הקרום בין האצבעות הרביעית והחמישית. GB 42 נמצאת יותר לכיוון הקרסול, במרווח המסרקים, פרוקסימלית למפרק המסרק־גליל הרביעי. תחילה מבחינים בין קרום האצבעות לבין עצמות המסרק.","en":"GB 43 uses the fourth–fifth toe-web margin. GB 42 lies more proximally in the metatarsal interval, proximal to the fourth toe joint. Distinguish web margin from metatarsal bones first.","kind":"edited-location-3.3"},"shared":["Foot"],"unique":["Fourth Toe","Fifth Toe"],"primaryEn":"On the dorsum of the foot, between the fourth and fifth toes, proximal to the web margin, at the border between the red and white flesh.","primaryMeasures":[]},"GB 44":{"anchor":0,"compare":"ST 45","focus":{"he":"GB 44 מתוארת סמוך לפינה הצדדית של ציפורן האצבע הרביעית, 0.1 F-cun לכיוון שורש האצבע. ST 45 קשורה לאצבע השנייה. אין לזהות את האצבע לפי גודל הציפורן בלבד באיור.","en":"GB 44 lies near the lateral fourth-toenail corner, 0.1 F-cun proximally. ST 45 uses the second toe. Identify the digit by order rather than illustrated nail size alone.","kind":"edited-location-3.3"},"shared":["Distal Phalanx"],"unique":["Fourth Toe","Toenail","Nail Of Pedal Digit 4"],"primaryEn":"On the fourth toe, lateral to the distal phalanx, 0.1 f-cun proximal to the lateral corner of the toenail, at the intersection of the vertical line of the lateral side of the nail and the horizontal line of the base of the fourth toenail.","primaryMeasures":[]},"LR 1":{"anchor":0,"compare":"SP 1","focus":{"he":"שתיהן בבוהן: SP 1 בצד המדיאלי ו־LR 1 בצד הלטרלי של הציפורן. זיהוי שתי פינות אותה ציפורן חשוב יותר מזכירת צד ימין או שמאל בתמונה.","en":"Both use the great toe: SP 1 its medial nail side and LR 1 its lateral nail side. Distinguish the nail corners rather than memorizing picture left and right.","kind":"edited-comparison"},"shared":["Great Toe","Distal Phalanx","Toenail"],"unique":[],"primaryEn":"On the great toe, lateral to the distal phalanx, 0.1 f-cun proximal to the lateral corner of the toenail, at the intersection of the vertical line of the lateral side of the nail and the horizontal line of the base of the toenail.","primaryMeasures":[]},"LR 2":{"anchor":1,"compare":"ST 44","focus":{"he":"ST 44 משתמשת ברווח שבין האצבעות השנייה והשלישית; LR 2 ברווח שבין הבוהן לאצבע השנייה. הספירה מתחילה בבוהן, גם כשהאיור מוצג מהצד.","en":"ST 44 uses the second–third toe interval; LR 2 the great–second toe interval. Toe numbering starts with the great toe regardless of the viewing direction.","kind":"edited-comparison"},"shared":["Second Toe"],"unique":["First Toe"],"primaryEn":"On the dorsum of the foot, between the first and second toes, proximal to the web margin, at the border between the red and white flesh.","primaryMeasures":[]},"LR 3":{"anchor":1,"compare":"ST 43","focus":{"he":"LR 3 מתוארת בין עצמות המסרק הראשונה והשנייה. ST 43 בין השנייה לשלישית. ספירת העצמות מן הבוהן מבדילה בין שני המרווחים בגב כף הרגל.","en":"LR 3 uses the first–second metatarsal interval; ST 43 the second–third interval. Counting bones from the great toe separates these dorsal-foot spaces.","kind":"edited-comparison"},"shared":["Second Metatarsal Bone"],"unique":["First Metatarsal Bone","Dorsalis Pedis Artery"],"primaryEn":"On the dorsum of the foot, between the first and second metatarsal bones, in the depression distal to the junction of the bases of the two bones, over the dorsalis pedis artery.","primaryMeasures":[]},"LR 4":{"anchor":1,"compare":"SP 5","focus":{"he":"LR 4 נמצאת לפני הפטישון הפנימי ובצד המדיאלי של גיד השוקתי הקדמי. SP 5 מתוארת לפני ומתחת לפטישון ביחס לעצם הסירה. נוכחות הגיד בתיאור מחדדת את ההבדל.","en":"LR 4 is anterior to the medial malleolus and medial to the tibialis-anterior tendon. SP 5 is anteroinferior to the malleolus with a navicular reference. The tendon relationship distinguishes LR 4.","kind":"edited-location-3.3"},"shared":["Medial Malleolus"],"unique":["Ankle","Tibialis Anterior Tendon"],"primaryEn":"On the anteromedial aspect of the ankle, in the depression medial to the tibialis anterior tendon, anterior to the medial malleolus.","primaryMeasures":[]},"LR 5":{"anchor":1,"compare":"KI 9","focus":{"he":"LR 5 נמצאת על מרכז הצד הפנימי של השוקה, 5 B-cun מעל הפטישון הפנימי. KI 9 באותו גובה אך במרווח אחורי בין שריר לגיד. פני עצם ומרווח בין רקמות הם שני עוגנים שונים.","en":"LR 5 uses the centre of the medial tibial surface, 5 B-cun above the medial malleolus. KI 9 shares the level in a posterior muscle–tendon interval. Bone surface and tissue interval are distinct.","kind":"edited-location-3.3"},"shared":["Leg","Tibia","Medial Malleolus"],"unique":["Patella"],"primaryEn":"On the anteromedial aspect of the leg, at the centre of the medial border (surface) of the tibia, 5 B-cun proximal to the prominence of the medial malleolus.","primaryMeasures":["5 B-cun"]},"LR 6":{"anchor":1,"compare":"LR 5","focus":{"he":"LR 6 משתמשת באותו צד פנימי של השוקה כמו LR 5, אך נמצאת 7 B-cun מעל הפטישון לעומת 5. ההפרש הוא שתי יחידות יחסיות לאורך השוק, לא שינוי בצד העצם.","en":"LR 6 uses the same medial tibial surface as LR 5 but lies 7 rather than 5 B-cun above the malleolus. The two-unit difference is longitudinal, not a change in bone side.","kind":"edited-location-3.3"},"shared":["Leg","Tibia","Medial Malleolus","Patella"],"unique":[],"primaryEn":"On the anteromedial aspect of the leg, at the centre of the medial border (surface) of the tibia, 7 B-cun proximal to the prominence of the medial malleolus.","primaryMeasures":["7 B-cun"]},"LR 7":{"anchor":1,"compare":"SP 9","focus":{"he":"LR 7 מתוארת מתחת לעלי הפנימי של השוקה, 1 B-cun מאחורי SP 9. המרחק הוא בכיוון אחורי, ולא מעלה או מטה לאורך השוק.","en":"LR 7 lies inferior to the medial tibial condyle, 1 B-cun posterior to SP 9. The stated offset is posterior, not up or down the leg.","kind":"edited-location"},"shared":["Medial Condyle Of The Tibia"],"unique":[],"primaryEn":"On the tibial aspect of the leg, inferior to the medial condyle of the tibia, 1 B-cun posterior to SP9.","primaryMeasures":["1 B-cun"]},"LR 8":{"anchor":1,"compare":"SP 9","focus":{"he":"SP 9 משתמשת בגבול התחתון של הקונדיל הפנימי של השוקה. LR 8 מתייחסת לקצה הפנימי של קפל הברך ולגידים. עצם וקפל אינם אותו ציון דרך.","en":"SP 9 uses the inferior border of the medial tibial condyle. LR 8 uses the medial knee-crease end and tendons. A bony margin and a crease are different references.","kind":"edited-comparison"},"shared":[],"unique":["Semitendinosus Tendon","Semimembranosus Muscle","Popliteal Crease"],"primaryEn":"On the medial aspect of the knee, in the depression medial to the tendons of the semitendinosus and the semimembranosus muscles, at the medial end of the popliteal crease.","primaryMeasures":[]},"LR 9":{"anchor":1,"compare":"SP 10","focus":{"he":"LR 9 נמצאת בין השריר העדין לשריר החייטים, 4 B-cun מעל בסיס הפיקה. SP 10 קשורה לשריר הרחב הפנימי ובגובה 2 B-cun. גם המרווח השרירי וגם הגובה שונים.","en":"LR 9 is between gracilis and sartorius, 4 B-cun above the patellar base. SP 10 uses vastus medialis at 2 B-cun. Both the muscle relationship and level differ.","kind":"edited-location-3.3"},"shared":["Thigh","Patella"],"unique":["Gracilis Muscle","Sartorius Muscle"],"primaryEn":"On the medial aspect of the thigh, between the gracilis and the sartorius muscles, 4 B- cun proximal to the base of the patella.","primaryMeasures":["4 B-cun"]},"LR 10":{"anchor":0,"compare":"LR 11","focus":{"he":"שתי המידות מתחילות ב־ST 30 ופונות לכיוון הברך: LR 10 במרחק 3 B-cun ו־LR 11 במרחק 2. משום כך סדר המספרים כאן אינו סדר ההתרחקות מן המפשעה.","en":"Both measures start at ST 30 and run toward the knee: LR 10 is 3 B-cun away and LR 11 is 2. Point-number order here is not increasing distance from the groin.","kind":"edited-location-3.3"},"shared":["Thigh"],"unique":[],"primaryEn":"On the medial aspect of the thigh, 3 B-cun distal to St30, over the artery.","primaryMeasures":["3 B-cun"]},"LR 11":{"anchor":1,"compare":"SP 11","focus":{"he":"נקודת הייחוס למרחק היא ST 30: התיאור מציין 2 B-cun ממנה לכיוון הברך. הערת המקור מוסיפה יחס לשריר המקרב הארוך.","en":"ST 30 starts the distance reference: 2 B-cun distally toward the knee. The source note adds the adductor-longus relationship.","kind":"edited-location"},"shared":["Adductor Longus Muscle"],"unique":[],"primaryEn":"On the medial aspect of the thigh, 2 B-cun distal to St30.","primaryMeasures":["2 B-cun"]},"LR 12":{"anchor":1,"compare":"ST 30","focus":{"he":"הגבול העליון של מאחה הערווה קובע את הגובה. LR 12 בהיסט 2.5 B-cun מקו האמצע, ו־ST 30 בהיסט 2. חצי היחידה הנוספת היא צדדית, לא כלפי מעלה או מטה.","en":"The superior pubic-symphysis border sets the level. LR 12 lies 2.5 B-cun lateral and ST 30 lies 2. The additional half-unit is lateral rather than superior or inferior.","kind":"edited-location-3.3"},"shared":["Groin Region","Pubic Symphysis","Anterior Median Line"],"unique":[],"primaryEn":"In the groin region, at the same level as the superior border of the pubic symphysis, and 2.5 B-cun lateral to the anterior median line.","primaryMeasures":["2.5 B-cun"]},"LR 13":{"anchor":1,"compare":"GB 25","focus":{"he":"שתיהן קשורות לקצה חופשי של צלע בצד הגוף: LR 13 לצלע ה־11 ו־GB 25 לצלע ה־12. יש לזהות את הצלע המתוארת לפני השוואת מיקומן בסכמה.","en":"Both use a free rib end on the flank: LR 13 rib 11 and GB 25 rib 12. Identify the named rib before comparing schematic positions.","kind":"edited-comparison"},"shared":["Costal Arch"],"unique":["Eleventh Rib"],"primaryEn":"On the lateral abdomen, inferior to the free extremity of the 11th rib.","primaryMeasures":[]},"LR 14":{"anchor":1,"compare":"GB 24","focus":{"he":"LR 14 במרווח הבין־צלעי השישי ו־GB 24 בשביעי, שתיהן בהיסט 4 B-cun. משתמשים במספר המרווח כעוגן הראשי לגובה, ולא במיקום הפטמה בלבד.","en":"LR 14 uses the sixth intercostal space and GB 24 the seventh, both at a 4 B-cun offset. The intercostal-space number, rather than nipple position alone, anchors the level.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Anterior Median Line","Nipple"],"unique":["Sixth Intercostal Space"],"primaryEn":"In the anterior thoracic region, in the sixth intercostal space, 4 B-cun lateral to the anterior median line.","primaryMeasures":["4 B-cun"]},"GV 1":{"anchor":1,"compare":"CV 1","focus":{"he":"GV 1 מוגדרת באמצע שבין קצה עצם הזנב לפי הטבעת. CV 1 נמצאת בצד האחר של פי הטבעת, לכיוון איברי המין החיצוניים. הסכמה המופשטת מדגישה את סדר ציוני הדרך.","en":"GV 1 is midway between the coccygeal tip and anus. CV 1 lies on the other side of the anus toward the external genital reference. The abstract view emphasizes landmark order.","kind":"edited-location-3.3"},"shared":["Perineal Region","Anus"],"unique":["Coccyx"],"primaryEn":"In the perineal region, inferior to the coccyx, midway between the tip of the coccyx and the anus.","primaryMeasures":[]},"GV 2":{"anchor":1,"compare":"BL 34","focus":{"he":"GV 2 קשורה לפתח העצה בקו האמצע האחורי. BL 34 מתוארת בנקב העצה האחורי הרביעי. הפתח המרכזי וזוג הנקבים הצדדיים הם מבנים נפרדים, גם בגובה קרוב.","en":"GV 2 uses the sacral hiatus on the posterior midline. BL 34 uses the fourth posterior sacral foramen. The central hiatus and paired lateral foramina are different structures.","kind":"edited-location-3.3"},"shared":["Sacral Region"],"unique":["Posterior Median Line","Anal Cleft"],"primaryEn":"In the sacral region, at the sacral hiatus, on the posterior median line.","primaryMeasures":[]},"GV 3":{"anchor":1,"compare":"BL 25","focus":{"he":"GV 3 נמצאת בשקע שמתחת לזיז L4 על קו האמצע האחורי. BL 25 משתמשת באותו גובה בהיסט של 1.5 B-cun. ב־GV אין להוסיף היסט צדדי מן הקו.","en":"GV 3 is in the depression below the L4 spinous process on the posterior midline. BL 25 uses that level at a 1.5 B-cun offset. GV 3 has no lateral displacement.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Fourth Lumbar Vertebra","Posterior Median Line"],"unique":["Iliac Crest"],"primaryEn":"In the lumbar region, in the depression inferior to the spinous process of the fourth lumbar vertebra (L4), on the posterior median line.","primaryMeasures":[]},"GV 4":{"anchor":1,"compare":"GV 3","focus":{"he":"GV 4 מתוארת מתחת לזיז L2 בקו האמצע; GV 3 מתחת לזיז L4. המספור עובר בין שתי חוליות שאינן סמוכות, ולכן אין למלא אוטומטית נקודה נוספת ב־L3.","en":"GV 4 is below L2 on the midline; GV 3 is below L4. The numbered points reference nonadjacent vertebrae. Do not infer an extra intermediate point at L3.","kind":"edited-location-3.3"},"shared":["Lumbar Region","Posterior Median Line"],"unique":["Second Lumbar Vertebra"],"primaryEn":"In the lumbar region, in the depression inferior to the spinous process of the second lumbar vertebra (L2), on the posterior median line.","primaryMeasures":[]},"GV 5":{"anchor":1,"compare":"BL 22","focus":{"he":"השקע שמתחת לזיז L1 מגדיר את GV 5 בקו האמצע. BL 22 נמצאת בגובה זה, 1.5 B-cun הצדה. L1 היא תחילת סדרת המותן, בנפרד מסדרת T של בית החזה.","en":"The depression below L1 defines midline GV 5. BL 22 lies at that level 1.5 B-cun laterally. L1 begins the lumbar series, distinct from the thoracic T series.","kind":"edited-location-3.3"},"shared":["Lumbar Region","First Lumbar Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the lumbar region, in the depression inferior to the spinous process of the first lumbar vertebra (L1), on the posterior median line.","primaryMeasures":[]},"GV 6":{"anchor":1,"compare":"GV 5","focus":{"he":"GV 6 משתמשת בשקע שמתחת לזיז T11, ו־GV 5 ב־L1. שתי הנקודות בקו האמצע, אך הרצף מדלג על T12. מספר נקודה אינו מבטיח מעבר לחוליה הסמוכה.","en":"GV 6 uses the depression below T11 and GV 5 below L1. Both are midline, but the point sequence skips T12. Consecutive point numbers do not guarantee adjacent vertebrae.","kind":"edited-location-3.3"},"shared":["Posterior Median Line"],"unique":["Upper Back","Eleventh Thoracic Vertebra"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the 11th thoracic vertebra (T11), on the posterior median line.","primaryMeasures":[]},"GV 7":{"anchor":1,"compare":"BL 19","focus":{"he":"GV 7 בשקע שמתחת לזיז T10 בקו האמצע האחורי. BL 19 בגובה זה בהיסט 1.5 B-cun. קוראים תחילה את גובה T10 ואז מבחינים בין שקע מרכזי לסימון צדדי.","en":"GV 7 is below T10 on the posterior midline; BL 19 uses that level at a 1.5 B-cun offset. Establish T10 before distinguishing midline depression from lateral marker.","kind":"edited-location-3.3"},"shared":["Upper Back","Tenth Thoracic Vertebra","Posterior Median Line"],"unique":[],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the tenth thoracic vertebra (T10), on the posterior median line.","primaryMeasures":[]},"GV 8":{"anchor":1,"compare":"GV 9","focus":{"he":"GV 8 נמצאת מתחת לזיז T9 ו־GV 9 מתחת לזיז T7. אין ביניהן נקודת GV מקבילה ב־T8 ברשימה הזאת. שמירת סדר החוליות חשובה יותר מהנחת מרווחים שווים.","en":"GV 8 lies below T9 and GV 9 below T7. This list has no intervening GV counterpart at T8. Preserve vertebral order rather than assuming equal point spacing.","kind":"edited-location-3.3"},"shared":["Upper Back","Posterior Median Line"],"unique":["Ninth Thoracic Vertebra"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the ninth thoracic vertebra (T9), on the posterior median line.","primaryMeasures":[]},"GV 9":{"anchor":1,"compare":"BL 17","focus":{"he":"הגבול התחתון של זיז T7 קובע את גובה GV 9. BL 17 נמצאת 1.5 B-cun הצדה באותו מפלס. הזווית התחתונה של השכמה מוזכרת כעזר, אך הסכמה אינה מדידה על שכמה מסוימת.","en":"The inferior T7 spinous-process border sets GV 9’s level; BL 17 is 1.5 B-cun lateral there. The scapular inferior angle is an auxiliary reference, not a patient-specific measurement in this schematic.","kind":"edited-location-3.3"},"shared":["Upper Back","Seventh Thoracic Vertebra","Posterior Median Line","Scapula"],"unique":[],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the seventh thoracic vertebra (T7), on the posterior median line.","primaryMeasures":[]},"GV 10":{"anchor":1,"compare":"GV 11","focus":{"he":"GV 10 מתוארת מתחת לזיז T6 ו־GV 11 מתחת לזיז T5. שתיהן בקו האמצע; הגדלת מספר GV כאן מתקדמת מעלה לאורך הגב, ולא מטה לפי מספר החוליה.","en":"GV 10 is below T6 and GV 11 below T5, both midline. Increasing GV number here moves upward along the back rather than downward with increasing vertebral number.","kind":"edited-location-3.3"},"shared":["Upper Back","Posterior Median Line"],"unique":["Sixth Thoracic Vertebra"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the sixth thoracic vertebra (T6), on the posterior median line.","primaryMeasures":[]},"GV 11":{"anchor":1,"compare":"GV 12","focus":{"he":"GV 11 משתמשת בזיז T5, ו־GV 12 בזיז T3. הרשומות מדלגות על גובה T4 בקו האמצע. נקודות BL בגובה T4 קיימות, אך אינן הופכות לנקודת GV נוספת.","en":"GV 11 uses T5 and GV 12 uses T3, skipping a T4 midline counterpart in this sequence. BL records at T4 do not imply an additional GV point.","kind":"edited-location-3.3"},"shared":["Upper Back","Posterior Median Line"],"unique":["Fifth Thoracic Vertebra"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the fifth thoracic vertebra (T5), on the posterior median line.","primaryMeasures":[]},"GV 12":{"anchor":1,"compare":"BL 13","focus":{"he":"GV 12 נמצאת מתחת לזיז T3 בקו האמצע. BL 13 בהיסט 1.5 B-cun מאותו גובה. קוץ השכמה מספק הקשר אזורי; נקודת הייחוס המפורשת היא זיז החוליה.","en":"GV 12 lies below T3 on the midline; BL 13 is 1.5 B-cun lateral at that level. The scapular spine gives regional context; the explicit reference is the vertebral spinous process.","kind":"edited-location-3.3"},"shared":["Upper Back","Third Thoracic Vertebra","Posterior Median Line"],"unique":["Scapula"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the third thoracic vertebra (T3), on the posterior median line.","primaryMeasures":[]},"GV 13":{"anchor":1,"compare":"GV 14","focus":{"he":"GV 13 משתמשת בזיז T1 ו־GV 14 בזיז C7, שתיהן בשקע שמתחת לזיז ובקו האמצע. מעבר מהחזה לצוואר משנה את אות הסדרה, ולא רק את המספר.","en":"GV 13 uses T1 and GV 14 C7, both in the depression below the spinous process on the midline. Moving from thorax to neck changes the series letter as well as the number.","kind":"edited-location-3.3"},"shared":["Posterior Median Line"],"unique":["Upper Back","First Thoracic Vertebra"],"primaryEn":"In the upper back region, in the depression inferior to the spinous process of the first thoracic vertebra (T1), on the posterior median line.","primaryMeasures":[]},"GV 14":{"anchor":1,"compare":"SI 15","focus":{"he":"השקע שמתחת לזיז C7 מגדיר את GV 14 בקו האמצע האחורי. SI 15 נמצאת באותו גובה בהיסט 2 B-cun. בליטה בתמונה אינה מספיקה כשלעצמה לקביעה שהיא C7.","en":"The depression below the C7 spinous process defines midline GV 14. SI 15 shares the level with a 2 B-cun offset. A prominence in a picture alone does not establish C7 identity.","kind":"edited-location-3.3"},"shared":["Seventh Cervical Vertebra","Posterior Median Line"],"unique":["Neck"],"primaryEn":"In the posterior region of the neck, in the depression inferior to the spinous process of the seventh cervical vertebra (C7), on the posterior median line.","primaryMeasures":[]},"GV 15":{"anchor":1,"compare":"GV 16","focus":{"he":"שתיהן בקו האמצע האחורי של הצוואר. GV 15 מתייחסת לגובה החוליה הצווארית השנייה; GV 16 לשקע שמתחת לבליטה העורפית החיצונית. ציון הדרך הגרמי שונה.","en":"Both lie on the posterior neck midline. GV 15 refers to the second cervical vertebral level; GV 16 to the depression below the external occipital protuberance. The bony reference differs.","kind":"edited-comparison"},"shared":[],"unique":["Second Cervical Vertebra","Posterior Median Line"],"primaryEn":"In the posterior region of the neck, in the depression superior to the spinous process of the second cervical vertebra (C2), on the posterior median line.","primaryMeasures":[]},"GV 16":{"anchor":1,"compare":"GV 15","focus":{"he":"שתיהן בקו האמצע האחורי של הצוואר. GV 15 מתייחסת לגובה החוליה הצווארית השנייה; GV 16 לשקע שמתחת לבליטה העורפית החיצונית. ציון הדרך הגרמי שונה.","en":"Both lie on the posterior neck midline. GV 15 refers to the second cervical vertebral level; GV 16 to the depression below the external occipital protuberance. The bony reference differs.","kind":"edited-comparison"},"shared":[],"unique":["External Occipital Protuberance","Trapezius"],"primaryEn":"In the posterior region of the neck, directly inferior to the external occipital protuberance, in the depression between the trapezius muscles.","primaryMeasures":[]},"GV 17":{"anchor":1,"compare":"BL 9","focus":{"he":"העוגן הוא השקע מעל הבליטה העורפית החיצונית בקו האמצע האחורי. אותו גובה יכול להופיע בנקודות צדדיות בלי שהן נמצאות בקו האמצע.","en":"Use the depression above the external occipital protuberance on the posterior midline. Lateral points may share the level without sharing the midline.","kind":"edited-location"},"shared":["External Occipital Protuberance","Posterior Median Line"],"unique":[],"primaryEn":"On the head, in the depression superior to the external occipital protuberance.","primaryMeasures":[]},"GV 18":{"anchor":1,"compare":"GV 19","focus":{"he":"GV 18 נמצאת 4 B-cun מעל קו השיער האחורי, ו־GV 19 במרחק 5.5. כאן מודדים מהקו האחורי, בניגוד לנקודות קרקפת שנמדדות מקו השיער הקדמי.","en":"GV 18 is 4 B-cun above the posterior hairline and GV 19 is 5.5. These measurements start at the posterior hairline, unlike scalp records measured from the anterior one.","kind":"edited-location-3.3"},"shared":["Head","Posterior Hairline","Posterior Median Line"],"unique":[],"primaryEn":"On the head, 4 B-cun superior to the posterior hairline, on the posterior median line.","primaryMeasures":["4 B-cun"]},"GV 19":{"anchor":1,"compare":"GV 20","focus":{"he":"GV 19 נמדדת 5.5 B-cun מקו השיער האחורי; GV 20 נמדדת 5 B-cun מהקו הקדמי. ההערה ממקמת את GV 19 במרחק 1.5 B-cun מאחורי GV 20. אין לחסר את שתי מידות השיער לבדן.","en":"GV 19 is measured 5.5 B-cun from the posterior hairline; GV 20 uses 5 from the anterior line. The note places GV 19 1.5 B-cun behind GV 20. Do not subtract unlike-reference measures.","kind":"edited-location-3.3"},"shared":["Head","Posterior Hairline"],"unique":["Posterior Median Line"],"primaryEn":"On the head, 5.5 B-cun superior to the posterior hairline, on the posterior median line.","primaryMeasures":["5.5 B-cun"]},"GV 20":{"anchor":1,"compare":"GV 21","focus":{"he":"GV 20 נמצאת בקו האמצע, 5 B-cun מקו השיער הקדמי; GV 21 במרחק 3.5. מרכז הראש הנראה בתמונה אינו מחליף את קו השיער והמידה היחסית המפורשים.","en":"GV 20 is midline, 5 B-cun from the anterior hairline; GV 21 uses 3.5. The apparent centre of an illustrated head does not replace the stated hairline and relative measure.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":["Posterior Hairline"],"primaryEn":"On the head, 5 B-cun superior to the ante- rior hairline, on the anterior median line.","primaryMeasures":["5 B-cun"]},"GV 21":{"anchor":1,"compare":"GV 22","focus":{"he":"GV 21 נמצאת 3.5 B-cun בתוך קו השיער הקדמי, ו־GV 22 במרחק 2. לפי המקור GV 21 באמצע בין GV 20 ל־GV 22. אמצע זה מתייחס לקו הקרקפת שביניהן.","en":"GV 21 is 3.5 B-cun within the anterior hairline and GV 22 is 2. The source places GV 21 midway between GV 20 and GV 22, along their scalp reference line.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 3.5 B-cun superior to the anterior hairline, on the anterior median line.","primaryMeasures":["3.5 B-cun"]},"GV 22":{"anchor":1,"compare":"GV 23","focus":{"he":"GV 22 נמצאת 2 B-cun מקו השיער הקדמי ו־GV 23 במרחק 1. שתיהן בקו האמצע. ההבחנה היא מרחק מקו השיער, ללא היסט ימינה או שמאלה.","en":"GV 22 is 2 B-cun from the anterior hairline and GV 23 is 1. Both lie on the midline. Their difference is hairline distance without a left or right offset.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 2 B-cun superior to the anterior hairline, on the anterior median line.","primaryMeasures":["2 B-cun"]},"GV 23":{"anchor":1,"compare":"BL 5","focus":{"he":"GV 23 ו־BL 5 נמצאות 1 B-cun מעל קו השיער הקדמי. GV 23 בקו האמצע ו־BL 5 בהיסט 1.5 B-cun. הגובה המשותף עוזר להשוות את העמודות על סכמת הקרקפת.","en":"GV 23 and BL 5 lie 1 B-cun above the anterior hairline. GV 23 is midline and BL 5 is 1.5 B-cun lateral. Their shared level helps compare scalp columns.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":[],"primaryEn":"On the head, 1 B-cun superior to the anterior hairline, on the anterior median line.","primaryMeasures":["1 B-cun"]},"GV 24":{"anchor":1,"compare":"GV 23","focus":{"he":"GV 24 נמצאת חצי B-cun בתוך קו השיער הקדמי, בקו האמצע; GV 23 במרחק יחידה שלמה. קו שיער שנסוג או אינו ברור הוא מגבלה של העוגן, ולא סיבה למדוד מקצה המסך.","en":"GV 24 is half a B-cun within the anterior hairline on the midline; GV 23 is one unit within it. An unclear or receding hairline limits the reference, not a reason to measure from the screen edge.","kind":"edited-location-3.3"},"shared":["Head","Anterior Hairline","Anterior Median Line"],"unique":["Eyebrow"],"primaryEn":"On the head, 0.5 B-cun superior to the anterior hairline, on the anterior median line.","primaryMeasures":["0.5 B-cun"]},"GV 25":{"anchor":1,"compare":"GV 26","focus":{"he":"קצה האף עצמו הוא המיקום של GV 25. GV 26 משתמשת בחריץ שבין האף לשפה העליונה. אף ששתי הנקודות בקו האמצע של הפנים, הן קשורות למבנים שונים.","en":"GV 25 is at the nasal tip itself. GV 26 uses the philtrum between nose and upper lip. Both are facial midline points but refer to different structures.","kind":"edited-location-3.3"},"shared":["Face"],"unique":["Nose","Nose Tip"],"primaryEn":"On the face, at the tip of the nose.","primaryMeasures":[]},"GV 26":{"anchor":1,"compare":"LI 19","focus":{"he":"GV 26 נמצאת בקו האמצע של הפילטרום, ו־LI 19 לצדו ומתחת לשוליים הצדדיים של הנחיר. לשתי הרשומות חלופה בגובה שונה; יש להשוות ראשי לראשי וחלופי לחלופי.","en":"GV 26 is on the philtrum midline; LI 19 lies beside it below the lateral nostril margin. Both have an alternative vertical level: compare primary with primary and alternative with alternative.","kind":"edited-comparison"},"shared":["Philtrum"],"unique":[],"primaryEn":"On the face, at the midpoint of the philtrum midline.","primaryMeasures":[]},"GV 27":{"anchor":1,"compare":"CV 24","focus":{"he":"CV 24 קשורה לקפל שבין השפה התחתונה לסנטר. GV 27 נמצאת באזור השפה העליונה. שני המבטים קדמיים, אך מדובר בשתי שפות ובשני ציוני דרך נפרדים.","en":"CV 24 uses the mentolabial groove below the lower lip. GV 27 concerns the upper lip. Both are anterior, but the lip and landmark differ.","kind":"edited-comparison"},"shared":[],"unique":["Upper Lip"],"primaryEn":"On the face, at the midpoint of the tubercle of the upper lip.","primaryMeasures":[]},"GV 28":{"anchor":1,"compare":"GV 27","focus":{"he":"GV 28 קשורה למפגש רסן השפה העליונה עם החניכיים העליונות. GV 27 נמצאת באזור החיצוני של השפה העליונה. לכן תקריב הפה מציג מבט שונה ממבט הפנים הרגיל.","en":"GV 28 uses the upper-labial-frenulum junction with the upper gum. GV 27 concerns the external upper-lip region. The oral close-up therefore differs from the ordinary facial view.","kind":"edited-location-3.3"},"shared":["Face"],"unique":["Labial Frenulum","Upper Gum"],"primaryEn":"On the face, at the junction of the frenulum of the upper lip with the upper gum.","primaryMeasures":[]},"CV 1":{"anchor":1,"compare":"GV 1","focus":{"he":"CV 1 באמצע שבין פי הטבעת לבין העוגן הקדמי של איברי המין החיצוניים, המשתנה לפי האנטומיה המתוארת במקור. GV 1 בצד הפונה לעצם הזנב. הסכמה שומרת על ייחוס קדמי ואחורי מופשט.","en":"CV 1 lies midway between the anus and the anterior external-genital reference specified for the anatomy in the source. GV 1 is on the coccygeal side. The schematic keeps these anterior and posterior relationships abstract.","kind":"edited-location-3.3"},"shared":["Perineal Region","Anus"],"unique":["Genital Organ"],"primaryEn":"In the perineal region, at the midpoint of the line connecting the anus with the posterior border of the scrotum in males and the posterior commissure of labium majoris in females.","primaryMeasures":[]},"CV 2":{"anchor":1,"compare":"ST 30","focus":{"he":"החיבור בין שתי עצמות החיק הוא העוגן התחתון, והמיקום מתואר מעליו בקו האמצע הקדמי. אין להחליף את חיבור החיק בכל אזור המפשעה.","en":"The pubic symphysis is the reference, with the point superior to it on the anterior midline. The symphysis is a specific structure, not the whole groin region.","kind":"edited-location"},"shared":["Pubic Symphysis","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, superior to the pubic symphysis, on the anterior median line.","primaryMeasures":[]},"CV 3":{"anchor":1,"compare":"CV 4","focus":{"he":"CV 3 נמצאת 4 B-cun מתחת לטבור בקו האמצע; CV 4 נמצאת 3 B-cun מתחתיו. ככל שמתקדמים כאן מ־CV 3 ל־CV 4 מתקרבים לטבור, אף שמספר הנקודה עולה.","en":"CV 3 is 4 B-cun below the umbilicus on the midline; CV 4 is 3 below. Moving from CV 3 to CV 4 approaches the umbilicus despite the increasing point number.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 4 B-cun inferior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["4 B-cun"]},"CV 4":{"anchor":1,"compare":"ST 28","focus":{"he":"CV 4 ו־ST 28 נמצאות 3 B-cun מתחת לטבור. CV 4 בקו האמצע ו־ST 28 בהיסט 2 B-cun. ההשוואה מפרידה בין שורת גובה לבין עמודה צדדית.","en":"CV 4 and ST 28 lie 3 B-cun below the umbilicus. CV 4 is midline and ST 28 is 2 B-cun lateral. Separate the shared vertical row from the lateral column.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 3 B-cun inferior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["3 B-cun"]},"CV 5":{"anchor":1,"compare":"CV 6","focus":{"he":"CV 5 נמצאת 2 B-cun מתחת לטבור; CV 6 במרחק 1.5. שתיהן בקו האמצע. המרווח בין שתי הנקודות הוא חצי יחידה יחסית, ולא יחידה שלמה.","en":"CV 5 is 2 B-cun below the umbilicus and CV 6 is 1.5 below, both midline. Their stated separation is half a relative unit rather than a full one.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 2 B-cun inferior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["2 B-cun"]},"CV 6":{"anchor":1,"compare":"CV 7","focus":{"he":"CV 6 נמצאת 1.5 B-cun מתחת לטבור, באמצע בין גובה CV 5 לגובה CV 7. CV 7 במרחק 1 B-cun. המספר העשרוני מבדיל בין סימונים קרובים בקו האמצע.","en":"CV 6 is 1.5 B-cun below the umbilicus, between CV 5’s and CV 7’s levels. CV 7 is 1 B-cun below. The fractional distance distinguishes nearby midline markers.","kind":"edited-location-3.3"},"shared":["Lower Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the lower abdomen, 1.5 B-cun inferior to the centre of the umbilicus, on the ante- rior median line.","primaryMeasures":["1.5 B-cun"]},"CV 7":{"anchor":1,"compare":"CV 9","focus":{"he":"CV 7 נמצאת 1 B-cun מתחת לטבור, ו־CV 9 נמצאת 1 B-cun מעליו. שתיהן בקו האמצע. סימטריה במספר אינה זהות בכיוון ביחס לטבור.","en":"CV 7 is 1 B-cun below the umbilicus and CV 9 is 1 above, both midline. Equal numerical distances have opposite directions relative to the umbilicus.","kind":"edited-location-3.3"},"shared":["Umbilicus","Anterior Median Line"],"unique":["Lower Abdomen"],"primaryEn":"On the lower abdomen, 1 B-cun inferior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["1 B-cun"]},"CV 8":{"anchor":1,"compare":"CV 7","focus":{"he":"ההגדרה משתמשת במרכז הטבור עצמו. נקודות אחרות בקו האמצע נמדדות ביחס לטבור; כאן אין היסט ממנו.","en":"The definition uses the umbilical centre itself. Other midline points are measured relative to it; this point has no offset from that reference.","kind":"edited-location"},"shared":["Umbilicus"],"unique":[],"primaryEn":"On the upper abdomen, in the centre of the umbilicus.","primaryMeasures":[]},"CV 9":{"anchor":1,"compare":"CV 8","focus":{"he":"CV 9 נמצאת 1 B-cun מעל מרכז הטבור, בעוד CV 8 במרכז עצמו. תחילה מזהים את הטבור ואז את הכיוון העליון; אין היסט צדדי בתיאור.","en":"CV 9 is 1 B-cun above the umbilical centre, whereas CV 8 is at the centre itself. Establish the umbilicus, then the superior direction; no lateral offset is specified.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus"],"unique":["Anterior Median Line"],"primaryEn":"On the upper abdomen, 1 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["1 B-cun"]},"CV 10":{"anchor":1,"compare":"KI 17","focus":{"he":"CV 10 נמצאת בקו האמצע, 2 B-cun מעל הטבור. KI 17 באותו גובה, חצי B-cun הצדה. המיקום של CV נשאר במרכז גם כאשר ההדגשה של KI קרובה אליו.","en":"CV 10 is midline, 2 B-cun above the umbilicus. KI 17 shares that level half a B-cun laterally. A nearby KI highlight does not move the CV reference off the midline.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 2 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["2 B-cun"]},"CV 11":{"anchor":1,"compare":"SP 16","focus":{"he":"CV 11 נמצאת 3 B-cun מעל הטבור בקו האמצע; SP 16 בגובה זה בהיסט 4 B-cun. שתי הרשומות ממחישות הבדל בין עוגן מרכזי לבין עמודה רחוקה יותר באותה שורה.","en":"CV 11 is midline, 3 B-cun above the umbilicus; SP 16 uses a 4 B-cun offset at that level. The pair contrasts a central reference with a farther lateral column.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 3 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["3 B-cun"]},"CV 12":{"anchor":1,"compare":"CV 16","focus":{"he":"CV 12 נמצאת 4 B-cun מעל הטבור ומתוארת גם כאמצע הדרך בין הטבור לחיבור גוף עצם החזה וזיז החרב. CV 16 נמצאת בחיבור עצמו. האמצע וקצה הקו הם מיקומים שונים.","en":"CV 12 is 4 B-cun above the umbilicus and the stated midpoint between umbilicus and xiphisternal junction. CV 16 uses the junction itself. Midpoint and endpoint are distinct positions.","kind":"edited-location-3.3"},"shared":["Anterior Median Line","Xiphisternal Junction"],"unique":["Upper Abdomen","Umbilicus"],"primaryEn":"On the upper abdomen, 4 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["4 B-cun"]},"CV 13":{"anchor":1,"compare":"ST 20","focus":{"he":"CV 13 נמצאת בקו האמצע, 5 B-cun מעל הטבור. ST 20 נמצאת 2 B-cun לצדה באותו גובה. השוואתן דורשת לשמור על גובה הטבור כעוגן משותף.","en":"CV 13 is midline, 5 B-cun above the umbilicus. ST 20 lies 2 B-cun lateral at that level. Keep the umbilicus as their shared vertical reference.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 5 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["5 B-cun"]},"CV 14":{"anchor":1,"compare":"KI 21","focus":{"he":"CV 14 ו־KI 21 נמצאות 6 B-cun מעל הטבור. CV 14 בקו האמצע ו־KI 21 בהיסט חצי B-cun. אין כאן שימוש במספר מרווח בין־צלעי להגדרת הגובה הראשית.","en":"CV 14 and KI 21 are 6 B-cun above the umbilicus. CV 14 is midline and KI 21 half a B-cun lateral. Their primary level definition uses umbilical measurement rather than an intercostal number.","kind":"edited-location-3.3"},"shared":["Upper Abdomen","Umbilicus","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 6 B-cun superior to the centre of the umbilicus, on the anterior median line.","primaryMeasures":["6 B-cun"]},"CV 15":{"anchor":1,"compare":"CV 16","focus":{"he":"המרחק של 1 B-cun מתחיל בחיבור גוף עצם החזה לזיז החרב ופונה מטה. CV 16 משתמשת בחיבור עצמו כעוגן המיקום.","en":"The 1 B-cun measure runs inferiorly from the xiphisternal junction. CV 16 uses the junction itself as its location reference.","kind":"edited-location"},"shared":["Xiphisternal Junction","Anterior Median Line"],"unique":[],"primaryEn":"On the upper abdomen, 1 B-cun inferior to the xiphisternal junction, on the anterior median line.","primaryMeasures":["1 B-cun"]},"CV 16":{"anchor":1,"compare":"CV 15","focus":{"he":"ציון הדרך הוא חיבור גוף עצם החזה לזיז החרב בקו האמצע. הוא שונה מקצה זיז החרב; CV 15 נמצאת מתחת לחיבור.","en":"The reference is the midline xiphisternal junction. It differs from the tip of the xiphoid process; CV 15 lies inferior to the junction.","kind":"edited-location"},"shared":["Xiphisternal Junction","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, at the midpoint of the xiphisternal junction, on the anterior median line.","primaryMeasures":[]},"CV 17":{"anchor":1,"compare":"KI 23","focus":{"he":"CV 17 נמצאת בקו האמצע בגובה המרווח הבין־צלעי הרביעי; KI 23 נמצאת במרווח עצמו, 2 B-cun הצדה. ״בגובה המרווח״ בקו האמצע אינו אומר שהסימון בתוך מרווח בין צלעות.","en":"CV 17 is midline at the fourth-intercostal-space level; KI 23 lies in that space 2 B-cun laterally. A midline point level with a space is not itself inside an intercostal space.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Fourth Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, at the same level as the fourth intercostal space, on the anterior median line.","primaryMeasures":[]},"CV 18":{"anchor":1,"compare":"ST 16","focus":{"he":"גובה המרווח הבין־צלעי השלישי מגדיר את CV 18 בקו האמצע. ST 16 נמצאת במרווח, 4 B-cun הצדה. יש להבחין בין השלכת הגובה על עצם החזה לבין המרווח בצד.","en":"The third-intercostal-space level defines midline CV 18. ST 16 lies in the space 4 B-cun laterally. Distinguish projection onto the sternum from the actual lateral intercostal interval.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Third Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, at the same level as the third intercostal space, on the anterior median line.","primaryMeasures":[]},"CV 19":{"anchor":1,"compare":"KI 25","focus":{"he":"CV 19 נמצאת בקו האמצע בגובה המרווח הבין־צלעי השני. KI 25 נמצאת במרווח השני בהיסט 2 B-cun. הגובה נשמר, בעוד המבנה שמתחת לסימון שונה.","en":"CV 19 is midline at the second-intercostal-space level. KI 25 is in the second space at a 2 B-cun offset. The level is shared while the underlying regional structure differs.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","Second Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, at the same level as the second intercostal space, on the anterior median line.","primaryMeasures":[]},"CV 20":{"anchor":1,"compare":"KI 26","focus":{"he":"CV 20 משתמשת בגובה המרווח הבין־צלעי הראשון על קו האמצע; KI 26 נמצאת במרווח עצמו, 2 B-cun הצדה. מיקום מרכזי על עצם החזה אינו מרווח בין שתי צלעות.","en":"CV 20 uses the first-intercostal-space level on the midline; KI 26 lies in the space 2 B-cun laterally. A central sternal reference is not a gap between two ribs.","kind":"edited-location-3.3"},"shared":["Anterior Thoracic Region","First Intercostal Space","Anterior Median Line"],"unique":[],"primaryEn":"In the anterior thoracic region, at the same level as the first intercostal space, on the anterior median line.","primaryMeasures":[]},"CV 21":{"anchor":1,"compare":"CV 22","focus":{"he":"הגומה שמעל עצם החזה היא העוגן: CV 21 נמצאת 1 B-cun מתחתיה, בקו האמצע. CV 22 משתמשת בגומה עצמה. אין לבלבל את הגבול העליון של החזה עם קצה זיז החרב שבתחתיתו.","en":"The suprasternal fossa is the reference: CV 21 is 1 B-cun inferior to it on the midline; CV 22 uses the fossa itself. Distinguish the upper sternal reference from the inferior xiphoid region.","kind":"edited-location-3.3"},"shared":["Suprasternal Fossa","Anterior Median Line"],"unique":["Anterior Thoracic Region"],"primaryEn":"In the anterior thoracic region, 1 B-cun inferior to the suprasternal fossa, on the anterior median line.","primaryMeasures":["1 B-cun"]},"CV 22":{"anchor":1,"compare":"CV 23","focus":{"he":"CV 22 מתוארת בגומה שמעל עצם החזה בבסיס הצוואר. CV 23 קשורה לעצם הלשון בחלק העליון של הצוואר. שתיהן בקו האמצע, אך בגבהים ובמבנים שונים.","en":"CV 22 uses the suprasternal fossa at the neck base. CV 23 relates to the hyoid in the upper neck. Both are midline points with different levels and structures.","kind":"edited-comparison"},"shared":["Anterior Median Line"],"unique":["Suprasternal Fossa","Clavicle"],"primaryEn":"In the anterior region of the neck, in the centre of the suprasternal fossa, on the anterior median line.","primaryMeasures":[]},"CV 23":{"anchor":1,"compare":"CV 22","focus":{"he":"CV 22 מתוארת בגומה שמעל עצם החזה בבסיס הצוואר. CV 23 קשורה לעצם הלשון בחלק העליון של הצוואר. שתיהן בקו האמצע, אך בגבהים ובמבנים שונים.","en":"CV 22 uses the suprasternal fossa at the neck base. CV 23 relates to the hyoid in the upper neck. Both are midline points with different levels and structures.","kind":"edited-comparison"},"shared":["Anterior Median Line"],"unique":["Thyroid Cartilage","Hyoid Bone","Hyoid Tubercle","Mandible"],"primaryEn":"In the anterior region of the neck, superior to superior border to thyroid cartilage, in the depression superior to the hyoid bone, on the anterior median line.","primaryMeasures":[]},"CV 24":{"anchor":1,"compare":"GV 27","focus":{"he":"CV 24 קשורה לקפל שבין השפה התחתונה לסנטר. GV 27 נמצאת באזור השפה העליונה. שני המבטים קדמיים, אך מדובר בשתי שפות ובשני ציוני דרך נפרדים.","en":"CV 24 uses the mentolabial groove below the lower lip. GV 27 concerns the upper lip. Both are anterior, but the lip and landmark differ.","kind":"edited-comparison"},"shared":[],"unique":["Mentolabial Sulcus"],"primaryEn":"On the face, in the depression in the centre of the mentolabial sulcus.","primaryMeasures":[]}}};
